-- Recipes. Like the library, they have no owner and are read-only for users.
insert into public.recipes
  (themealdb_id, title, cuisine, instructions, prep_minutes, cook_minutes, base_servings,
   cost_bracket, diet_tags, source_url, image_url, image_credit, source_type)
select v.*, 'seed'
from (values
  ('53483', 'Acaraje black-eyed pea fritters with shrimp filling', 'Brazilian', '1. For the filling, blend half of the red onion with the ginger, the red chili and a pinch of salt until smooth.
2. Heat the 1 tbsp of oil in a frying pan and fry the paste for about 5 minutes. Add the shrimp, the chopped tomatoes and the cilantro, squeeze in the lime and season with salt. Cook for 3 minutes, until the shrimp are pink, then take it off the heat.
3. For the fritters, drain and rinse the black-eyed peas, then blend them with the garlic and the green chili until smooth.
4. Scrape the purée into a bowl and mix in the rest of the onion (finely chopped), the flour, salt, chili powder and baking powder. Roll the mixture into 16 balls.
5. Heat about 3 inches (8 cm) of oil in a wok or deep pan. When a small piece of bread sizzles in it, fry 4 or 5 balls at a time for 4 to 5 minutes, until golden and crisp. Drain on paper towels.
6. Split each fritter open, spoon in some of the shrimp filling and serve with hot sauce.', 20, 25, 4, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/caraje-black-eyed-pea-fritters-shrimp-filling', 'https://www.themealdb.com/images/media/meals/dxs5t71782678369.jpg', 'Photo from TheMealDB'),
  ('53158', 'Air fryer patatas bravas', 'Spanish', '1. Cut the potatoes into chunks, cover them with just-boiled water and let them soak for 30 minutes. Drain and let them dry for 5 minutes.
2. Heat the air fryer to 400°F (200°C). Toss the potatoes with 1 tbsp of the oil and 1/2 tsp each of salt and black pepper, then air-fry them for 20 to 30 minutes, until golden and crisp.
3. Meanwhile, heat the rest of the oil in a small pan over medium-low heat and cook the chopped onion for 8 to 10 minutes, until soft but not brown.
4. Add the garlic for 1 minute, then the paprika for 30 seconds. Stir in the tomato paste for 1 minute, add the canned tomatoes and simmer for 5 to 10 minutes, until slightly thicker.
5. Pile the potatoes on a plate, spoon the sauce over them and scatter with basil.', 40, 30, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/air-fryer-patatas-bravas', 'https://www.themealdb.com/images/media/meals/3m8yae1763257951.jpg', 'Photo from TheMealDB'),
  ('53169', 'Ajo blanco', 'Spanish', '1. Tear the bread into a bowl, pour 1 1/2 cups (350 ml) of water over it and let it soak for 10 minutes.
2. Put the bread and its water in a blender with the almonds, garlic, olive oil, vinegar, another 1 1/2 cups (350 ml) of water and 1 tsp of salt. Blend until very smooth.
3. Chill the soup for about 1 hour. Serve it cold with a drizzle of olive oil and some black pepper.', 75, 0, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/ajo-blanco', 'https://www.themealdb.com/images/media/meals/5jdtie1763289302.jpg', 'Photo from TheMealDB'),
  ('53282', 'Algerian Carrots', 'Algerian', '1. Slice the carrots. Bring the water to a boil in a saucepan with a steamer basket, add the carrots, cover and steam over medium heat for 4 to 6 minutes, until just tender. Keep 1/2 cup of the cooking water.
2. Warm the olive oil in a skillet over low heat with the salt, pepper, cinnamon, cumin, minced garlic and thyme. Cook gently for about 10 minutes, stirring often, until fragrant.
3. Pour in the saved cooking water, add the bay leaf, cover and simmer for 20 minutes.
4. Stir in the carrots and heat them through for 2 to 3 minutes. Remove the bay leaf, sprinkle with the lemon juice and serve.', 10, 35, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.allrecipes.com/recipe/99244/algerian-carrots/', 'https://www.themealdb.com/images/media/meals/o2cd4r1764113576.jpg', 'Photo from TheMealDB'),
  ('53288', 'Algerian Flafla (Bell Pepper Salad)', 'Algerian', '1. Heat the oven to 450°F (230°C). Roast the whole peppers on a sheet of foil for 30 to 45 minutes, turning them once, until the skins are blackened and the peppers are soft.
2. Let them cool for 10 minutes, then peel off the skins, remove the stems and seeds and cut the peppers into 1/2-inch pieces.
3. Heat the oil in a skillet over medium heat and cook the chopped onion for about 5 minutes, until soft.
4. Add the garlic, salt and pepper, then the peppers and the chopped tomato. Cook for about 5 minutes, stirring now and then, until the tomato is soft. Serve warm or cold.', 15, 50, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.allrecipes.com/recipe/153802/algerian-flafla-bell-pepper-salad/', 'https://www.themealdb.com/images/media/meals/tbj1bs1764118062.jpg', 'Photo from TheMealDB'),
  ('53281', 'Algerian Kefta (Meatballs)', 'Algerian', '1. Mix the ground beef with half of the minced garlic and 1 tbsp of the chopped onion, using your hands. Shape it into 12 to 14 small oval patties, about 1 1/2 inches long.
2. Brown the patties in batches in a large skillet over medium-high heat, about 10 minutes, until crisp outside and cooked through. Set them aside in a serving dish.
3. Lower the heat to medium, add the rest of the onion to the pan, season with salt and pepper and cook for about 5 minutes, until soft. Add the rest of the garlic for 30 seconds.
4. Stir in the chopped tomatoes and the parsley, pour in the water and cook for about 5 minutes, until the tomatoes are soft. Pour the sauce over the meatballs and serve.', 15, 25, 4, '$$', array[]::text[], 'https://www.allrecipes.com/recipe/153790/algerian-kefta-meatballs/', 'https://www.themealdb.com/images/media/meals/8rfd4q1764112993.jpg', 'Photo from TheMealDB'),
  ('53430', 'Antiguan Breakfast (Chop Up and ‘Saltfish’)', 'Caribbean', '1. Peel the eggplants and the pumpkin and cut them into medium pieces.
2. Melt the butter in a medium pot over medium-high heat. Cook the chopped onion and garlic for 2 minutes, until soft but not brown.
3. Add the pumpkin and eggplant and cook for 2 to 3 minutes more. Pour in water just to cover, bring to a boil, then simmer for about 15 minutes, until the vegetables are soft.
4. Stir in the chopped callaloo and cook for 3 minutes.
5. Drain the vegetables in a colander, return them to the pot and mash them well. Season with the salt and pepper and serve.', 15, 30, 6, '$', array['vegetarian']::text[], 'https://www.atastefortravel.ca/24626-antigua-chop-up/#recipe', 'https://www.themealdb.com/images/media/meals/jvjnoh1780086318.jpg', 'Photo from TheMealDB'),
  ('53439', 'Arepa', 'Caribbean', '1. Put the masarepa (precooked corn flour) in a bowl. Dissolve the salt in the warm water and add it little by little, mixing, until you have a soft dough. Let it rest for 5 minutes.
2. Shape the dough into rounds about 3 inches wide and 1/2 inch thick.
3. Heat the oven to 350°F (180°C). Cook the arepas slowly in a lightly oiled skillet until a crust forms on both sides.
4. Bake them for about 20 minutes, until they sound hollow when tapped.', 15, 30, 3, '$', array['vegan', 'vegetarian']::text[], 'https://www.visitaruba.com/aruba-recipes/arepa/', 'https://www.themealdb.com/images/media/meals/ejht7k1780092390.jpg', 'Photo from TheMealDB'),
  ('53147', 'Arroz con gambas y calamar', 'Spanish', '1. Peel and devein most of the shrimp, keeping a few whole to decorate if you like. Clean the squid and slice it into rings.
2. Heat the oil in a large frying pan or shallow casserole over medium-low heat and cook the chopped onion for 5 minutes, until soft. Add the bay leaf, saffron, rice and tomato paste and stir for 1 to 2 minutes.
3. Pour in the wine and let it bubble for 1 to 2 minutes, then add the seafood stock and 2/3 cup (150 ml) of water. Cook for 5 minutes.
4. Stir in the squid, season well and bring to a boil. Cover, lower the heat and simmer gently for 12 minutes, adding a splash of water if it looks dry.
5. Stir in the peeled shrimp and lay any whole ones on top. Cover and simmer for 5 to 6 minutes more, until the shrimp are pink. Let it stand for 2 minutes, then serve from the pan.', 25, 35, 6, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/arroz-con-gambas-y-calamar', 'https://www.themealdb.com/images/media/meals/jc6oub1763196663.jpg', 'Photo from TheMealDB'),
  ('53133', 'Asado', 'Argentinian', '1. Light a charcoal or wood grill and let it burn down to glowing coals. Without a grill, heat the oven to 400°F (200°C) instead.
2. Salt the beef generously just before cooking.
3. Grill the beef with the thickest cuts farthest from the heat, turning now and then, until it''s cooked the way you like it. Thin cuts take about 20 minutes and ribs up to 2 hours. In the oven, roast the beef on a rack.
4. Add the chorizo and morcilla for the last 20 to 30 minutes, turning them until browned and cooked through.
5. Let the meat rest for 10 minutes, then slice it. Serve with chimichurri, a tomato salad and crusty bread.', 30, 120, 8, '$$$', array[]::text[], 'https://www.munchery.com/blog/the-ten-iconic-dishes-of-argentina-and-how-to-cook-them-at-home/', 'https://www.themealdb.com/images/media/meals/kgfh3q1763075438.jpg', 'Photo from TheMealDB'),
  ('53278', 'Aubergine & hummus grills', 'Turkish', '1. Heat the broiler. Slice the eggplants, lay them in one layer on a large baking sheet, brush them lightly with the vegetable oil and season well.
2. Broil for about 15 minutes, turning twice and brushing with oil, until soft and cooked through. Meanwhile, blend the bread into crumbs, add 2 tsp of oil and pulse briefly to coat.
3. Spread a couple of teaspoons of hummus on each slice and press the hummus side into the crumbs. Broil crumb side up for about 3 minutes, until golden.
4. Toss the chopped walnuts, parsley and halved tomatoes with the lemon juice, olive oil and seasoning, and serve with the eggplant and more hummus.', 15, 20, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/aubergine-hummus-grills', 'https://www.themealdb.com/images/media/meals/zub3s91764110535.jpg', 'Photo from TheMealDB'),
  ('53267', 'Aubergine couscous salad', 'Turkish', '1. Heat the broiler to high. Cut the eggplant into thick slices, lay them on a baking sheet, brush with oil and season.
2. Broil for about 15 minutes, turning and brushing with more oil halfway, until browned and soft.
3. Meanwhile, put the couscous in a large bowl, pour the hot broth over it, cover and leave for 10 minutes.
4. Mix the halved tomatoes, chopped mint, crumbled goat cheese and the rest of the oil.
5. Fluff the couscous with a fork, then stir in the eggplant, the tomato mixture and the lemon juice.', 10, 15, 2, '$$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/aubergine-couscous-salad', 'https://www.themealdb.com/images/media/meals/02s6gc1763799560.jpg', 'Photo from TheMealDB'),
  ('53099', 'Aussie Burgers', 'Australian', '1. Put the beef in a bowl with 1 tsp of salt and plenty of black pepper. With wet hands, mix it and shape it into 4 burgers.
2. Slice the beets and split each naan in half.
3. Heat a grill pan over high heat. Toast the naan halves on both sides and set them aside.
4. Cook the burgers for 2 to 3 minutes on each side, or until cooked through.
5. Put a naan half on each plate with some arugula, then a burger, a few slices of beet and a spoonful of the sour cream dip. Season and serve.', 10, 15, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/aussie-burgers', 'https://www.themealdb.com/images/media/meals/44bzep1761848278.jpg', 'Photo from TheMealDB'),
  ('53050', 'Ayam Percik', 'Malaysian', '1. Blend the shallots, ginger, garlic, chilies, turmeric, cumin, coriander seeds and fennel seeds into a smooth paste.
2. Fry the paste in a skillet over medium heat for 10 minutes, until fragrant, adding a spoonful of water or oil if it gets too dry. Don''t let it burn.
3. Add the tamarind paste, coconut milk, water, sugar and a pinch of salt. Bring to a boil, then simmer over medium-low heat for 10 minutes, stirring now and then, until slightly reduced. Let it cool.
4. Pour the sauce over the chicken and marinate it in the fridge overnight, or for up to 2 days.
5. Heat the oven to 425°F (220°C). Spread some of the marinade on a greased baking sheet, lay the chicken on top so it covers the sauce, and spread the rest over the chicken.
6. Roast for 35 to 45 minutes, until cooked through (175°F inside). Let it rest for 5 minutes and serve with the sauce and steamed rice.', 20, 60, 4, '$$', array[]::text[], 'http://www.curiousnut.com/roasted-spiced-chicken-ayam-percik/', 'https://www.themealdb.com/images/media/meals/020z181619788503.jpg', 'Photo from TheMealDB'),
  ('53481', 'Bahia-style Moqueca prawn stew', 'Brazilian', '1. Mix the shrimp with 2 tbsp of the lime juice, 1 tsp of salt and 1 tbsp of the chopped garlic. Chill for 1 hour.
2. Heat the coconut oil in a large saucepan and cook the green onions and onion for 5 minutes. Add the sliced red pepper, pepper flakes, paprika and the rest of the garlic.
3. Add the chopped tomatoes, coconut milk and a little salt. Simmer for 10 minutes to thicken.
4. Add the shrimp with their marinade and the rest of the lime juice. Simmer gently for about 3 minutes, until the shrimp turn pink. Serve with the cilantro and rice.', 75, 25, 4, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/bahia-style-moqueca-prawn-stew', 'https://www.themealdb.com/images/media/meals/e2kcut1782591669.jpg', 'Photo from TheMealDB'),
  ('52807', 'Baingan Bharta', 'Indian', '1. Rub the eggplant with a little oil and roast it directly over a gas flame, turning it every 2 to 3 minutes, until the skin is charred and the inside is completely soft (a knife slides in easily). You can also roast it in a hot oven, with less smoky flavor.
2. Let it cool in a bowl of water, then peel off the skin and chop or mash the flesh.
3. Heat the oil in a pan and cook the chopped onion and garlic until soft and translucent, without browning. Add the chopped green chili for 1 minute.
4. Add the chopped tomatoes and cook, stirring, until the oil starts to separate from the mixture. Stir in the chili powder.
5. Add the eggplant, season with salt and cook for 4 to 5 minutes more, stirring well. Stir in the cilantro and serve with roti, chapati or rice.', 20, 25, 2, '$', array['vegan', 'vegetarian']::text[], 'http://www.vegrecipesofindia.com/baingan-bharta-recipe-punjabi-baingan-bharta-recipe/', 'https://www.themealdb.com/images/media/meals/urtpqw1487341253.jpg', 'Photo from TheMealDB'),
  ('52959', 'Baked salmon with fennel & tomatoes', 'British', '1. Heat the oven to 350°F (180°C). Trim the fennel, keeping the fronds. Cut each bulb in half and each half into 3 wedges.
2. Boil the fennel in salted water for 10 minutes and drain it well. Chop the fronds and mix them with the parsley and the lemon zest.
3. Spread the fennel in a shallow baking dish with the tomatoes, drizzle with the oil and bake for 10 minutes.
4. Nestle the salmon among the vegetables, sprinkle with lemon juice and bake for 15 minutes more, until the fish is just cooked.
5. Scatter the herb mixture over the top, add the olives if you like, and serve.', 15, 35, 2, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/7745/baked-salmon-with-fennel-and-tomatoes', 'https://www.themealdb.com/images/media/meals/1548772327.jpg', 'Photo from TheMealDB'),
  ('53548', 'Baked Yuca Fries', 'Cuban', '1. Heat the oven to 450°F (230°C) and bring a large pot of water to a boil.
2. Trim the yuca, cut each one in half across and cut off the waxy peel. Cut each piece lengthwise into quarters (16 pieces in all) and remove the woody center.
3. Boil the yuca for 8 to 10 minutes, until a fork goes in easily. Drain and pat dry.
4. Toss with the oil, chili powder, salt and pepper. Spread on a baking sheet and bake for about 25 minutes, turning halfway, until golden and crisp.
5. Meanwhile, blend the avocado, sour cream, lime juice and cilantro until smooth, and season. Serve the fries hot with the sauce.', 10, 40, 4, '$', array['vegetarian']::text[], 'https://www.delish.com/cooking/recipe-ideas/a36702083/yuca-fries-recipe/', 'https://www.themealdb.com/images/media/meals/j223gc1784579841.jpg', 'Photo from TheMealDB'),
  ('53440', 'Balchi di Pisca', 'Caribbean', '1. A day ahead, soak the salt cod in cold water for 24 hours, then drain it.
2. Cover the cod with fresh water and simmer gently for about 15 minutes, until it flakes easily. Drain, keeping a little of the cooking water, and remove any bones.
3. Peel and dice the potatoes, boil them until tender and drain them well. Mash them with the cod.
4. Blend the chopped tomato, green pepper, onion and garlic with the hot sauce, a pinch of nutmeg, salt and pepper for a few seconds. Mix it into the fish with the beaten egg.
5. The mixture should be firm enough to shape: add a spoonful of the cooking water if it''s too dry. Roll it into balls about 1 1/2 inches wide.
6. Deep-fry the balls in hot oil until golden brown, then drain them on paper towels.', 30, 40, 4, '$$', array['pescatarian']::text[], 'https://www.visitaruba.com/aruba-recipes/balchi-di-pisca/', 'https://www.themealdb.com/images/media/meals/qqwhw51780093126.jpg', 'Photo from TheMealDB'),
  ('53451', 'Bangladeshi fish curry with daikon', 'Bangladeshi', '1. Cut the fish into 2 1/2-inch chunks, rinse and drain. Peel the daikon, cut it lengthwise into quarters and slice it into 3/4-inch (2 cm) pieces. Blend the onion into a paste.
2. Heat the oil in a large, shallow pan over medium heat. Fry the crushed garlic for 1 minute, until pale golden.
3. Add the onion paste and salt and cook for 3 to 5 minutes, until soft. Pour in 3/4 cup (200 ml) of water, cover and cook for 10 minutes.
4. Stir in the turmeric, coriander and chili powder for 2 minutes, then cover and cook over low heat for 5 minutes.
5. Add the daikon and another 3/4 cup (200 ml) of water. Cover and cook over medium heat for 10 minutes.
6. Add the fish and gently coat it in the sauce. Cover and cook for 5 minutes. From now on, shake the pan instead of stirring, so the fish doesn''t break.
7. Pour 2 cups (500 ml) of hot water down the side of the pan, cover and simmer for 15 minutes. Add the cilantro and the sliced green chilies, cook for 5 minutes more and serve with rice and lime wedges.', 20, 55, 4, '$$', array['pescatarian']::text[], 'https://www.greatbritishchefs.com/recipes/bangladesh-fish-curry-recipe', 'https://www.themealdb.com/images/media/meals/r7mcjm1780261264.jpg', 'Photo from TheMealDB'),
  ('53103', 'Barramundi with Moroccan spices', 'Australian', '1. Blend the cumin, coriander, paprika, chili powder, garlic, lemon juice, olive oil, cilantro and a pinch of salt into a dressing.
2. Cut three slashes on each side of the fish, coat it with half of the dressing and let it marinate for 30 minutes.
3. Heat the oven to 425°F (220°C). Roast the fish on a tray for 20 minutes, until the flesh is firm.
4. Serve with the rest of the dressing and couscous or rice.', 40, 20, 2, '$$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/barramundi-moroccan-spices', 'https://www.themealdb.com/images/media/meals/4o4wh11761848573.jpg', 'Photo from TheMealDB'),
  ('52997', 'Beef Banh Mi Bowls with Sriracha Mayo, Carrot & Pickled Cucumber', 'Vietnamese', '1. Rinse the rice in a sieve until the water runs clear. Put it in a small pot with 2 cups of water and a pinch of salt, bring to a boil, then cover and cook over low heat for 15 minutes. Keep it covered off the heat for 10 minutes.
2. Meanwhile, chop the garlic, zest the lime and cut it into wedges, slice the cucumber into thin half-moons, dice the onion and grate the carrot.
3. Mix the cucumber with the juice of half the lime, 1/2 tsp of sugar and a pinch of salt. Mix the mayonnaise with a pinch of the garlic, a squeeze of lime and as much sriracha as you like.
4. Heat a little oil in a large pan over medium-high heat and cook the onion for 4 to 5 minutes. Add the beef, the garlic and 4 tsp of sugar and cook for 4 to 5 minutes, breaking up the meat, until browned. Stir in the soy sauce and season.
5. Fluff the rice and stir in the lime zest. Divide it between bowls and top with the beef, carrot and cucumber, a squeeze of lime and the sriracha mayo.', 15, 25, 4, '$$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/z0ageb1583189517.jpg', 'Photo from TheMealDB'),
  ('52904', 'Beef Bourguignon', 'French', '1. Heat 1 tbsp of the goose fat in a large casserole. Season the beef and brown it on all sides, 3 to 5 minutes per side, in 2 or 3 batches. Set it aside in a colander over a bowl.
2. In the same pan, fry the bacon, shallots, mushrooms, garlic and bouquet garni until lightly browned. Stir in the tomato paste for a few minutes, then return the beef and its juices.
3. Pour in the wine and about 1/2 cup (100 ml) of water, so the meat is almost covered. Bring to a boil, scraping up the browned bits from the bottom.
4. Heat the oven to 300°F (150°C). Cover the stew with a sheet of foil pressed onto its surface and cook in the oven for 3 hours. If the sauce is thin, lift out the meat and vegetables and boil the sauce for a few minutes to thicken it.
5. For the mash, peel and cube the celeriac. Fry it in the olive oil for 5 minutes, until golden, and season. Add the rosemary, thyme, 1 bay leaf and the cardamom pods, pour in about 3/4 cup (200 ml) of water, partly cover and simmer for 25 to 30 minutes.
6. Drain any water left, remove the herbs and cardamom, and crush the celeriac with a masher and a little olive oil. Serve the stew in bowls with the mash on top.', 20, 195, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/5032/beef-bourguignon', 'https://www.themealdb.com/images/media/meals/vtqxtu1511784197.jpg', 'Photo from TheMealDB'),
  ('52812', 'Beef Brisket Pot Roast', 'American', '1. Trim any large chunks of fat from the brisket, keeping a thin layer on one side. Score that fat in a criss-cross pattern, cutting through the fat but not the meat. Salt the brisket well and leave it at room temperature for 30 minutes.
2. Pat it dry and put it fat side down in a heavy, ovenproof pot over medium-high heat. Cook for 5 to 8 minutes, until the fat is browned, then turn it and brown the other side. Set it aside.
3. Add the chopped onions to the fat in the pot with a little salt and cook over high heat for 5 to 8 minutes, until lightly browned. Stir in the garlic for 1 to 2 minutes.
4. Heat the oven to 300°F (150°C). Tie the bay leaves, rosemary and thyme together. Put the brisket back in the pot with the onions around it, add the broth and the herbs and bring to a boil on the stove.
5. Cover and cook in the oven for 3 hours, turning the brisket every hour. Add the carrots and cook for 1 hour more, until the meat is falling-apart tender.
6. Meanwhile, boil the potatoes until tender. Move the brisket to a board, cover it with foil and remove the herbs. If you like, blend half of the onions and the cooking liquid with the mustard into a gravy.
7. Slice the meat across the grain and serve with the carrots, onions, potatoes and gravy.', 45, 270, 8, '$$', array[]::text[], 'http://www.simplyrecipes.com/recipes/beef_brisket_pot_roast/', 'https://www.themealdb.com/images/media/meals/ursuup1487348423.jpg', 'Photo from TheMealDB'),
  ('53317', 'Beef Empanadas', 'Uruguayan', '1. For the dough, stir the lard, warm water and salt in a large bowl. Add the flour and half of the oregano and knead for 5 minutes. Cover and let it rest for at least 30 minutes.
2. Hard-boil the eggs, then peel and dice them. Put the tomatoes in boiling water for 30 seconds, cool them, peel them and dice them.
3. Cook the crushed garlic and the diced onions in a little oil until soft, then set them aside. Dice the steak and brown it in the same pan over high heat.
4. Season the meat with the rest of the oregano, the paprika, pepper flakes and parsley, add the onions, garlic, tomatoes and green onions and simmer for a few minutes. Season with salt and pepper and stir in the eggs.
5. Heat the oven to 400°F (200°C). Roll out the dough thinly on a floured surface and cut 5-inch (12 cm) circles. Put 2 to 4 teaspoons of filling on each, wet the edges, fold into half-moons and seal with a fork.
6. Brush with the egg wash and bake on a lined baking sheet for about 25 minutes, until golden. Serve warm with chimichurri.', 60, 45, 6, '$$', array[]::text[], 'https://jennyisbaking.com/2019/10/25/traditionelle-uruguayische-empanadas/#recipe', 'https://www.themealdb.com/images/media/meals/dxpc7j1764370714.jpg', 'Photo from TheMealDB'),
  ('53421', 'BEEF LOK LAK (Lok Lak Sach Ko)', 'Cambodian', '1. Fry the eggs sunny side up and set them aside. Chop the garlic, wash and dry the lettuce, and thinly slice the onion and tomatoes.
2. Cut the beef into 1-inch (2 to 3 cm) cubes and mix it with the salt, palm sugar, wine, oyster sauce, soy sauce and sesame oil.
3. Heat the oil in a frying pan over high heat and fry the garlic until lightly browned. Add the beef with all of its marinade and cook for 5 to 7 minutes, depending on how rare you like it.
4. Toast the peppercorns in a dry pan over medium-low heat for 2 to 3 minutes, grind them and mix them with a pinch of salt and the lime juice for a dipping sauce.
5. Arrange the lettuce, tomatoes and onion on a plate, spoon the beef on top and finish with the fried eggs. Serve with the pepper sauce and steamed rice.', 20, 15, 4, '$$$', array[]::text[], 'https://www.chefnak.com/beef-lok-lak', 'https://www.themealdb.com/images/media/meals/t2b8bn1779737789.jpg', 'Photo from TheMealDB'),
  ('53068', 'Beef Mechado', 'Filipino', '1. Cut the beef into 2-inch cubes and the potato into large chunks.
2. Heat the oil in a large pot over medium heat and cook the crushed garlic and chopped onion until soft.
3. Add the beef and brown it on all sides.
4. Stir in the soy sauce, a squeeze of the lemon, the tomato paste, the water and the bay leaves. Bring to a boil, then cover and simmer over low heat for about 1 hour 15 minutes, until the beef is tender. Add a splash of water if it gets dry.
5. Add the potato and cook for 15 minutes more, until tender. Season with the pepper and salt and serve with rice.', 10, 90, 6, '$$', array[]::text[], 'https://panlasangpinoy.com/filipino-pinoy-food-tomato-sauce-beef-mechado-recipe/', 'https://www.themealdb.com/images/media/meals/cgl60b1683206581.jpg', 'Photo from TheMealDB'),
  ('53469', 'Beef pumpkin Stew', 'Botswanan', '1. Cut the beef into 1-inch chunks and toss them in the flour until coated on all sides.
2. Melt the butter in a large soup pot over medium-high heat. Brown the beef in small batches and set it aside in a bowl.
3. Add the onion and garlic to the pot and cook for 1 minute, scraping the bottom as you stir.
4. Return the beef and add the broth, pumpkin purée, Worcestershire sauce, salt and pepper. Bring to a boil, then lower the heat to medium-low and simmer for 3 hours, stirring now and then.
5. Add the cubed potatoes, sliced carrots and thyme sprigs, turn the heat up to medium and cook for 30 minutes more. Season to taste and serve.', 20, 220, 10, '$', array[]::text[], 'https://www.honeyandbirch.com/pumpkin-beef-stew-recipe/#recipe', 'https://www.themealdb.com/images/media/meals/k07k271782502861.jpg', 'Photo from TheMealDB'),
  ('52834', 'Beef stroganoff', 'Russian', '1. Heat the olive oil in a non-stick frying pan and cook the sliced onion over medium heat for about 15 minutes, until very soft, adding a splash of water if it sticks.
2. Add the crushed garlic for 2 to 3 minutes, then the butter. When it foams, add the sliced mushrooms and cook for about 5 minutes, until soft. Season and tip everything onto a plate.
3. Season the flour with a big pinch of salt and pepper and toss the sliced steak in it. Fry the steak for 3 to 4 minutes, until browned, adding a little oil if the pan is dry.
4. Return the onions and mushrooms. Whisk the crème fraîche, mustard and broth together, pour them in and cook over medium heat for about 5 minutes.
5. Scatter with parsley and serve with pasta or rice.', 10, 35, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/beef-stroganoff', 'https://www.themealdb.com/images/media/meals/svprys1511176755.jpg', 'Photo from TheMealDB'),
  ('52803', 'Beef Wellington', 'British', '1. Pulse the mushrooms with some salt and pepper in a food processor into a rough paste. Cook it in a pan over high heat for about 10 minutes, stirring often, until dry. Let it cool.
2. Season the beef and sear it in a hot pan with a little olive oil for 30 seconds on each side, just to brown it. Let it cool, then brush it all over with the mustard.
3. Lay the prosciutto slices on a sheet of plastic wrap, slightly overlapping. Spread the mushroom paste over them and put the beef in the middle. Using the plastic wrap, roll the ham tightly around the beef and twist the ends. Chill for 15 to 20 minutes.
4. Roll out the pastry on a floured surface into a large rectangle. Unwrap the beef and lay it in the center. Brush the pastry around it with egg yolk, fold the ends over and wrap the pastry around the beef, cutting off any excess.
5. Put it seam side down on a baking sheet, brush with egg yolk and chill for about 15 minutes. Heat the oven to 400°F (200°C).
6. Score the pastry lightly, brush it with egg yolk again and bake for 20 minutes. Lower the oven to 350°F (180°C) and bake for 15 minutes more. Let it rest for 10 to 15 minutes before slicing. The beef should still be pink in the middle.', 60, 50, 4, '$$$', array[]::text[], 'http://www.goodtoknow.co.uk/recipes/164868/Gordon-Ramsay-s-beef-Wellington', 'https://www.themealdb.com/images/media/meals/vvpprx1487325699.jpg', 'Photo from TheMealDB'),
  ('53313', 'Beetroot latkes', 'Ukrainian', '1. Heat the oven to 350°F (180°C). Grate the beets and mix them with the egg, flour, crushed garlic, caraway, cumin, lemon zest and a pinch of salt.
2. Heat the oil in a large non-stick pan and spoon in the mixture to make 6 round latkes. Fry them for 4 to 5 minutes on each side.
3. Move them to a baking sheet and bake for 10 minutes.
4. Mix the yogurt with the chopped mint. Toss the arugula and halved tomatoes with a squeeze of lemon, and serve with the latkes and the mint yogurt.', 25, 20, 2, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/beetroot-latkes', 'https://www.themealdb.com/images/media/meals/qwicc91764368097.jpg', 'Photo from TheMealDB'),
  ('53463', 'Belgian Meatballs in Liège Syrup Sauce', 'Belgian', '1. Mix the beef and pork with 1 finely chopped onion, the garlic, egg, breadcrumbs, 1 tbsp of the mustard, the parsley, salt and pepper. Shape into meatballs, as small or as large as you like.
2. Heat a little oil in a large pan and brown the meatballs on all sides. Set them aside.
3. Melt the butter in the same pan and cook the other 2 onions, sliced, until soft and lightly golden. Sprinkle in the brown sugar and let it melt.
4. Add the vinegar and scrape up the browned bits. Stir in the rest of the mustard and the Liège syrup, then pour in the broth (and a splash of beer if you like) and add the bay leaf. Stir until the sauce is glossy.
5. Return the meatballs, cover and simmer gently for 25 to 30 minutes, stirring now and then, until the sauce thickens. Taste and adjust, and serve with fries or mashed potatoes.', 20, 45, 4, '$$', array[]::text[], 'https://junedarville.com/belgian-meatballs.html', 'https://www.themealdb.com/images/media/meals/gjjlzc1782496055.jpg', 'Photo from TheMealDB'),
  ('53466', 'Belgian Waterzooi Chicken', 'Belgian', '1. Put the chicken, water and 1 garlic clove in a large saucepan and bring to a boil. Cover and simmer over low heat for 10 minutes. Lift out the chicken and keep the broth.
2. When the chicken is cool, dice the breast and pull the meat off the leg, without skin or bones. Cut the leeks, celery and carrot into thin strips and dice the potatoes.
3. Melt the butter with the rosemary and bay leaves in a large pan over medium heat. Add the vegetables, season with salt and pepper and cook for 3 minutes.
4. Add the chicken, cover and cook for 5 minutes. Pour in the cream and 1/2 cup (120 ml) of the broth, cover and cook for 20 minutes, until the potatoes are tender.
5. Whisk the egg yolk with 2 tbsp of the warm cream from the pan, stir it back in over very low heat to thicken the sauce, and remove the herbs. Season and serve hot.', 15, 40, 2, '$$', array[]::text[], 'https://junedarville.com/waterzooi.html', 'https://www.themealdb.com/images/media/meals/nmxec11782498644.jpg', 'Photo from TheMealDB'),
  ('53453', 'Bengali Chicken Curry with Potatoes', 'Bangladeshi', '1. Heat the oil in a large skillet over medium-high heat and cook the chopped onions for about 5 minutes, until translucent. Add the ginger-garlic paste and cook for 5 minutes more.
2. Lower the heat to medium, add the chopped tomatoes and cook for 5 to 10 minutes, until pulpy. Stir in the cayenne, curry powder, garam masala, turmeric and cumin and cook for 5 minutes.
3. Add the diced chicken and potatoes and simmer, stirring now and then, for about 20 minutes, until the potatoes are tender and the chicken is cooked through.
4. Sprinkle with the cilantro, simmer for 10 minutes more and serve hot.', 10, 50, 4, '$$', array[]::text[], 'https://www.allrecipes.com/recipe/215055/bengali-chicken-curry-with-potatoes/', 'https://www.themealdb.com/images/media/meals/9ya6o71780262651.jpg', 'Photo from TheMealDB'),
  ('52979', 'Bitterballen (Dutch meatballs)', 'Dutch', '1. Melt the butter in a pan and stir in half of the flour, little by little, into a thick paste. Slowly stir in the broth until smooth, then simmer over low heat for a couple of minutes.
2. Stir in the finely chopped onion, the parsley and the cooked, shredded beef, and season with salt, pepper and nutmeg. It should become a very thick sauce.
3. Spread it in a shallow container, cover and chill for several hours, until firm.
4. Roll heaped tablespoons of the mixture into small balls. Roll each one in the rest of the flour, then in the beaten eggs, then in the breadcrumbs, making sure the egg covers it completely. Chill them while the oil heats.
5. Heat oil for deep-frying to 375°F (190°C) and fry 4 balls at a time until golden. Serve with a grainy mustard.', 30, 30, 6, '$$', array[]::text[], 'https://www.holland.com/global/tourism/information/traditional-dutch-food/bitterballen.htm', 'https://www.themealdb.com/images/media/meals/lhqev81565090111.jpg', 'Photo from TheMealDB'),
  ('53482', 'Black bean & meat stew - feijoada', 'Brazilian', '1. Soak the black beans in cold water overnight, then drain them.
2. Fry the bacon in a large heavy pan with a lid until crisp, then lift it out, keeping the fat. Brown the ribs, sliced chorizo and cubed pork shoulder in batches, seasoning each batch, and set them aside.
3. Add the chopped onions, garlic and pepper flakes to the pan, with a little oil if needed. Season and cook for 8 minutes, until soft.
4. Return all the meat and add the bay leaves and beans. Pour in just enough water to cover, about 2 3/4 cups (650 ml), and bring to a boil.
5. Cover and simmer over low heat for 2 hours, until the beans are soft and the meat is tender. If there''s too much liquid, take the lid off for the last hour. Serve with rice, chopped parsley, hot sauce and orange slices.', 15, 140, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/black-bean-meat-stew-feijoada', 'https://www.themealdb.com/images/media/meals/xrxz7h1782592711.jpg', 'Photo from TheMealDB'),
  ('53536', 'Black Beans Hotpot', 'Costa Rican', '1. Soak the dried beans in cold water overnight, then drain them.
2. Put the beans in a large pot with the chopped onion, bell peppers, celery and garlic, the cumin, oregano, salt, pepper and water.
3. Bring to a boil, then cover and simmer over low heat for 1 1/2 hours, until the beans are very soft. Add more water if they get dry. (In a pressure cooker, cook on high for 35 minutes and let the pressure release on its own.)
4. Taste, adjust the seasoning and serve.', 10, 90, 6, '$', array['vegan', 'vegetarian']::text[], 'https://www.recipesfromcostarica.com/recipes', 'https://www.themealdb.com/images/media/meals/81ahfr1784394567.jpg', 'Photo from TheMealDB'),
  ('53080', 'Blini Pancakes', 'Russian', '1. Whisk the buckwheat flour, all-purpose flour, salt and yeast in a large bowl. Make a well in the middle and whisk in the warm milk until smooth.
2. Cover and let the batter rise for about 1 hour, until doubled.
3. Separate the egg. Stir 2 tbsp of the butter (melted) and the egg yolk into the batter. Whisk the egg white until stiff and fold it in gently. Cover and let it stand for 20 minutes.
4. Heat a little butter in a large non-stick skillet over medium heat. Drop in small spoonfuls of batter and cook for about 1 minute, until bubbles form, then turn and cook for 30 seconds more.
5. Keep the blini warm under a towel while you cook the rest, adding more butter to the pan as needed.', 90, 20, 4, '$', array['vegetarian']::text[], 'https://www.thespruceeats.com/russian-blini-recipe-buckwheat-pancakes-1136797', 'https://www.themealdb.com/images/media/meals/0206h11699013358.jpg', 'Photo from TheMealDB'),
  ('53401', 'Bolani with Potato Filling', 'Afghan', '1. Mix the flour and 1 tsp of the salt in a bowl and slowly add the water to make a stiff dough. Knead for 5 to 10 minutes, until smooth and elastic. Cover with a damp cloth and let it rest for at least 30 minutes.
2. Peel the potatoes and boil them in salted water until soft. Drain and mash them well, then mix in the chopped green onions, the rest of the salt and the pepper.
3. Divide the dough into 3 or 4 balls and roll each one out as thin as you can on a floured surface. Cut out 5 to 6-inch (13 to 15 cm) circles.
4. Spread 1 to 2 tablespoons of potato over each circle, wet the edges, fold them over and press to seal.
5. Shallow-fry the bolani 1 or 2 at a time in hot oil until browned on both sides. Keep them warm until all are done and serve right away.', 60, 30, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.afghanaid.org.uk/brilliant-bolani-with-potato-filling', 'https://www.themealdb.com/images/media/meals/de0sns1779555283.jpg', 'Photo from TheMealDB'),
  ('53311', 'Borsch', 'Ukrainian', '1. For the broth, put the beef, 1 whole onion, the bay leaf and 8 cups (2 liters) of lightly salted cold water in a large saucepan. Simmer over very low heat for about 1 1/2 hours, until the beef falls apart, skimming the top now and then. Break up the beef and remove the onion.
2. Add the diced potatoes, season well and cook for 10 to 15 minutes, until tender.
3. Meanwhile, heat the oil in a deep frying pan and cook the other onion and the carrot, both diced, over medium heat until soft. Add the grated beets and cook for about 5 minutes, then the diced red pepper for 2 minutes.
4. Add the tomatoes and chopped prunes, turn up the heat and boil to reduce slightly, then stir everything into the soup.
5. Add the shredded cabbage and the beans and cook for 7 to 10 minutes, until tender. Serve with a spoonful of crème fraîche, plenty of chopped dill and crusty bread.', 20, 120, 6, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/borsch', 'https://www.themealdb.com/images/media/meals/804v1j1764367088.jpg', 'Photo from TheMealDB'),
  ('52914', 'Boulangère Potatoes', 'French', '1. Heat the oven to 400°F (200°C). Thinly slice the onions and the potatoes.
2. Fry the onions and thyme sprigs in the oil for about 5 minutes, until soft and lightly golden.
3. Oil a 6-cup (1.5 liter) baking dish. Layer the potatoes with a few onions between each layer, finishing with potatoes.
4. Pour the broth over the top and bake for 50 to 60 minutes, until the potatoes are cooked and the top is golden and crisp.', 20, 60, 8, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/5056/boulangre-potatoes', 'https://www.themealdb.com/images/media/meals/qywups1511796761.jpg', 'Photo from TheMealDB'),
  ('52826', 'Braised Beef Chilli', 'Mexican', '1. Heat the oven to 250°F (120°C). Take the beef out of the fridge. Pulse the onions and garlic in a food processor until finely chopped.
2. Heat 2 tbsp of olive oil in a large casserole and brown the beef on all sides. Set it aside, add a little more oil and brown the sliced chorizo, then set it aside too.
3. Cook the onion and garlic with the cumin, allspice, cloves, cinnamon, bay leaves, oregano and ancho chilies in the chorizo oil until soft. Season and stir in the vinegar, tomatoes, ketchup and sugar.
4. Return the meat with 1 2/3 cups (400 ml) of water (or red wine), bring to a simmer, cover and cook in the oven for 2 hours.
5. Add the drained beans and cook for 1 hour more. Pull the meat apart with two forks just before serving.', 15, 190, 6, '$$', array[]::text[], 'http://www.telegraph.co.uk/food-and-drink/recipes/braised-beef-chilli-con-carne/', 'https://www.themealdb.com/images/media/meals/uuqvwu1504629254.jpg', 'Photo from TheMealDB'),
  ('53305', 'Braised stuffed cabbage', 'Polish', '1. Heat the oven to 350°F (180°C). Cut the tough stalk out of the cabbage leaves. Cook them in boiling salted water for 1 to 2 minutes, until they start to wilt, then cool them under cold water and pat dry.
2. Fry the chopped onion in the oil for 5 minutes, until lightly browned. Add the rosemary and the chopped celery and cook for 8 minutes more.
3. Stir in the rice for about 1 minute, until glossy. Take it off the heat, stir in the chopped chestnuts and the cranberries and season.
4. Spoon some of the filling onto each leaf, fold in the sides and roll it up. Put the rolls seam side down in a single layer in an oiled baking dish.
5. Mix the broth, vinegar and honey and pour it over. Cover tightly with foil and bake for 1 hour, then uncover and bake for 15 minutes more.', 30, 75, 3, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/braised-stuffed-cabbage', 'https://www.themealdb.com/images/media/meals/z267f71764364072.jpg', 'Photo from TheMealDB'),
  ('53533', 'Breaded Steak Recipe (Lomo de Res Apanado)', 'Colombian', '1. Put each piece of steak between two sheets of plastic and pound it with a mallet until it''s 1/4 to 1/2 inch thick.
2. Put the steaks in a dish with the aliños sauce and marinate in the fridge for 3 hours or overnight.
3. Mix the flour, breadcrumbs, cumin, parsley, salt and pepper on a plate, and beat the eggs in a bowl.
4. Coat each steak in the flour mixture, then the egg, then the flour mixture again.
5. Heat oil in a large skillet over medium heat until it just starts to smoke. Fry the steaks for 3 to 4 minutes on each side, until golden, then drain them on paper towels and serve.', 30, 20, 6, '$$', array[]::text[], 'https://www.mycolombianrecipes.com/breaded-steak-lomo-de-res-apanado/#recipe', 'https://www.themealdb.com/images/media/meals/lmwaf61783805434.jpg', 'Photo from TheMealDB'),
  ('53458', 'Breadfruit in Butter Sauce', 'Caribbean', '1. Cut the breadfruit, remove the core and seeds and peel it. Boil it in salted water with a piece of onion and a little oil until tender, then drain and let it cool.
2. Meanwhile, melt the butter in a frying pan and lightly brown the onions, sliced into rings.
3. Add the garlic, tomatoes, parsley, lime juice, salt and pepper and cook for a couple of minutes. Pour in the water, bring to a boil and simmer for 5 to 10 minutes.
4. Slice the breadfruit into a serving dish, pour the butter sauce over it and add pepper sauce to taste. Garnish with chopped parsley.', 15, 35, 4, '$', array['vegetarian']::text[], 'https://www.totallybarbados.com/articles/barbados-recipes/breadfruit-butter-sauce-recipe/', 'https://www.themealdb.com/images/media/meals/6utn1w1782237402.jpg', 'Photo from TheMealDB'),
  ('52965', 'Breakfast Potatoes', 'Canadian', '1. Dice the potatoes and keep them in a bowl of water so they don''t brown. Chop the bacon (it''s easier if you freeze it for a few minutes first).
2. Heat the oil in a large skillet over medium-high heat. Drain the potatoes, add them to the pan and season with salt, pepper and a pinch of allspice.
3. Cook for 10 minutes, stirring often, until browned, adding a little more oil if needed.
4. Add the bacon and cook for 5 to 6 minutes, until crisp. Lower the heat to medium-low, add the minced garlic and parsley and cook for about 1 minute, until fragrant.
5. Drizzle the maple syrup over the potatoes, toss and cook for 1 minute more. Serve warm.', 10, 20, 2, '$', array[]::text[], 'http://www.vodkaandbiscuits.com/2014/03/06/bangin-breakfast-potatoes/', 'https://www.themealdb.com/images/media/meals/1550441882.jpg', 'Photo from TheMealDB'),
  ('52842', 'Broccoli & Stilton soup', 'British', '1. Heat the oil in a large saucepan and cook the chopped onion over medium heat until soft, adding a splash of water if it starts to stick.
2. Add the chopped celery, leek and potato and the butter. Stir until the butter melts, then cover and let the vegetables sweat for 5 minutes.
3. Pour in the broth, add the chopped broccoli stalk and cook for 10 to 15 minutes, until everything is soft.
4. Add the broccoli florets and cook for 5 minutes more. Blend until smooth, then stir in the crumbled Stilton, leaving a few lumps. Season with black pepper and serve.', 10, 35, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/1940679/broccoli-and-stilton-soup', 'https://www.themealdb.com/images/media/meals/tvvxpv1511191952.jpg', 'Photo from TheMealDB'),
  ('52940', 'Brown Stew Chicken', 'Jamaican', '1. Cut the chicken into pieces. Squeeze the lime over it, rub it in well and drain off the juice.
2. Mix the chicken in a large bowl with the chopped tomato, onions, garlic and red pepper, the thyme, allspice and soy sauce. Cover and marinate for at least 1 hour.
3. Heat the oil in a heavy pot. Lift the chicken out of the marinade, shaking off the vegetables, and keep the marinade. Brown the chicken a few pieces at a time in the very hot oil.
4. Drain off the extra oil and return all the chicken. Pour in the marinade, add the sliced carrot and cook over medium heat for 10 minutes.
5. Mix the cornstarch into the coconut milk and stir it into the stew. Turn the heat to low and cook for 20 minutes more, until the chicken is tender.', 75, 45, 4, '$$', array[]::text[], 'http://www.geniuskitchen.com/recipe/authentic-jamaican-brown-stew-chicken-347996', 'https://www.themealdb.com/images/media/meals/sypxpx1515365095.jpg', 'Photo from TheMealDB'),
  ('53492', 'Bulgarian Green Salad', 'Bulgarian', '1. Slice the lettuce into a large bowl and add the sliced radishes, cucumber and green onions.
2. Drizzle with the vinegar and olive oil, season with salt and toss gently.
3. Scatter with chopped dill and parsley and serve right away.', 10, 0, 4, '$', array['vegan', 'vegetarian']::text[], 'https://cookinglsl.com/bulgarian-green-salad-recipe/#wprm-recipe-container-24454', 'https://www.themealdb.com/images/media/meals/6awyvm1782685205.jpg', 'Photo from TheMealDB'),
  ('53077', 'Cabbage Soup (Shchi)', 'Russian', '1. Melt the butter in a large heavy pot over medium heat and cook the chopped onion until translucent.
2. Add the shredded cabbage and the chopped carrot and celery and cook for about 3 minutes, stirring often, until they start to soften.
3. Add the bay leaf and broth and bring to a boil. Cover and simmer over low heat for about 15 minutes.
4. Add the diced potatoes, bring back to a boil and simmer, covered, for about 10 minutes, until tender.
5. Add the chopped tomatoes, bring back to a boil and simmer uncovered for 5 minutes. Season with salt and pepper and remove the bay leaf.
6. Serve topped with sour cream and fresh dill.', 15, 40, 6, '$', array['vegetarian']::text[], 'https://www.thespruceeats.com/traditional-russian-cabbage-soup-shchi-recipe-1135534', 'https://www.themealdb.com/images/media/meals/60oc3k1699009846.jpg', 'Photo from TheMealDB'),
  ('53488', 'Cabbage with Ground Beef', 'Bulgarian', '1. Heat the oil in a large skillet or braiser over medium heat. Add the beef and cook for 3 to 4 minutes, breaking it into small pieces, until browned.
2. Stir in the chopped onion, carrots, red pepper and garlic and the tomato paste. Season with the salt, pepper, smoked paprika and cumin and cook for 2 to 3 minutes, stirring often.
3. Add the chopped cabbage, vinegar and water and stir well. Cover and cook over medium-low heat for 30 minutes, stirring now and then.
4. If there''s too much liquid, uncover and cook over medium-high heat for 5 to 7 minutes more. Sprinkle with parsley and serve.', 10, 40, 6, '$', array[]::text[], 'https://cookinglsl.com/ground-beef-cabbage-recipe/#wprm-recipe-container-59951', 'https://www.themealdb.com/images/media/meals/brmxra1782681940.jpg', 'Photo from TheMealDB'),
  ('52819', 'Cajun spiced fish tacos', 'Mexican', '1. Mix the Cajun seasoning and cayenne with a little salt and pepper on a large plate and coat the fish all over.
2. Heat the oil in a frying pan and cook the fish over medium heat until golden. Lower the heat and cook for about 10 minutes in all, until cooked through. Cook it in batches if needed.
3. For the dressing, mix the sour cream with the lemon juice, the crushed garlic and a little salt and pepper.
4. Warm the tortillas in the microwave for 5 to 10 seconds. Fill them with sliced avocado, shredded lettuce and green onions, a spoonful of salsa and large flakes of fish, and drizzle with the dressing.', 15, 15, 4, '$$', array['pescatarian']::text[], 'https://realfood.tesco.com/recipes/cajun-spiced-fish-tacos.html', 'https://www.themealdb.com/images/media/meals/uvuyxu1503067369.jpg', 'Photo from TheMealDB'),
  ('53428', 'Camaro Grelhado Com Molho Cru (Grilled Prawns with Green Onion Sauce)', 'Angolan', '1. For the sauce, grind or blend the garlic, green onions, cumin, salt, vinegar and water into a paste.
2. Thread the shrimp onto skewers and brush them with some of the sauce.
3. Cook on a hot grill pan or barbecue for 3 to 4 minutes on each side, until they are no longer see-through.
4. Serve with the rest of the sauce on the side.', 15, 10, 4, '$$', array['pescatarian']::text[], 'https://www.196flavors.com/wprm_print/camarao-grelhado-com-molho-cru', 'https://www.themealdb.com/images/media/meals/jg4r991779916649.jpg', 'Photo from TheMealDB'),
  ('53418', 'Cambodian Stir-fried Morning Glory with Pork, Fermented Soybeans, and Garlic', 'Cambodian', '1. Cut the morning glory into 2-inch pieces and chop the garlic.
2. Heat 1 tbsp of oil in a wok over medium heat and stir-fry the garlic for about 30 seconds, until fragrant.
3. Add the pork and break it up. Stir-fry for 2 to 3 minutes, until browned and cooked through.
4. Stir in the fermented beans and cook for 1 minute more.
5. Add the morning glory and the sliced chili and stir-fry for 2 to 3 minutes, so it stays bright green and crisp. Season with fish sauce and a pinch of sugar and serve right away with rice.', 10, 10, 2, '$', array[]::text[], 'https://mitziemee.com/recipe-cambodian-stir-fried-morning-glory/', 'https://www.themealdb.com/images/media/meals/wympxc1779734808.jpg', 'Photo from TheMealDB'),
  ('53576', 'Carrot and Bean Fritters', 'Estonian', '1. Heat the oven to 400°F (200°C). Drain the beans.
2. Grate the carrots and mash them with the beans, the flour and the crushed garlic. Season with thyme, chopped parsley, salt and pepper.
3. Shape the mixture into small patties and press each one into the breadcrumbs.
4. Fry the patties in hot oil for a few minutes on each side, until browned.
5. Move them to a lined baking sheet and bake for 10 minutes.', 20, 20, 4, '$', array['vegan', 'vegetarian']::text[], 'https://estoniancuisine.com/2021/01/15/carrot-and-bean-fritters-porgandi-oakotletid/#more-12384', 'https://www.themealdb.com/images/media/meals/xjii2g1784836867.jpg', 'Photo from TheMealDB'),
  ('53330', 'Cassava pizza', 'Venezuelan', '1. Heat the oven to 400°F (200°C). Cut the chorizo into pieces and the pepper into strips.
2. Spread a little tomato sauce and mozzarella over each piece of cassava bread.
3. Top with the chorizo, ham, corn, olives and pepper.
4. Bake for 7 to 10 minutes and serve hot.', 10, 10, 3, '$$', array[]::text[], 'https://goya.es/en/recipes/cassava-pizza', 'https://www.themealdb.com/images/media/meals/lrfdwz1764438393.jpg', 'Photo from TheMealDB'),
  ('53055', 'Cevapi Sausages', 'Croatian', '1. Put the beef and pork in a bowl with the very finely chopped onion, grated garlic, parsley, paprika, baking powder, breadcrumbs, water, crumbled stock cube, salt and pepper.
2. Mix very well, cover and chill for 1 hour.
3. Shape portions of about 1/4 cup into rolls as thick as your thumb and 3 to 4 inches long. You should have about 18.
4. Cook them on a hot grill pan or barbecue for 12 to 14 minutes, turning often, until browned and cooked through. Serve hot.', 90, 15, 4, '$$', array[]::text[], 'https://whereismyspoon.co/cevapi-or-cevapcici-recipe-grilled-sausages-croatian-food/', 'https://www.themealdb.com/images/media/meals/vc08jn1628769553.jpg', 'Photo from TheMealDB'),
  ('53290', 'Cheese Borek', 'Algerian', '1. Whisk the egg with the chopped parsley, garlic and pepper flakes, then mix in the grated cheeses.
2. Lay one sheet of filo on a work surface, brush it with about 1 tbsp of the melted butter and cut it lengthwise into 4 strips.
3. Put a rounded teaspoon of filling at one end of each strip. Fold the corner over the filling to make a triangle and keep folding along the strip. Repeat with all the filo.
4. Heat the oven to 350°F (175°C) and butter a large baking sheet. Lay the triangles on it in one layer.
5. Bake for about 30 minutes, until lightly browned, and serve warm.', 40, 30, 6, '$$', array['vegetarian']::text[], 'https://www.allrecipes.com/recipe/26728/cheese-borek/', 'https://www.themealdb.com/images/media/meals/oal8x31764119345.jpg', 'Photo from TheMealDB'),
  ('52846', 'Chicken & mushroom Hotpot', 'British', '1. Heat the oven to 400°F (200°C). Thinly slice the potatoes and boil them for 5 minutes, then drain. Melt the butter in a saucepan over medium heat and cook the chopped onion for 5 minutes, then add the sliced mushrooms.
2. When they''re almost cooked, stir in the flour and crumble in the stock cube. Stir over low heat for 2 minutes.
3. Take it off the heat and slowly stir in 2 cups (500 ml) of water. Season with pepper and a pinch each of nutmeg and mustard powder, then bring to a boil, stirring, until the sauce thickens.
4. Stir in the cooked, diced chicken and the corn and pour everything into a buttered baking dish.
5. Lay the potato slices on top, slightly overlapping, brush them with a little melted butter and bake for about 35 minutes, until golden.', 25, 35, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/chicken-mushroom-hot-pot', 'https://www.themealdb.com/images/media/meals/uuuspp1511297945.jpg', 'Photo from TheMealDB'),
  ('52796', 'Chicken Alfredo Primavera', 'Italian', '1. Heat 1 tbsp of the butter and 2 tbsp of the oil in a large skillet over medium-high heat. Season the chicken breasts with salt and pepper and cook for 5 to 7 minutes on each side, until cooked through. Let them rest on a board.
2. Meanwhile, cook the pasta in a large pot of salted boiling water for about 12 minutes, until al dente. Keep 1/2 cup of the pasta water and drain.
3. Lower the heat to medium and add the rest of the butter and oil to the skillet. Add the chopped squash, broccoli, mushrooms, bell pepper and onion and the pepper flakes, and cook for about 5 minutes, stirring often, until tender.
4. Add the garlic with a pinch of salt and pepper for 1 minute. Pour in the wine and let it reduce by half, about 3 minutes.
5. Stir in the milk, cream and pasta water and simmer for 2 to 3 minutes. Turn off the heat and stir in the parmesan, the pasta and the sliced chicken. Season and serve with parsley.', 15, 35, 6, '$$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/syqypv1486981727.jpg', 'Photo from TheMealDB'),
  ('53459', 'Chicken and Potato Roti', 'Caribbean', '1. Melt 3 tbsp of sugar in a large saucepan over high heat until it caramelizes, then add the cubed chicken and stir until browned.
2. Add the chopped onions, garlic and parsley, the thyme, jerk seasoning, salt, pepper and the whole Scotch bonnet (don''t cut it). Lower the heat and simmer for 25 minutes.
3. Meanwhile, for the roti, sift the flour with a pinch of salt. Rub in the shortening, 1 tbsp at a time, until it looks like breadcrumbs. Mix in small amounts of water until you have a soft dough.
4. Roll the dough out on a floured surface into at least 12 very thin rounds and cover them with a towel.
5. Add 1 1/4 cups of water and the cubed potatoes to the chicken, cover and cook over low heat for 30 minutes. Remove the Scotch bonnet.
6. Cook each roti on a hot, dry griddle for about 1 minute on each side, until browned but not crisp. To serve, spoon some filling onto each roti and fold it around.', 40, 75, 6, '$$', array[]::text[], 'https://www.totallybarbados.com/articles/barbados-recipes/chicken-potato-roti-recipe/', 'https://www.themealdb.com/images/media/meals/mp9z0i1782238092.jpg', 'Photo from TheMealDB'),
  ('52850', 'Chicken Couscous', 'Moroccan', '1. Heat the oil in a large frying pan and cook the chopped onion for 1 to 2 minutes, until soft.
2. Add the diced chicken and fry for 7 to 10 minutes, until cooked through and the onion is golden. Grate in the ginger, stir in the harissa and cook for 1 minute more.
3. Add the apricots, drained chickpeas and couscous, pour in the broth and stir once.
4. Cover tightly and leave for about 5 minutes, until the couscous has soaked up the broth. Fluff it with a fork and scatter with cilantro. Serve with extra harissa if you like.', 10, 20, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/13139/onepan-chicken-couscous', 'https://www.themealdb.com/images/media/meals/qxytrx1511304021.jpg', 'Photo from TheMealDB'),
  ('52765', 'Chicken Enchilada Casserole', 'Mexican', '1. Cut each chicken breast into 3 pieces and put them in a small pot with the enchilada sauce. Cover and cook over low to medium heat for about 20 minutes, stirring now and then, until cooked through.
2. Lift out the chicken and shred it with two forks. Heat the oven to 375°F (190°C).
3. Spread about 1/4 cup of the sauce in a baking dish. Layer 2 tortillas, a third of the chicken, a third of the remaining sauce and a third of the cheese. Repeat twice.
4. Bake uncovered for 20 to 30 minutes, until bubbling and browned on top. Serve warm.', 10, 50, 4, '$$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/qtuwxu1468233098.jpg', 'Photo from TheMealDB'),
  ('52818', 'Chicken Fajita Mac and Cheese', 'American', '1. Fry the sliced onion and peppers and the garlic in the olive oil until soft.
2. Push the vegetables to the side and add the diced chicken. Add the fajita seasoning and salt and cook until the chicken colors slightly.
3. Add the cream, broth and macaroni and cook over low heat for 20 minutes, stirring now and then, until the pasta is tender.
4. Stir in the cheese until melted and serve topped with parsley.', 10, 30, 6, '$$', array[]::text[], 'http://twistedfood.co.uk/chicken-fajita-mac-n-cheese/', 'https://www.themealdb.com/images/media/meals/qrqywr1503066605.jpg', 'Photo from TheMealDB'),
  ('52875', 'Chicken Ham and Leek Pie', 'British', '1. Heat the broth in a saucepan, add the chicken, cover and simmer gently for 10 minutes. Lift out the chicken and keep the broth.
2. Melt 2 tbsp (25 g) of the butter in a large heavy pan over low heat and cook the sliced leeks for 2 minutes, then the garlic for 1 minute. Add another 4 tbsp (50 g) of butter and, once it melts, stir in 3 tbsp of the flour for 30 seconds.
3. Slowly stir in the milk, a little at a time, then 1 cup (250 ml) of the broth and the wine, until smooth. Simmer for 3 minutes, season, stir in the cream and let it cool, covered.
4. Heat the oven to 400°F (200°C) with a baking sheet inside. For the pastry, pulse the rest of the flour and butter in a food processor into fine crumbs, then add 1 beaten egg and the water until it forms a ball. Keep a third for the lid.
5. Roll out the rest about 1/4 inch thick and line a pie dish with it. Cut the chicken into 1-inch pieces and stir it into the sauce with the diced ham. Pour it into the dish.
6. Brush the rim with beaten egg, roll out the lid and press it on to seal. Cut a small hole in the middle, brush with egg and bake on the hot sheet for 35 to 40 minutes, until golden.', 45, 60, 6, '$$', array[]::text[], 'https://www.bbc.co.uk/food/recipes/creamy_chicken_ham_and_03877', 'https://www.themealdb.com/images/media/meals/xrrtss1511555269.jpg', 'Photo from TheMealDB'),
  ('52795', 'Chicken Handi', 'Indian', '1. Heat the oil in a large pot or wok and fry the sliced onions until deep golden brown. Lift them out and set them aside.
2. Fry the chopped garlic in the same pot for 1 minute, then add the chopped tomatoes and cook for about 5 minutes, until soft.
3. Return the onions and stir in the ginger paste. Add the cumin seeds, half of the coriander seeds and the chopped green chilies, then the turmeric and chili powder, and cook for a couple of minutes.
4. Add the chicken pieces, season with salt, cover and cook over medium-low heat for about 15 minutes, until almost cooked through. Don''t rush this step.
5. When the oil separates from the spices, lower the heat as far as it goes and stir in the beaten yogurt so it doesn''t split. Add the rest of the coriander seeds and half of the fenugreek.
6. Stir in the cream, sprinkle with the rest of the fenugreek and the garam masala, and serve hot with naan or roti.', 15, 50, 6, '$$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/wyxwsp1486979827.jpg', 'Photo from TheMealDB'),
  ('52879', 'Chicken Parmentier', 'French', '1. For the topping, boil the potatoes in salted water until tender. Drain, mash them well and stir in half of the butter, the cream and the egg yolks. Season.
2. For the filling, melt the rest of the butter in a large pan and gently fry the chopped shallots, carrots and celery until soft. Add the garlic.
3. Pour in the wine for 1 minute, then stir in the tomato paste, tomatoes and broth and cook for 10 to 15 minutes, until thickened. Add the cooked, shredded chicken, the olives and parsley and season.
4. Heat the oven to 350°F (180°C). Put the filling in an 8 x 12-inch baking dish, cover it with the mashed potato and grate the Gruyère over the top.
5. Bake for 30 to 35 minutes, until piping hot and golden.', 30, 60, 6, '$$', array[]::text[], 'https://www.bbc.co.uk/food/recipes/chicken_parmentier_25434', 'https://www.themealdb.com/images/media/meals/uwvxpv1511557015.jpg', 'Photo from TheMealDB'),
  ('53011', 'Chicken Quinoa Greek Salad', 'Greek', '1. Cook the quinoa as the package says, then rinse it in cold water and drain well.
2. Meanwhile, mash the butter with the chopped chili and garlic. Toss the chicken in 2 tsp of the oil with some salt and pepper.
3. Cook the chicken in a hot grill pan for 3 to 4 minutes on each side, until cooked through. Put it on a plate and dot it with the spicy butter to melt.
4. Mix the olives, sliced onion, crumbled feta and chopped mint in a bowl. Add the quinoa, the rest of the oil and the lemon juice and zest, and season well.
5. Serve with the chicken on top, drizzled with the buttery juices.', 10, 20, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/griddled-chicken-quinoa-greek-salad', 'https://www.themealdb.com/images/media/meals/k29viq1585565980.jpg', 'Photo from TheMealDB'),
  ('53549', 'Chicken Salad With Mushrooms and Bacon', 'Danish', '1. Put the chicken in a saucepan, cover it with water, add 1 tsp of salt and simmer for about 15 minutes. Let it cool, then shred it with two forks.
2. Stir the mayonnaise, crème fraîche, mustard and vinegar together and season. Mix in the finely chopped shallot and the chicken.
3. Fry the bacon until crisp and drain it on paper towels.
4. Fry the sliced mushrooms in the same pan for about 5 minutes, until golden, and season.
5. Top the chicken salad with the bacon, mushrooms and chopped parsley, and serve on slices of bread.', 15, 25, 4, '$$', array[]::text[], 'https://denmark.dk/people-and-culture/recipes/chicken-salad/', 'https://www.themealdb.com/images/media/meals/t5rgav1784659936.jpg', 'Photo from TheMealDB'),
  ('53218', 'Chicken Shawarma with homemade garlic herb yoghurt sauce', 'Saudi Arabian', '1. Cut the chicken into small, thin slices and put them in a large zip-top bag.
2. Add 2 of the garlic cloves (crushed), the coriander, cumin, cardamom, cayenne, smoked paprika, salt, lemon juice and 2 tbsp of the oil. Close the bag, mix well and chill for 10 to 12 hours (or less if you''re short on time).
3. Heat the rest of the oil in a large frying pan over medium-high heat. Cook the chicken in 2 batches, so the pan isn''t crowded, for 5 to 8 minutes, until well browned and cooked through.
4. Meanwhile, mix the yogurt with the last garlic clove (crushed), a squeeze of lemon, a pinch of cumin and salt.
5. Serve the chicken in warm flatbreads with the garlic yogurt sauce, and lettuce, tomato and onion if you like.', 15, 20, 4, '$$', array[]::text[], 'https://cookpad.com/eng/recipes/24343467?ref=search&search_term=saudi+arabia', 'https://www.themealdb.com/images/media/meals/hcg6l91763596970.jpg', 'Photo from TheMealDB'),
  ('53261', 'Chicken wings with cumin, lemon & garlic', 'Turkish', '1. Cut each wing in two at the joint with kitchen scissors.
2. Mix the crushed garlic, lemon zest and juice, cumin seeds and oil with plenty of salt and pepper. Toss the wings in it, cover and marinate in the fridge for at least 1 hour, or overnight.
3. Heat the oven to 400°F (200°C). Spread the wings on a baking sheet and bake for 45 to 50 minutes, until crisp, drizzling the honey over them for the last 10 minutes. (On a barbecue, they take about 20 minutes.)
4. Serve with flatbreads, olives and plenty of napkins.', 70, 50, 6, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/chicken-wings-cumin-lemon-garlic', 'https://www.themealdb.com/images/media/meals/4hzyvq1763792564.jpg', 'Photo from TheMealDB'),
  ('52870', 'Chickpea Fajitas', 'Mexican', '1. Heat the oven to 400°F (200°C) and line a baking sheet with foil. Drain the chickpeas, pat them dry and toss them on the sheet with the oil and paprika.
2. Roast for 20 to 25 minutes, shaking halfway, until browned and crisp.
3. Meanwhile, mix the chopped tomatoes and red onion with the vinegar and let them pickle. Mash the avocado with a fork, leaving some chunks, stir in the lime juice and season. Mix the sour cream with the harissa.
4. Heat a grill pan until very hot and char the tortillas on both sides, one at a time.
5. To build the fajitas, spread some harissa cream on each tortilla and top with chickpeas, avocado, the pickled salsa and cilantro. Serve with lime wedges.', 15, 25, 2, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/chickpea-fajitas', 'https://www.themealdb.com/images/media/meals/tvtxpq1511464705.jpg', 'Photo from TheMealDB'),
  ('53514', 'Chilean Empanada', 'Chilean', '1. Hard-boil 4 of the eggs, then peel and chop them.
2. Melt the butter in a large skillet over medium heat and cook the chopped onion, garlic, oregano, cumin, 1/2 tsp of the salt and the pepper for 5 to 7 minutes, until golden. Add the pork and cook for 7 to 10 minutes, until browned and crumbly.
3. Drain off the fat and stir in the raisins, sliced olives and chopped eggs. Set aside.
4. For the dough, mix the flour with the rest of the salt. Whisk the water with the melted shortening, pour it into the flour and mix into a dough. Let it rest for 10 minutes.
5. Heat the oven to 400°F (200°C) and line a baking sheet. Roll the dough out 1/8 inch thick and cut 12 circles. Spoon filling into the middle of each one, fold in half and seal with a fork.
6. Brush with the last egg, beaten, and bake for about 25 minutes, until golden brown.', 40, 45, 6, '$$', array[]::text[], 'https://www.allrecipes.com/recipe/185584/chilean-empanada/', 'https://www.themealdb.com/images/media/meals/q4xgij1782851193.jpg', 'Photo from TheMealDB'),
  ('53289', 'Chorba Hamra bel Frik (Algerian Lamb, Tomato, and Freekeh Soup)', 'Algerian', '1. Cover the freekeh with cold water and set it aside.
2. Put the diced lamb, chopped onion, pepper, paprika, cinnamon and salt in a pot. Stir in the oil, half of the chopped cilantro and mint, and the whole celery stalk. Cook over low heat for 15 minutes.
3. Stir in the drained chickpeas, pour in just enough water to cover and bring back to a simmer. Add the diced zucchini and carrot and the tomato paste.
4. Grate the tomatoes into the soup, discarding the skins. Add the diced potato and enough water to cover, and simmer for about 10 minutes, until soft.
5. Drain the freekeh, add it to the soup and simmer for about 15 minutes, until tender. Remove the celery stalk and sprinkle with the rest of the cilantro and mint.', 20, 55, 6, '$$', array[]::text[], 'https://www.allrecipes.com/recipe/264552/chorba-hamra-bel-frik-algerian-lamb-tomato-and-freekeh-soup/', 'https://www.themealdb.com/images/media/meals/p9tebp1764118792.jpg', 'Photo from TheMealDB'),
  ('53136', 'Choripán', 'Argentinian', '1. Cook the chorizos slowly on a grill or in a pan over medium heat for 10 to 15 minutes, until cooked through. Cooking them slowly stops the skins from bursting.
2. Slice the bread rolls and toast them lightly.
3. Split each chorizo lengthwise, put it in a roll and top with plenty of chimichurri. Serve hot.', 5, 15, 4, '$$', array[]::text[], 'https://www.munchery.com/blog/the-ten-iconic-dishes-of-argentina-and-how-to-cook-them-at-home/', 'https://www.themealdb.com/images/media/meals/5i25sg1763075353.jpg', 'Photo from TheMealDB'),
  ('53283', 'Chtitha Batata (Algerian Potato Stew)', 'Algerian', '1. Grind the garlic, chili, cumin, paprika, black pepper, cayenne and salt into a paste with a mortar and pestle, then mix in the olive oil.
2. Fry the paste in a large saucepan over medium heat for 2 to 4 minutes, until fragrant.
3. Add the potatoes, cut in half, and stir to coat them. Stir in the tomato paste and pour in just enough water to cover.
4. Bring to a boil, then simmer for about 40 minutes, until the potatoes are tender. Serve the potatoes with the sauce spooned over.', 10, 45, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.allrecipes.com/recipe/265319/chtitha-batata-algerian-potato-stew/', 'https://www.themealdb.com/images/media/meals/q8pu1k1764114334.jpg', 'Photo from TheMealDB'),
  ('53528', 'Chuletas de Cerdo a la Criolla (Pork Chops in Creole Sauce)', 'Colombian', '1. Put the pork chops in a zip-top bag with a spoonful of mustard, the cumin, crushed garlic, salt and pepper. Make sure they''re coated and chill for 1 hour or overnight.
2. Heat the oil in a large skillet over medium heat and cook the chops for 3 minutes on each side. Set them aside on a warm plate.
3. Add the chopped onions and tomatoes to the pan, with a little more oil if needed. Cook over high heat for 5 to 7 minutes, stirring often, until softened.
4. Return the chops, cover and simmer over medium-low heat for about 15 minutes, until tender. Serve with the sauce spooned over and the cilantro on top.', 70, 30, 4, '$$', array[]::text[], 'https://www.mycolombianrecipes.com/chuletas-de-cerdo-a-la-criolla-pork-chops-in-creole-sauce/#recipe', 'https://www.themealdb.com/images/media/meals/087fu71783802698.jpg', 'Photo from TheMealDB'),
  ('53555', 'Classic Potato Salad', 'Danish', '1. Boil the potatoes in lightly salted water for 10 to 12 minutes, until a fork slides out easily. Drain and let them cool.
2. Snap off the woody ends of the asparagus and chop it into small pieces. If you prefer it less raw, soak it in boiling water for 2 minutes.
3. Finely chop the chives, red onion and radishes.
4. Stir the crème fraîche, mayonnaise, mustard, sugar and vinegar together and season.
5. Mix the potatoes and vegetables with the dressing, keeping some chives to sprinkle on top, season and serve.', 20, 15, 4, '$', array['vegetarian']::text[], 'https://denmark.dk/people-and-culture/recipes/potato-salad/', 'https://www.themealdb.com/images/media/meals/5q88l31784664151.jpg', 'Photo from TheMealDB'),
  ('53505', 'Conch Fritters', 'Caribbean', '1. Grind or very finely chop the conch, the bell peppers, onions and chilies.
2. Mix in the lime juice, minced garlic, black pepper, salt, basil and pepper flakes, then the egg. Add the flour 1 tablespoon at a time, mixing until combined.
3. Cover and chill for 1 hour, or overnight for more flavor.
4. Heat about 2 inches of oil in a deep pan over medium-low heat. Drop in 1-inch balls of the mixture with two spoons and fry for 5 to 7 minutes, until golden and cooked inside.
5. Drain on paper towels and serve with tartar sauce and lime wedges.', 80, 25, 6, '$$', array['pescatarian']::text[], 'https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes', 'https://www.themealdb.com/images/media/meals/nmtq3n1782772031.jpg', 'Photo from TheMealDB'),
  ('52832', 'Coq au vin', 'French', '1. Heat 1 tbsp of the oil in a large heavy pan and fry the chopped bacon until crisp. Drain it on paper towels. Fry the shallots in the pan for 5 to 8 minutes, until browned all over, and set them aside with the bacon.
2. Pat the chicken dry. Add the rest of the oil and brown the chicken in 2 batches, 5 to 8 minutes each, turning often. Set it aside.
3. Add the garlic briefly, then pour in the brandy over medium-high heat and scrape the bottom of the pan until most of it has bubbled away.
4. Return the legs and thighs, pour in the wine, broth and tomato paste, and add the thyme, rosemary and bay leaves tied together. Season, return the bacon and shallots, add the breasts, cover and simmer gently for 50 minutes to 1 hour.
5. Just before serving, fry the mushrooms in a non-stick pan over high heat until golden.
6. Move the chicken, bacon and shallots to a serving dish and remove the herbs. Mash the flour with the butter, bring the sauce to a gentle boil and whisk in small pieces of this paste. Simmer for 1 to 2 minutes, then pour it over the chicken with the mushrooms and parsley.', 25, 80, 6, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/1913655/coq-au-vin', 'https://www.themealdb.com/images/media/meals/qstyvs1505931190.jpg', 'Photo from TheMealDB'),
  ('52977', 'Corba', 'Turkish', '1. Rinse the lentils 2 or 3 times and drain them.
2. Heat a little olive oil in a large pot over medium-high heat and cook the chopped onion with a pinch of salt for about 3 minutes. Add the diced carrot and cook for 3 minutes more.
3. Stir in the tomato paste for 1 minute, then add the cumin, paprika, mint, thyme, black pepper and pepper flakes and stir for 10 seconds.
4. Add the lentils, broth, water and salt and bring to a gentle boil. Lower the heat, half-cover and cook for 15 to 20 minutes, until the lentils fall apart.
5. Blend until as smooth as you like, adjust the salt and serve with bread or crackers.', 10, 30, 8, '$', array['vegan', 'vegetarian']::text[], 'https://findingtimeforcooking.com/main-dishes/red-lentil-soup-corba/', 'https://www.themealdb.com/images/media/meals/58oia61564916529.jpg', 'Photo from TheMealDB'),
  ('53431', 'Corn on the cob with lime, green chilli and coconut butter', 'Caribbean', '1. Bring the broth to a boil in a big, deep pan. Add the corn, cook for about 5 minutes, then turn off the heat and let it cool in the broth.
2. Drain the corn and char it in a very hot, dry frying pan for a couple of minutes on each side, two or three at a time.
3. Simmer the coconut milk with the lime juice and the chopped chili, season lightly, stir in the butter and set aside.
4. Toast the coconut in a hot, dry pan, stirring all the time, until golden. Let it cool, then mix it with the fried shallots and the chopped cilantro and parsley, and season.
5. Spoon the coconut milk mixture over each cob and sprinkle with the coconut mixture and lime zest.', 15, 20, 6, '$', array['vegetarian']::text[], 'https://www.theguardian.com/food/2020/jul/04/andi-oliver-antiguan-feast-recipes-slow-cooked-pork-belly-corn-chilli-lime-mango-chow-spiced-bread-butter-pudding', 'https://www.themealdb.com/images/media/meals/brhaoj1780086661.jpg', 'Photo from TheMealDB'),
  ('53490', 'Cottage Cheese And Feta Stuffed Peppers', 'Bulgarian', '1. Cut the peppers in half lengthwise and remove the seeds.
2. Mix the feta, cottage cheese, chives, parsley, salt and lemon juice in a bowl.
3. Fill the peppers with the mixture, sprinkle with more chives and parsley, and serve.', 10, 0, 4, '$', array['vegetarian']::text[], 'https://cookinglsl.com/cottage-cheese-stuffed-peppers/#wprm-recipe-container-59383', 'https://www.themealdb.com/images/media/meals/w0rsga1782683912.jpg', 'Photo from TheMealDB'),
  ('53530', 'Creamy Mustard Chicken', 'Colombian', '1. Pat the chicken dry and season it with the salt, pepper and paprika.
2. Heat the oil in a large pan over medium-high heat and brown the chicken on all sides, about 10 minutes, turning a couple of times. Set it aside.
3. Cook the chopped onion and garlic for about 2 minutes, until soft. Add the broth, mustard, honey and cream and season.
4. Return the chicken, cover and cook over medium-low heat for about 45 minutes, until cooked through (170°F inside).
5. Serve over white rice with chopped parsley.', 15, 60, 4, '$$', array[]::text[], 'https://www.mycolombianrecipes.com/mustard-creamy-chicken/#recipe', 'https://www.themealdb.com/images/media/meals/4htbtm1783803558.jpg', 'Photo from TheMealDB'),
  ('52841', 'Creamy Tomato Soup', 'British', '1. Put the oil, chopped onions, celery, carrots and potatoes and the bay leaves in a big pot. Cook gently for 10 to 15 minutes, until the onions are soft.
2. Stir in the tomato paste, sugar, vinegar, canned tomatoes and tomato purée, and crumble in the stock cubes. Add 4 cups (1 liter) of boiling water and bring to a simmer.
3. Cover and simmer for 15 minutes, until the potatoes are tender. Remove the bay leaves and blend until very smooth. Season, adding a pinch more sugar if needed.
4. To serve, reheat the soup and stir in the milk without letting it boil.', 20, 45, 10, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/2604646/creamy-tomato-soup', 'https://www.themealdb.com/images/media/meals/stpuws1511191310.jpg', 'Photo from TheMealDB'),
  ('53072', 'Crispy Eggplant', 'Filipino', '1. Cut the eggplant into slices about 1/2 inch (1 cm) thick, sprinkle them with salt and let them sit for 30 minutes.
2. Rinse off the salt and pat the slices dry.
3. Mix the breadcrumbs and sesame seeds on a plate. Beat the eggs with a pinch of salt and pepper in a bowl.
4. Heat oil in a large skillet over high heat. Dip each slice in egg, then in the crumbs, and fry for 2 to 3 minutes on each side, until golden brown. Drain on paper towels.', 40, 15, 2, '$', array['vegetarian']::text[], 'https://yummyfood.ph/recipe/crispiest-fried-eggplant/', 'https://www.themealdb.com/images/media/meals/c7lzrl1683208757.jpg', 'Photo from TheMealDB'),
  ('53419', 'Crispy fried fish with ginger and fermented soybeans (trey chien chuon)', 'Cambodian', '1. Cut the ginger into thin matchsticks and fry it in plenty of oil until golden and slightly crisp. Set it aside.
2. Cut the fish into strips, dust them very lightly with the tempura flour and fry them in the same oil until golden and crisp.
3. Drain the fermented soybeans in a colander. If they are very salty, rinse them first.
4. Heat 1 tbsp of oil in a deep pan and fry the chopped garlic until slightly golden. Add the soybeans and stir-fry for a few minutes, adding the sugar if they taste very salty. Add the water and cook for 1 minute.
5. Just before serving, stir in the fried ginger, the chopped green onions and the fish. Serve with steamed rice.', 20, 25, 4, '$$', array['pescatarian']::text[], 'https://mitziemee.com/recipe-cambodian-fried-fish-ginger-fermented-soybeans/', 'https://www.themealdb.com/images/media/meals/9q1ci41779735714.jpg', 'Photo from TheMealDB'),
  ('52999', 'Crispy Sausages and Greens', 'Irish', '1. Heat the oven to 350°F (180°C). Strip the kale leaves from the stems and tear them into 1-inch pieces. Chop the cabbage.
2. Fry the sliced onion and mushrooms in a little olive oil until soft.
3. Put the greens in a large baking dish with the sliced garlic, onion and mushrooms. Coat with a little olive oil and pour the broth over.
4. Cover with foil and bake for about 15 minutes, until the greens wilt. Uncover, season and bake for 20 to 25 minutes more, until the cabbage is tender.
5. Meanwhile, prick the sausages and cook them in a little oil in a skillet over medium-high heat for 10 to 12 minutes, until browned and cooked through. Slice them and toss them with the greens, with a splash of vinegar if you like.', 15, 40, 4, '$$', array[]::text[], 'https://www.bonappetit.com/columns/cooking-without-recipes/article/kale-cabbage-sausage-weeknight-dinner', 'https://www.themealdb.com/images/media/meals/st1ifa1583267248.jpg', 'Photo from TheMealDB'),
  ('52830', 'Crock Pot Chicken Baked Tacos', 'Mexican', '1. Put the chicken in a pot with the dressing, cumin, smoked paprika and garlic. Cover and simmer over low heat for about 30 minutes, turning now and then, until cooked through. (In a slow cooker, cook on high for 4 hours.)
2. Lift out the chicken, shred it and mix it with most of the cooking liquid.
3. Heat the oven to 450°F (230°C). Stand the taco shells in a baking dish and fill each with a layer of refried beans, chicken and cheese.
4. Bake for 10 to 15 minutes, until the cheese bubbles.
5. Meanwhile, blend the avocado with the green salsa until smooth, and thin the sour cream with the milk. Top the tacos with sliced tomatoes and jalapeño, then drizzle with both sauces.', 20, 45, 6, '$$', array[]::text[], 'http://www.nobiggie.net/crock-pot-chicken-baked-tacos/', 'https://www.themealdb.com/images/media/meals/ypxvwv1505333929.jpg', 'Photo from TheMealDB'),
  ('53547', 'Cuban Sandwich', 'Cuban', '1. Put the pork chops in a baking dish, poke them all over with a fork, season with 1 tsp of salt and toss with the oil.
2. Mix the orange and lime zest and juice with the oregano, pepper and garlic powder. Pour half over the pork and let it rest for 10 to 15 minutes.
3. Heat the oven to 425°F (220°C). Stir the mustard and mayonnaise into the rest of the marinade.
4. Roast the pork for 15 to 20 minutes, until it reaches 140°F inside, then slice it.
5. Cut the bread into 4 pieces, butter the outsides and spread the cut sides with the mustard sauce. Layer cheese, ham, pork, sliced pickles and more cheese, close the sandwiches and wrap each in foil.
6. Cook them in a heavy skillet over medium heat with another heavy pan on top as a press, 3 to 4 minutes on each side, until toasted and melted. Cut in half and serve.', 25, 30, 4, '$$', array[]::text[], 'https://www.delish.com/cooking/recipe-ideas/a64854750/homemade-cuban-sandwiches-recipe/', 'https://www.themealdb.com/images/media/meals/djdg8l1784578885.jpg', 'Photo from TheMealDB'),
  ('53309', 'Cucumber & fennel salad', 'Polish', '1. Slice the cucumber thinly and put it in a sieve. Sprinkle it with 1 tsp of salt and the sugar and leave it for 10 minutes.
2. Thinly slice the fennel and mix it with the drained cucumber.
3. Mix the sour cream with the lemon juice, vinegar and chopped dill, season with black pepper and stir it into the salad.', 20, 0, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/cucumber-fennel-salad', 'https://www.themealdb.com/images/media/meals/ei21r61764365935.jpg', 'Photo from TheMealDB'),
  ('53473', 'Curried Spinach from Botswana', 'Botswanan', '1. Heat the oil in a skillet over medium heat and cook the diced onion until lightly browned.
2. Add the curry powder and a little salt and toast for a few seconds.
3. Add the chopped tomatoes and the water and cook for 5 to 7 minutes, until the tomatoes break down.
4. Stir in the chopped spinach and cook for 7 to 10 minutes more, until soft and wilted.', 10, 20, 4, '$', array['vegan', 'vegetarian']::text[], 'https://kosherworldkitchen.com/morogo-curried-spinach/#recipe', 'https://www.themealdb.com/images/media/meals/lyr07q1782505714.jpg', 'Photo from TheMealDB'),
  ('52785', 'Dal fry', 'Indian', '1. Rinse the dal and soak it in about 3 cups of water for at least 1 hour, then drain it.
2. Cook the dal with 2 1/2 cups of water, the salt and the turmeric over medium-high heat for about 30 minutes, until soft and like a thick soup.
3. Heat the ghee in a frying pan and add the cumin and mustard seeds. When they crackle, add the bay leaves, chopped green chili, ginger and chili powder and stir for a few seconds.
4. Add the tomatoes and sugar and cook until the tomatoes are soft and mushy. Stir in the cilantro and garam masala for about 1 minute.
5. Pour this over the dal, mix well and cook for 1 minute more. Serve with naan or rice.', 70, 40, 4, '$', array['vegetarian']::text[], 'https://www.instagram.com/p/BO21bpYD3Fu', 'https://www.themealdb.com/images/media/meals/wuxrtu1483564410.jpg', 'Photo from TheMealDB'),
  ('53143', 'Easy Spanish chicken', 'Spanish', '1. Heat the oven to 400°F (200°C). Heat the oil in a large ovenproof frying pan over medium heat and fry the chopped onion, sliced chorizo and peppers with a pinch of salt and pepper for 15 minutes, until soft.
2. Add the paprika and garlic and cook for a few minutes, until fragrant.
3. Stir in the tomatoes, olives and drained butter beans and season. Nestle the chicken thighs in the sauce and season them well.
4. Bake for 40 minutes, until the skin is crisp and the chicken is cooked through. Scatter with parsley and serve.', 15, 60, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/easy-spanish-chicken', 'https://www.themealdb.com/images/media/meals/kzxflc1763194887.jpg', 'Photo from TheMealDB'),
  ('53486', 'Easy White Bean Soup', 'Bulgarian', '1. Cover the beans with cold water and soak them for at least 4 hours or overnight. Drain and rinse.
2. Chop one onion and the carrots, and leave the other onion whole. Heat the oil in a large pot over medium heat and cook the chopped onion and carrots for 2 minutes.
3. Add the beans, water, whole peppers, whole onion, tomato paste, mint, thyme, savory, salt and pepper. Bring to a boil, then simmer for about 2 hours, until the beans are tender.
4. Lift out the peppers and the whole onion. Mash the onion, peel and chop the peppers and return them to the pot.
5. Season to taste and serve with chopped parsley.', 15, 120, 8, '$', array['vegan', 'vegetarian']::text[], 'https://cookinglsl.com/bulgarian-white-bean-soup/', 'https://www.themealdb.com/images/media/meals/p5nzbk1782680889.jpg', 'Photo from TheMealDB'),
  ('52944', 'Escovitch Fish', 'Jamaican', '1. Rinse the fish, rub it with lime and season with salt and pepper.
2. Heat the oil in a large skillet over medium heat and fry the fish for 5 to 7 minutes on each side, until crisp and cooked through. Set it aside and pour off all but 2 to 3 tbsp of the oil.
3. Add the bay leaf, garlic and ginger and stir-fry for about 1 minute, without letting the garlic burn.
4. Add the sliced onion, peppers and carrot, the thyme, sliced Scotch bonnet, sugar, allspice and Worcestershire sauce and stir for 2 to 3 minutes.
5. Add the vinegar, season and simmer for 2 minutes. Remove the bay leaf and thyme and spoon the sauce over the fish.', 15, 25, 4, '$$', array['pescatarian']::text[], 'https://www.africanbites.com/jamaican-escovitched-fish/', 'https://www.themealdb.com/images/media/meals/1520084413.jpg', 'Photo from TheMealDB'),
  ('53091', 'Falafel Pita Sandwich with Tahini Sauce', 'Syrian', '1. Heat the oven to 450°F (230°C). Bake the falafel on a baking sheet for 8 to 10 minutes, until hot.
2. Meanwhile, whisk the tahini, water, lemon juice, crushed garlic and paprika into a sauce.
3. Cut about 1 inch off the top of each pita to open a pocket.
4. Put 2 falafel in each pita with some lettuce, tomato, cucumber, pickle and red onion. Drizzle with about 1 tbsp of the tahini sauce and a little harissa.', 15, 10, 6, '$', array['vegetarian']::text[], 'https://www.allrecipes.com/recipe/266014/falafel-pita-sandwich-with-tahini-sauce/', 'https://www.themealdb.com/images/media/meals/ae6clc1760524712.jpg', 'Photo from TheMealDB'),
  ('53123', 'Fårikål (Norwegian National Dish)', 'Norwegian', '1. Cut the lamb into large pieces and the cabbage into large wedges, keeping the core so they hold together.
2. Put a layer of lamb in the bottom of a large pot, fat side down, and sprinkle with some of the peppercorns, salt and flour. Add a layer of cabbage.
3. Repeat the layers, finishing with cabbage.
4. Pour in the water and bring to a boil. Cover and cook over low heat for 2 to 3 hours, until the lamb falls off the bone.
5. Serve with boiled potatoes and plenty of the broth.', 15, 150, 6, '$$', array[]::text[], 'https://scandinaviancookbook.com/farikal-national-dish-of-norway/', 'https://www.themealdb.com/images/media/meals/ttfxxn1762773067.jpg', 'Photo from TheMealDB'),
  ('53188', 'Fašírky', 'Slovak', '1. Soak the bread in the milk until soft, then squeeze it out and crumble it.
2. Mix the pork with the finely chopped onion and garlic, the bread, 1 egg, the salt, pepper, marjoram, mustard and parsley.
3. Shape the mixture into palm-sized patties and flatten them slightly.
4. Dust each patty with flour, dip it in the other egg, beaten, and coat it with breadcrumbs.
5. Fry in oil over medium heat for 4 to 5 minutes on each side, until golden and cooked through. Drain on paper towels and serve with mashed potatoes or salad.', 20, 20, 4, '$', array[]::text[], 'https://www.slovakia-foods.co.uk/blog/post/fasirky-recipe-how-to-make-authentic-slovak-meat-patties.html', 'https://www.themealdb.com/images/media/meals/gtpvwp1763363947.jpg', 'Photo from TheMealDB'),
  ('53092', 'Fasoliyyeh Bi Z-Zayt (Syrian Green Beans with Olive Oil)', 'Syrian', '1. Put the green beans in a large pot, drizzle with the olive oil, season with salt and cover.
2. Cook over medium-high heat, stirring now and then, until done the way you like. In Syria they''re cooked until they start to brown. They should steam in their own moisture, not fry.
3. Add the cilantro and the crushed garlic and cook just until the cilantro wilts. Serve warm with pita bread, or as a side dish.', 5, 25, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.allrecipes.com/recipe/56161/fasoliyyeh-bi-z-zayt-syrian-green-beans-with-olive-oil/', 'https://www.themealdb.com/images/media/meals/21yc5s1760524759.jpg', 'Photo from TheMealDB'),
  ('52919', 'Fennel Dauphinoise', 'French', '1. Heat the oven to 350°F (180°C). Thinly slice the potatoes and fennel, keeping the fronds, and crush the garlic.
2. Put them in a medium non-stick pan with the milk and cream, season well, cover and simmer gently for 10 minutes, stirring halfway, until the potatoes are just tender.
3. Divide the mixture between 2 small buttered ramekins and scatter with parmesan.
4. Bake for 40 minutes, until golden and tender. Snip the fennel fronds over the top before serving.', 15, 50, 2, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/fennel-dauphinoise', 'https://www.themealdb.com/images/media/meals/ytttsv1511798734.jpg', 'Photo from TheMealDB'),
  ('53064', 'Fettuccine Alfredo', 'Italian', '1. Cook the pasta in a large pot of salted boiling water as the package says, then drain.
2. Meanwhile, heat the cream and butter in a large skillet over medium heat until the butter melts and the cream bubbles.
3. Whisk in the parmesan, season with salt and pepper and let the sauce thicken slightly.
4. Add the pasta and toss until coated. Sprinkle with parsley and serve.', 5, 20, 4, '$', array['vegetarian']::text[], 'https://www.delish.com/cooking/recipe-ideas/a55312/best-homemade-fettuccine-alfredo-recipe/', 'https://www.themealdb.com/images/media/meals/0jv5gx1661040802.jpg', 'Photo from TheMealDB'),
  ('52802', 'Fish pie', 'British', '1. Put the potatoes in a large pan of cold salted water, bring to a boil and simmer, covered, for 15 minutes, until tender. Drain, dry them over low heat for 30 seconds and mash with 1 tbsp of the oil. Season.
2. Meanwhile, put the milk and fish in a large pan and bring to a boil. Take it off the heat, cover and leave for 3 minutes. Lift out the fish, keeping the milk, and flake it into a baking dish without skin or bones.
3. Heat the rest of the oil in a pan, stir in the flour for 30 seconds, then gradually stir in about 1 cup (250 ml) of the milk. Grate in some nutmeg, season and let it bubble until thick. Stir in the cream.
4. Heat the oven to 375°F (190°C). Grate the artichokes and add them to the dish with the sliced leek, the shrimp and the chopped herbs. Stir the lemon zest and juice into the sauce and pour it over.
5. Spoon the mash on top, rough it up with a fork, sprinkle with the cheese and bake for 35 to 40 minutes, until golden and bubbling.', 25, 60, 4, '$$$', array['pescatarian']::text[], null, 'https://www.themealdb.com/images/media/meals/ysxwuq1487323065.jpg', 'Photo from TheMealDB'),
  ('53079', 'Fish Soup (Ukha)', 'Russian', '1. Heat the oil in a medium pot over medium-high heat and cook the chopped onion, stirring now and then, until it starts to caramelize. Add the sliced carrots and cook for about 4 minutes more.
2. Add the stock, water, diced potatoes and bay leaves, season with salt and pepper and bring to a boil. Cover and cook over low heat for about 20 minutes, until the potatoes are tender.
3. Gently add the fish, cut into cubes, and bring back to a simmer. It cooks very fast: it''s done when it''s opaque and flakes easily.
4. Serve with chopped dill or parsley.', 15, 35, 6, '$$', array['pescatarian']::text[], 'https://www.curiouscuisiniere.com/ukha-russian-fish-soup/', 'https://www.themealdb.com/images/media/meals/7n8su21699013057.jpg', 'Photo from TheMealDB'),
  ('52918', 'Fish Stew with Rouille', 'French', '1. Peel and devein the shrimp, keeping the tails on. Fry the shells in 1 tbsp of the oil for 5 minutes, until pink and golden. Add the wine and boil until reduced by two thirds, then add the stock. Strain and discard the shells.
2. Heat the rest of the oil in a deep frying pan, add the sliced fennel and onion and the garlic, season, cover and cook gently for 10 minutes. Meanwhile, boil the potato, cut into 3/4-inch chunks, for 5 minutes and drain.
3. Add a strip of orange zest, the star anise, the bay leaf and 1/2 tsp of the harissa to the pan and fry gently, uncovered, for 5 to 10 minutes, until soft and golden.
4. Stir in the tomato paste for 2 minutes, then add the tomatoes and the shrimp stock and simmer for 10 minutes. Season. Scrub the mussels and remove the beards, throwing away any that stay open when tapped.
5. Gently stir in the potato, the fish in chunks and the shrimp. Bring back to a boil, cover and simmer for 3 minutes. Add the mussels, cover and cook for 2 minutes more, until they open (throw away any that stay closed).
6. Scatter with thyme leaves. For a quick rouille, stir the rest of the harissa into the mayonnaise. Serve in bowls with the rouille on top and bread on the side.', 30, 55, 2, '$$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/532640/summer-fish-stew-with-rouille', 'https://www.themealdb.com/images/media/meals/vptqpw1511798500.jpg', 'Photo from TheMealDB'),
  ('53122', 'Fiskesuppe (Creamy Norwegian Fish Soup)', 'Norwegian', '1. Cut the fish into cubes, crush the garlic and cut the potatoes, carrots and leek into thin strips.
2. Heat the butter in a pot and add the garlic. When it starts to turn golden, whisk in the flour.
3. Add the fish stock, whisking until there are no lumps. Add the vegetables and milk, bring to a boil and cook for about 10 minutes.
4. Stir in the crème fraîche and bring back to a simmer. When it bubbles, turn off the heat, add the fish and let it cook in the hot soup for 5 minutes. Add the shrimp just before serving.
5. Sprinkle with chives and serve.', 10, 25, 4, '$$', array['pescatarian']::text[], 'https://scandinaviancookbook.com/fiskesuppe-creamy-norwegian-fish-soup/', 'https://www.themealdb.com/images/media/meals/raqjbj1762773035.jpg', 'Photo from TheMealDB'),
  ('53464', 'Flemish Hutsepot', 'Belgian', '1. Melt the butter in a large pan over medium heat and cook the chopped onion and garlic for 5 minutes.
2. Add the chopped potatoes, bay leaves and thyme and cook for 5 minutes more.
3. Add the sliced carrots, diced turnips and sliced leek, the mustard and the broth, and season. Cover and cook for 20 to 25 minutes, stirring often, until everything is tender. Add a little water if needed.
4. Meanwhile, fry the sausages in a little oil until golden and cooked through.
5. When the potatoes start to fall apart, stir everything into a chunky stew and season to taste. Serve topped with the sausages and some extra mustard.', 15, 35, 4, '$', array[]::text[], 'https://junedarville.com/hutsepot.html', 'https://www.themealdb.com/images/media/meals/2lywl71782496853.jpg', 'Photo from TheMealDB'),
  ('52815', 'French Lentils With Garlic and Thyme', 'French', '1. Heat the oil in a large saucepan over medium heat. Add the chopped onion, garlic, carrot and celery and cook for 5 to 10 minutes, until soft.
2. Add 6 cups of water, the lentils, thyme, bay leaves and salt. Bring to a boil, then lower to a fast simmer.
3. Simmer for 20 to 25 minutes, until the lentils are tender and have absorbed most of the water. Drain any extra water and serve.', 10, 35, 6, '$', array['vegan', 'vegetarian']::text[], null, 'https://www.themealdb.com/images/media/meals/vwwspt1487394060.jpg', 'Photo from TheMealDB'),
  ('53553', 'Frikadeller - Danish Meatballs', 'Danish', '1. Finely chop the onion and garlic.
2. Stir the salt into the pork, then mix in the flour, oats and pepper, the onion and garlic, the egg and lastly the milk. Stir until the mixture is firm, then chill it for at least 30 minutes.
3. Melt the butter in a pan over medium heat. Shape about 2 tablespoons of the mixture into each meatball with a spoon.
4. Fry them until well browned on both sides and cooked through. Serve hot with potato salad.', 40, 20, 4, '$', array[]::text[], 'https://denmark.dk/people-and-culture/recipes/danish-meat-balls/', 'https://www.themealdb.com/images/media/meals/bnhfa71784662834.jpg', 'Photo from TheMealDB'),
  ('53025', 'Ful Medames', 'Egyptian', '1. Soak the dried beans in cold water overnight, then drain them.
2. Cover them with fresh unsalted water in a large pan with a lid and simmer gently for 2 to 2 1/2 hours, until tender. Keep them covered with water, and add salt once they''re soft.
3. Let the liquid reduce. Mash a ladle or two of the beans with some of the liquid and stir them back in to thicken.
4. Serve in bowls with chopped parsley. Let everyone add olive oil, lemon juice, crushed garlic, cumin, salt and pepper to taste, and eat the beans lightly crushed with a fork, with flatbread.', 10, 150, 6, '$', array['vegan', 'vegetarian']::text[], 'https://www.epicurious.com/recipes/food/views/ful-medames-352993', 'https://www.themealdb.com/images/media/meals/lvn2d51598732465.jpg', 'Photo from TheMealDB'),
  ('52896', 'Full English Breakfast', 'British', '1. Brush a griddle or large frying pan with a little oil and cook the sausages slowly over low heat for 15 to 20 minutes, turning now and then, until golden. After 10 minutes, turn the heat up to medium.
2. Cut a few slits in the fat of the bacon and fry it for 2 to 4 minutes on each side.
3. Season the mushrooms, drizzle them with oil and cook stalk side up for 1 to 2 minutes, then turn and cook for 3 to 4 minutes more.
4. Cut the tomatoes in half, season and cook cut side down for 2 minutes, then turn and cook for 2 to 3 minutes more. Slice the black pudding and cook it for 1 1/2 to 2 minutes on each side. Keep everything warm. Meanwhile, heat the baked beans in a small pan.
5. In a separate pan, fry the bread in oil for 2 to 3 minutes on each side, until golden. Fry the eggs in the same pan, spooning the hot oil over them. Serve everything on warm plates.', 10, 30, 2, '$$', array[]::text[], 'https://www.bbc.co.uk/food/recipes/stressfreefullenglis_67721', 'https://www.themealdb.com/images/media/meals/sqrtwu1511721265.jpg', 'Photo from TheMealDB'),
  ('53541', 'Gallo pinto', 'Costa Rican', '1. Heat a little oil in a pan over medium-high heat. Add the chopped onion, bell pepper and cilantro, the cumin and salt, and cook for 3 to 5 minutes, until the onion is translucent.
2. Stir in the cooked beans, lower the heat to medium, add the Lizano sauce and cook for 5 minutes.
3. Add the cooked rice and stir for 5 to 7 minutes, until it takes on all the flavors. Cook it less if you like it moist, longer if you like it toasted.', 5, 15, 2, '$', array['vegan', 'vegetarian']::text[], 'https://www.recipesfromcostarica.com/recipes', 'https://www.themealdb.com/images/media/meals/ytogg31784397116.jpg', 'Photo from TheMealDB'),
  ('53144', 'Gambas al ajillo', 'Spanish', '1. Peel the shrimp, leaving the tails on, and remove the dark vein. Season with a little salt.
2. Put the sliced garlic, olive oil and chilies in a frying pan or terracotta dish over high heat.
3. When the garlic starts to turn golden, add the shrimp and cook for 1 to 2 minutes on each side, until just pink.
4. Sprinkle with the parsley and some black pepper and serve right away.', 5, 5, 2, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/gambas-al-ajillo', 'https://www.themealdb.com/images/media/meals/ze8uwg1763196123.jpg', 'Photo from TheMealDB'),
  ('52764', 'Garides Saganaki', 'Greek', '1. Put the shrimp in a pot with enough water to cover and boil for 5 minutes. Drain and let them cool.
2. Heat 2 tbsp of the oil in a saucepan and cook the chopped onion until soft. Add the chopped parsley, wine, tomatoes, garlic and the rest of the oil.
3. Simmer for about 30 minutes, stirring now and then, until thick. Meanwhile, peel the shrimp, leaving the heads and tails on if you like.
4. Stir the shrimp into the sauce and simmer for about 5 minutes. Crumble in the feta, take it off the heat and let it stand until the cheese starts to melt. Serve warm with crusty bread.', 15, 45, 4, '$$', array['pescatarian']::text[], null, 'https://www.themealdb.com/images/media/meals/wuvryu1468232995.jpg', 'Photo from TheMealDB'),
  ('52951', 'General Tsos Chicken', 'Chinese', '1. Cut the chicken into bite-size pieces. Whisk the flour, egg, 2 tbsp of the cornstarch, the baking powder, salt, onion salt, garlic powder and water into a smooth batter, and coat the chicken in it.
2. Heat oil for deep-frying to 350°F (175°C). Fry the chicken in batches for 3 to 4 minutes, until golden and crisp, and drain it on paper towels.
3. For the sauce, heat the sesame oil in a wok and fry the minced garlic and ginger for 30 seconds. Add the broth, duck sauce, soy sauce, honey, vinegar and gochujang and bring to a boil.
4. Mix the rest of the cornstarch with 2 tbsp of water and stir it in until the sauce thickens.
5. Toss the chicken in the sauce for 1 minute and serve sprinkled with the sliced green onions.', 15, 20, 4, '$$', array[]::text[], 'https://www.skinnytaste.com/general-tsos-chicken/', 'https://www.themealdb.com/images/media/meals/1529444113.jpg', 'Photo from TheMealDB'),
  ('53012', 'Gigantes Plaki', 'Greek', '1. Soak the beans overnight in plenty of water. Drain, rinse, cover with fresh water and simmer for about 50 minutes, until slightly tender but not soft. Drain.
2. Heat the oven to 350°F (180°C). Heat the olive oil in a large frying pan and cook the chopped onion and garlic over medium heat for 10 minutes, until soft but not brown.
3. Stir in the tomato paste for 1 minute, then add the chopped tomatoes, sugar, oregano and a pinch of cinnamon and simmer for 2 to 3 minutes. Season well and stir in the beans.
4. Pour into a large baking dish and bake uncovered, without stirring, for about 1 hour, until the beans are tender and the sauce is thick.
5. Let it cool a little, then scatter with parsley and drizzle with olive oil.', 20, 120, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/gigantes-plaki', 'https://www.themealdb.com/images/media/meals/b79r6f1585566277.jpg', 'Photo from TheMealDB'),
  ('53274', 'Griddled aubergines with sesame dressing', 'Turkish', '1. Slice the eggplants, brush the slices with oil and season.
2. Heat a grill pan until hot and cook the slices for 2 to 3 minutes on each side, until golden and tender. Work in batches.
3. Mix the yogurt with the tahini, crushed garlic, lemon juice and most of the chopped herbs, and season.
4. Spoon the dressing over the eggplant and scatter with the rest of the herbs.', 10, 20, 6, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/griddled-aubergines-sesame-dressing', 'https://www.themealdb.com/images/media/meals/yoj48r1763817100.jpg', 'Photo from TheMealDB'),
  ('53255', 'Grilled aubergines with spicy chickpeas & walnut sauce', 'Turkish', '1. Heat 2 tbsp of the oil in a pan and fry the chopped onion for about 10 minutes, until soft and lightly browned. Stir in the chopped chili, grated ginger and cumin.
2. Add the drained chickpeas, chopped tomatoes and 5 tbsp of water, bring to a boil and simmer for 10 minutes. Season and add the lemon juice.
3. Meanwhile, heat the broiler. Slice the eggplants lengthwise, brush them with oil, season and broil until golden. Turn them, brush again and broil until tender.
4. Mix the yogurt with the crushed garlic, most of the chopped walnuts and cilantro, and a little salt and pepper.
5. Arrange the eggplant on a warm plate, spoon the chickpeas over it, drizzle with the walnut sauce and scatter with the rest of the walnuts and cilantro.', 20, 30, 2, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/grilled-aubergines-spicy-chickpeas-walnut-sauce', 'https://www.themealdb.com/images/media/meals/ctw3ba1763788978.jpg', 'Photo from TheMealDB'),
  ('53478', 'Grilled corn with garlic mayo & grated cheese', 'Brazilian', '1. Boil the corn for 5 minutes and leave it in the water until you''re ready to grill it.
2. Mix the crushed garlic with the mayonnaise.
3. Pat the corn dry, rub it with the garlic mayo and season.
4. Cook on a hot grill pan or barbecue for about 5 minutes, turning, until charred in places. Scatter with the parmesan and chopped cilantro and squeeze lime over the top.', 5, 15, 6, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/grilled-corn-garlic-mayo-grated-cheese', 'https://www.themealdb.com/images/media/meals/k1if4d1782589892.jpg', 'Photo from TheMealDB'),
  ('53074', 'Grilled eggplant with coconut milk', 'Filipino', '1. Prick the eggplants all over with a fork so they don''t burst.
2. Grill them over a gas flame or on a hot grill pan, turning often, until the skins are blackened and the flesh is soft.
3. Cool them in a bowl of water, peel off the skins and cut the flesh into bite-size pieces. Put them in a shallow dish.
4. Mix the coconut milk with the lemon juice, salt and pepper flakes, then taste and adjust. Pour it over the eggplant, sprinkle with sliced green onions and stir gently.', 10, 20, 3, '$', array['vegan', 'vegetarian']::text[], 'https://simplybakings.com/grilled-eggplant-with-coconut-milk/', 'https://www.themealdb.com/images/media/meals/bopa2i1683209167.jpg', 'Photo from TheMealDB'),
  ('52829', 'Grilled Mac and Cheese Sandwich', 'American', '1. Cook the macaroni in well-salted boiling water for 8 to 10 minutes, until al dente, and drain. Mix the flour with the mustard powder, 1/2 tsp of the garlic powder, the salt, pepper and cayenne.
2. Melt 10 tbsp of the butter in the empty pan over low heat, whisk in the flour mixture and cook for about 1 minute, until nutty. Slowly whisk in the milk and cream and cook for about 2 minutes, until it starts to thicken.
3. Take it off the heat and stir in the grated Monterey Jack until melted, then the macaroni.
4. Spread it on a buttered, lined 9 x 13-inch baking sheet, cover with buttered parchment and chill for about 1 hour, until firm. Cut it into 8 pieces.
5. Mix the rest of the butter with the rest of the garlic powder and spread it on one side of each slice of bread.
6. Build each sandwich buttered side out: bread, a slice of cheddar, a piece of mac and cheese, a slice of Colby Jack, bread. Cook in a covered skillet over medium-low heat for about 4 minutes on each side, until browned and hot inside.', 90, 40, 8, '$$', array['vegetarian']::text[], 'https://leitesculinaria.com/103647/recipes-grilled-mac-and-cheese-sandwich.html', 'https://www.themealdb.com/images/media/meals/xutquv1505330523.jpg', 'Photo from TheMealDB'),
  ('53041', 'Grilled Portuguese sardines', 'Portuguese', '1. Mix the olive oil, crushed garlic, paprika, lemon juice, rosemary and chopped chili with some salt and pepper in a baking dish.
2. Add the sardines, toss well, cover and chill for a few hours.
3. Heat a grill pan or barbecue until hot and cook the sardines for 4 to 5 minutes on each side, until charred.
4. Drizzle with oil, sprinkle with a little more paprika and serve with lemon wedges.', 10, 10, 4, '$$', array['pescatarian']::text[], 'https://www.olivemagazine.com/recipes/fish-and-seafood/grilled-portuguese-sardines/', 'https://www.themealdb.com/images/media/meals/lpd4wy1614347943.jpg', 'Photo from TheMealDB'),
  ('53340', 'Hodge Podge', 'Canadian', '1. Bring a large pot of salted water to a boil. Cook the diced potatoes and carrots for about 5 minutes, until just tender, then add the green beans and peas for 1 minute. Drain.
2. Melt the butter in a heavy pot over medium heat and warm the vegetables in it.
3. Add the milk and cream and bring to a boil, then lower the heat and season with the salt and pepper.
4. Add the dill and chives and simmer for at least 10 minutes. Serve warm.', 10, 30, 6, '$', array['vegetarian']::text[], 'https://canadianfoodfocus.org/recipes/classic-canadian-dish-hodge-podge/', 'https://www.themealdb.com/images/media/meals/xihv0c1764447887.jpg', 'Photo from TheMealDB'),
  ('52993', 'Honey Balsamic Chicken with Crispy Broccoli & Potatoes', 'American', '1. Heat the oven to 425°F (220°C). Cut the potatoes into 1/2-inch wedges, toss them on one side of a baking sheet with a little oil, salt and pepper, and roast for 5 minutes.
2. Cut the broccoli into bite-size florets and chop the garlic. Warm the olive oil with half of the garlic in a small pan for 30 seconds.
3. Add the broccoli to the other side of the sheet, toss it with the garlic oil, salt and pepper, and roast for 15 to 20 minutes more, until browned and crisp.
4. Meanwhile, season the chicken and cook it in a little vegetable oil in a large pan over medium-high heat for 5 to 6 minutes on each side, until cooked through. Set it aside.
5. In the same pan, cook the rest of the garlic for 30 seconds, then add the vinegar, honey and broth and simmer for 2 to 3 minutes, until thick and glossy. Take it off the heat and stir in the butter.
6. Turn the chicken in the glaze and serve with the potatoes and broccoli.', 10, 35, 2, '$$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/kvbotn1581012881.jpg', 'Photo from TheMealDB'),
  ('52773', 'Honey Teriyaki Salmon', 'Japanese', '1. Whisk the soy sauce and sake together and coat the salmon in it.
2. Heat the oil in a skillet over medium-low heat. Cook the salmon on both sides, adding the rest of the glaze, until it''s cooked through and the glaze has thickened.
3. Sprinkle with the sesame seeds and serve right away.', 10, 15, 2, '$$', array['pescatarian']::text[], null, 'https://www.themealdb.com/images/media/meals/xxyupu1468262513.jpg', 'Photo from TheMealDB'),
  ('53253', 'Imam bayildi with BBQ lamb & tzatziki', 'Turkish', '1. Heat the oven to 375°F (190°C). Halve the eggplants lengthwise, score the flesh deeply, brush with plenty of olive oil and roast on a baking sheet for about 20 minutes, until soft.
2. Fry the chopped onion in a little oil until soft, then add the garlic and cinnamon for 1 minute.
3. Scoop out the middle of the eggplants, chop it and add it to the onions. Halve the tomatoes, scoop the seeds and juice into a sieve over a bowl, chop the flesh and add it to the pan. Cook for 10 minutes, until soft, and stir in most of the parsley.
4. Lay the eggplant halves in a baking dish, fill them with the tomato mixture, pour over the tomato juice, drizzle with oil and bake for 30 minutes.
5. For the tzatziki, mix the yogurt with the grated cucumber and chopped mint and season.
6. Season the lamb with salt, pepper and a pinch of paprika and cook on a hot grill pan for 3 minutes on each side. Squeeze lemon over it and serve with the eggplant, the rest of the parsley and the tzatziki.', 20, 75, 6, '$$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/imam-bayildi-bbq-lamb-tzatziki', 'https://www.themealdb.com/images/media/meals/ampz9v1763787134.jpg', 'Photo from TheMealDB'),
  ('52781', 'Irish stew', 'Irish', '1. Soak the wheat berries overnight. Drain, cover with plenty of water and simmer for about 1 hour, until cooked. Drain.
2. Heat the oven to 350°F (180°C). Season the lamb with 1 tsp of salt and some pepper. Heat 1 tbsp of the oil in a large, deep pan with a lid and brown the lamb in batches, about 4 minutes on all sides. Set it aside.
3. Lower the heat to medium and fry the shallots in a little more oil for about 4 minutes, until caramelized. Then brown the carrots, turnips, celeriac and potatoes, cut into chunks, in batches, adding oil as needed.
4. Pour the wine into the pan with the sugar, herbs, 1 tsp of salt and plenty of pepper and boil for about 3 minutes.
5. Return the lamb, vegetables and wheat berries, add the broth, cover and boil for 5 minutes, then cook in the oven for 1 1/2 hours. If there''s a lot of liquid, boil it uncovered for a few minutes before serving.', 30, 150, 8, '$$$', array[]::text[], 'http://www.ottolenghi.co.uk/recipes/meat/irish-stew-shop', 'https://www.themealdb.com/images/media/meals/sxxpst1468569714.jpg', 'Photo from TheMealDB'),
  ('52938', 'Jamaican Beef Patties', 'Jamaican', '1. For the pastry, mix the flour with 1 tsp of the salt and the curry powder. Rub in the butter until it''s in small pieces coated with flour.
2. Mix in about 1/2 cup of ice water, then 2 to 3 tbsp at a time until it forms a dough. Cut it into 12 pieces, cover and chill for 30 minutes.
3. For the filling, mix the beef with the allspice and black pepper. Heat the oil in a skillet and cook the chopped onion until translucent, then the chopped Scotch bonnet, garlic and thyme for 1 minute, with the rest of the salt.
4. Add the beef and cook until no longer pink, breaking up any clumps. Stir in the ketchup and about 2 cups of water, bring to a boil and simmer until the liquid has reduced to a thick sauce. Let it cool completely.
5. Heat the oven to 350°F (180°C). Roll each piece of dough into a 5-inch circle, put 3 heaped tablespoons of filling on one half, wet the edges, fold over and crimp with a fork.
6. Beat the egg with a splash of water, brush it over the patties and bake on lined sheets for about 30 minutes, until golden.', 50, 60, 6, '$$', array[]::text[], 'https://www.thespruce.com/jamaican-beef-patties-recipe-2137762', 'https://www.themealdb.com/images/media/meals/wsqqsw1515364068.jpg', 'Photo from TheMealDB'),
  ('53354', 'Jamaican Curry Goat', 'Jamaican', '1. Rinse the goat meat. Mix it with 1 1/2 tbsp of the curry powder, the all-purpose seasoning, ground ginger, allspice, sliced onion, garlic and thyme. Marinate in the fridge for at least 4 hours or overnight.
2. Pick out the onion and garlic and set them aside. Heat the oil in a heavy pot and brown the goat for 2 to 3 minutes on each side. Set it aside.
3. Add a little more oil and the rest of the curry powder for 10 seconds, then the onion and garlic for about 4 minutes, until soft, adding a little water if dry.
4. Return the goat with the water, cover and simmer over low heat for about 2 hours, until tender, adding water as needed. (In a pressure cooker, cook for 40 minutes on high.)
5. Add the cubed potato and the whole Scotch bonnet and cook for 15 minutes more, until the potato is soft. Remove the pepper, season and serve with rice.', 20, 150, 6, '$$$', array[]::text[], 'https://www.myforkinglife.com/jamaican-curry-goat/#recipe', 'https://www.themealdb.com/images/media/meals/uc9qp11764796575.jpg', 'Photo from TheMealDB'),
  ('53349', 'Jamaican Pepper Shrimp', 'Jamaican', '1. Mix the shrimp with the minced Scotch bonnets, the all-purpose seasoning, annatto and allspice, and marinate for 10 minutes.
2. Bring the shrimp stock to a gentle simmer in a large pan over medium heat. Add the diced onion and garlic and cook for about 2 minutes.
3. Add the shrimp and thyme, cover and cook for 5 to 7 minutes, stirring now and then, until the shrimp are bright orange and cooked through.
4. Stir in the vinegar for 1 minute and add salt to taste. Serve hot with some of the cooking liquid.', 15, 10, 4, '$$', array['pescatarian']::text[], 'https://www.myforkinglife.com/jamaican-pepper-shrimp-recipe/#recipe', 'https://www.themealdb.com/images/media/meals/bx07m71764792853.jpg', 'Photo from TheMealDB'),
  ('53357', 'Jamaican Rice and Peas', 'Jamaican', '1. Put the rice, coconut milk, drained kidney beans, water, salt, allspice and pepper in a large pot and stir. Lay the green onions, thyme and whole Scotch bonnet on top.
2. Bring to a boil, then cover and cook over low heat for 18 minutes.
3. Take it off the heat and leave the lid on for 5 minutes more.
4. Remove the green onions, Scotch bonnet and thyme, fluff with a fork and serve.', 5, 25, 6, '$', array['vegan', 'vegetarian']::text[], 'https://www.myforkinglife.com/jamaican-rice-and-peas/#recipe', 'https://www.themealdb.com/images/media/meals/pkyvrn1764878267.jpg', 'Photo from TheMealDB'),
  ('53364', 'Jamaican Steamed Cabbage', 'Jamaican', '1. Shred the cabbage and slice the carrots, tomato, onion, garlic, green onions and Scotch bonnet.
2. Put everything in a large pan with the thyme, water, oil, butter, salt and pepper and cover.
3. Cook over medium heat for 10 minutes, stirring now and then, then lower the heat and cook for 5 minutes more, until the cabbage is tender. Remove the thyme stalks and serve.', 15, 15, 6, '$', array['vegetarian']::text[], 'https://www.myforkinglife.com/jamaican-cabbage/#recipe', 'https://www.themealdb.com/images/media/meals/paejva1765321314.jpg', 'Photo from TheMealDB'),
  ('53145', 'Jamon & wild garlic croquetas', 'Spanish', '1. Wash the wild garlic, pour boiling water over it until just wilted, rinse it under cold water, squeeze it dry and chop finely.
2. Warm the milk in a pan until steaming. In a second pan, warm the olive oil and stir in the flour for a couple of minutes, until lightly browned. Gradually add the milk until you have a thick, smooth sauce, and let it bubble for 1 to 2 minutes. Season.
3. Beat in the grated manchego, chopped ham and wild garlic. Spread it on an oiled plate, cover and chill for at least 1 hour.
4. With oiled hands, shape it into 18 to 20 balls and freeze them for 30 minutes to firm up.
5. Dip each ball in the beaten egg, then roll it in the breadcrumbs.
6. Heat the oil in a deep pan, no more than a third full, to 340°F (170°C). Fry the croquetas in batches for 2 to 3 minutes, until deep golden, and drain on paper towels. Serve warm.', 120, 20, 6, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/jamon-wild-garlic-croquetas', 'https://www.themealdb.com/images/media/meals/zc9cwz1763196177.jpg', 'Photo from TheMealDB'),
  ('52937', 'Jerk chicken with rice & peas', 'Jamaican', '1. For the jerk marinade, blend the juice of 1 lime, the green onions, ginger, garlic, onion, chilies, dried thyme, soy sauce, oil, brown sugar, allspice and 1 tsp of salt into a thick paste. Don''t add water. Taste and add more chili or sugar if needed.
2. Cut a few slashes in the chicken, rub the marinade in well, cover and marinate in the fridge overnight.
3. Heat the oven to 350°F (180°C). Roast the chicken in a roasting pan with the squeezed lime halves for about 45 minutes, until cooked through. (On a barbecue, cook it slowly over indirect heat for about 30 minutes.)
4. Meanwhile, rinse the rice and put it in a large saucepan with the coconut milk, thyme sprigs, a pinch of salt and 1 1/4 cups (300 ml) of cold water. Bring to a boil, then cover and cook over medium heat for 10 minutes.
5. Stir in the drained beans, cover and leave off the heat for 5 minutes, until the liquid is absorbed. Squeeze the roasted lime over the chicken and serve with the rice and peas.', 25, 45, 6, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/2369635/jerk-chicken-with-rice-and-peas', 'https://www.themealdb.com/images/media/meals/tytyxu1515363282.jpg', 'Photo from TheMealDB'),
  ('53398', 'Kadu Borani', 'Afghan', '1. Peel the squash and cut it into 1/2-inch (1 cm) slices. Deep-fry them in oil until golden and set aside.
2. Deep-fry the sliced onions in the same oil until golden, then grind them with the garlic into a paste.
3. Heat a little oil in a pan over medium heat and add the turmeric. Dissolve the salt in 1 cup of the water and add it. Layer the squash and the onion paste in the pan until both are used up.
4. Add the sugar and the rest of the water, lower the heat and cook until the water has reduced.
5. Spread some yogurt on a plate, put the squash on top, cover with more yogurt and finish with sliced green chili.', 20, 40, 4, '$', array['vegetarian']::text[], 'https://www.afghanaid.org.uk/kadu-borani-recipe', 'https://www.themealdb.com/images/media/meals/walmi81779552709.jpg', 'Photo from TheMealDB'),
  ('52971', 'Kafteji', 'Tunisian', '1. Peel the potatoes and cut them into 2-inch cubes. Heat about 1/2 inch of olive oil in a large pan until very hot and fry them for about 20 minutes, turning now and then, until golden. Drain on paper towels.
2. Meanwhile, rub the halved, seeded pepper with oil and broil it cut side down until the skin is blackened. Put it in a sealed bag for 15 minutes, then peel it.
3. In another pan, fry the onions, sliced into thin rings, in more oil for about 15 minutes, until golden, and add the ras el hanout at the end.
4. Cut the pumpkin into 2-inch cubes and fry it in the potato pan for 10 to 15 minutes, until soft and browned. Drain.
5. Pour off the oil, put all the vegetables back in the pan and mix. Pour the beaten eggs over them, cover and cook until set.
6. Tip everything onto a large board, season and chop it all together with a big knife.', 20, 50, 4, '$', array['vegetarian']::text[], 'http://allrecipes.co.uk/recipe/12294/kafteji--tunisian-fried-vegetables-.aspx', 'https://www.themealdb.com/images/media/meals/1bsv1q1560459826.jpg', 'Photo from TheMealDB'),
  ('52769', 'Kapsalon', 'Dutch', '1. Bake the fries until golden, as the package says, and spread them over a baking dish.
2. Cut the doner meat into strips and fry them in a little oil for about 6 minutes.
3. Spread the meat over the fries and cover with the cheese. Put it in the oven for a few minutes, until the cheese melts.
4. Chop the lettuce, tomato and cucumber into a simple salad and spread it over the top. Serve with garlic sauce and hot sauce.', 10, 20, 2, '$$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/sxysrt1468240488.jpg', 'Photo from TheMealDB'),
  ('53125', 'Karbonader (Lean Beef Patties) with Caramelized Onions', 'Norwegian', '1. Grate half an onion and slice the rest. Fry the sliced onions in 2 tbsp of the butter over low to medium heat until caramelized.
2. Mix the beef with the grated onion, salt, pepper, nutmeg, cornstarch and water.
3. Shape it into a log and cut it into 6 patties. Mark a light crisscross pattern on each with a knife.
4. Brown the patties on both sides in the rest of the butter over high heat, then lower the heat and cook for 2 to 3 minutes more.
5. Serve with the onions and boiled potatoes.', 10, 25, 3, '$', array[]::text[], 'https://scandinaviancookbook.com/karbonader/', 'https://www.themealdb.com/images/media/meals/0bpjb11763075817.jpg', 'Photo from TheMealDB'),
  ('53445', 'Kaspressknödel - Cheese Dumplings', 'Austrian', '1. Mix the cubed bread with the milk and a pinch of salt and let it soak for a while.
2. Add the grated potatoes, grated cheese, eggs and chopped parsley.
3. Fry the diced onion in a little butter until golden and add it to the mixture.
4. Add the flour and knead gently. Shape into round dumplings and press them flat.
5. Fry them in butter on both sides until golden brown. Serve in a clear broth or with a salad.', 25, 25, 4, '$', array['vegetarian']::text[], 'https://www.austria.info/en-gb/recipes/cheese-dumplings/', 'https://www.themealdb.com/images/media/meals/x26z3y1780155760.jpg', 'Photo from TheMealDB'),
  ('52820', 'Katsu Chicken curry', 'Japanese', '1. For the sauce, heat a little of the oil in a medium non-stick saucepan and cook the chopped onions and garlic until soft. Add the chopped carrots and cook over low heat for 10 to 12 minutes.
2. Stir in 1 tbsp of the flour and the curry powder for 1 minute. Gradually stir in the broth, then add the honey, soy sauce and bay leaf and slowly bring to a boil.
3. Simmer for about 20 minutes, until thickened but still pourable. Stir in the garam masala, strain the sauce and keep it warm.
4. Season the chicken. Coat each breast in the rest of the flour, then the beaten egg, then the breadcrumbs.
5. Heat the rest of the oil in a large frying pan over medium-high heat and fry the chicken for 3 to 4 minutes on each side, until golden and cooked through. Drain on paper towels.
6. Slice the chicken, pour the curry sauce over it and serve with white rice.', 15, 45, 4, '$$', array[]::text[], 'http://allrecipes.co.uk/recipe/29578/chicken-katsu-curry.aspx', 'https://www.themealdb.com/images/media/meals/vwrpps1503068729.jpg', 'Photo from TheMealDB'),
  ('52887', 'Kedgeree', 'British', '1. Heat the oil in a large pan with a lid and gently fry the chopped onion for 5 minutes, until soft but not colored. Add the coriander and curry powder, season with salt and fry for about 3 minutes, until fragrant.
2. Stir in the rice, add 2 1/2 cups (600 ml) of water and bring to a boil. Cover and simmer for 10 minutes, then take it off the heat and leave it covered for 10 to 15 minutes more, without lifting the lid.
3. Meanwhile, put the haddock and bay leaves in a frying pan, cover with the milk and poach for 10 minutes, until the fish flakes. Remove the skin and break the fish into large flakes.
4. Boil the eggs for 4 1/2 to 5 minutes, cool them in cold water, peel them and cut them into quarters.
5. Gently mix the fish, eggs, chopped parsley and cilantro into the rice and serve hot, with a few extra herbs on top.', 10, 35, 4, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/10421/kedgeree', 'https://www.themealdb.com/images/media/meals/utxqpt1511639216.jpg', 'Photo from TheMealDB'),
  ('53449', 'Kelem dolmasi', 'Azerbaijani', '1. Boil the rice for 8 minutes and drain. Finely chop the onion and herbs, and roughly mash the drained chickpeas.
2. Mix the lamb with the minced lamb fat, onion, turmeric, cinnamon, chickpeas, rice and herbs, and season well with salt and pepper.
3. Bring a very large pot of salted water to a boil. Pull off the outer cabbage leaves and keep them. Boil the rest of the cabbage whole for 3 to 4 minutes, then peel off the softened leaves. Repeat until you have all the leaves you can use.
4. Cut out the tough stalks and halve the largest leaves. Put a heaped tablespoon of filling on each leaf, fold in the ends and roll it up tightly.
5. Line the bottom of a large pot with the outer leaves and stalks and lay the rolls on top. Add water up to the top of the lining leaves, weigh the rolls down with a heatproof plate and simmer for 25 minutes.
6. Heat the tomato paste with the water for a few minutes, pour it over the rolls and cook for 5 minutes more.', 45, 35, 4, '$$', array[]::text[], 'https://travelbystove.blogspot.com/2012/01/recipes-from-azerbaijani.html', 'https://www.themealdb.com/images/media/meals/7vdtqi1780160088.jpg', 'Photo from TheMealDB'),
  ('53112', 'Kenyan Beef Curry', 'Kenyan', '1. Bring the water to a boil in a large pot. Add the cubed beef, crushed garlic and ginger, cover and simmer gently for 20 minutes, stirring now and then. Drain, keeping the cooking water.
2. Heat the oil in the same pot over medium heat and cook the chopped onions for 5 to 7 minutes, until soft. Add the chopped tomatoes and cook for 3 to 5 minutes, until falling apart.
3. Add the beef and cook for 5 minutes, stirring now and then. Stir in the paprika, pepper, curry powder, tomato paste and salt to taste.
4. Pour back the cooking water, with extra water to cover. Bring to a boil and simmer uncovered for about 1 hour, stirring now and then, until the meat is tender and the sauce thick. Add water if it starts to stick.
5. Taste, adjust the seasoning and garnish with sliced chili and cilantro.', 15, 95, 4, '$$', array[]::text[], 'https://tasteoftheplace.com/kenyan-beef-curry/', 'https://www.themealdb.com/images/media/meals/lqampv1762325397.jpg', 'Photo from TheMealDB'),
  ('53494', 'Keto Banitsa', 'Bulgarian', '1. Heat the oven to 360°F (180°C) and butter an 8 x 8-inch baking dish.
2. Beat the eggs in a bowl, then slowly whisk in the melted butter.
3. Stir in the grated mozzarella, crumbled feta and cream cheese, then whisk in the baking powder.
4. Pour it into the dish, sprinkle with sesame seeds if you like and bake for about 20 minutes, until golden.
5. Let it cool in the dish for 5 to 10 minutes, then cut it into pieces.', 10, 25, 6, '$', array['vegetarian']::text[], 'https://cookinglsl.com/keto-banitsa/#wprm-recipe-container-43619', 'https://www.themealdb.com/images/media/meals/8wynv41782686271.jpg', 'Photo from TheMealDB'),
  ('52868', 'Kidney Bean Curry', 'Indian', '1. Heat the oil in a large frying pan over low-medium heat. Cook the chopped onion with a pinch of salt, stirring now and then, until soft and starting to color.
2. Add the garlic, grated ginger and chopped cilantro stalks and cook for 2 minutes, until fragrant. Add the cumin, paprika and garam masala for 1 minute more.
3. Tip in the tomatoes and the kidney beans with their liquid and bring to a boil. Lower the heat and simmer for 15 minutes, until thick.
4. Meanwhile, cook the rice. Season the curry and serve with the rice and the cilantro leaves.', 5, 30, 2, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/kidney-bean-curry', 'https://www.themealdb.com/images/media/meals/sywrsu1511463066.jpg', 'Photo from TheMealDB'),
  ('53027', 'Koshari', 'Egyptian', '1. Rinse the rice and soak it in water while you cook the lentils. Boil the lentils in 4 cups of water, then simmer for 15 to 17 minutes, until just tender but still firm. Drain and season with a little salt.
2. Drain the rice and cook it with the lentils, 1 tbsp of the oil, salt, pepper and the coriander over medium-high heat for 3 minutes, stirring.
3. Add warm water to cover by about 1 1/2 inches (about 3 cups), bring to a boil, then cover and cook over low heat for about 20 minutes, until the liquid is absorbed. Leave covered for 5 minutes.
4. Meanwhile, cook the macaroni in salted boiling water until al dente and drain. Warm the drained chickpeas.
5. Fry the onion, sliced into thin rings and salted, in the rest of the oil over medium-high heat for 15 to 20 minutes, stirring often, until deep brown and crisp.
6. Serve the rice and lentils topped with the pasta, chickpeas and crispy onions.', 15, 60, 6, '$', array['vegan', 'vegetarian']::text[], 'https://www.themediterraneandish.com/egyptian-koshari-recipe/', 'https://www.themealdb.com/images/media/meals/4er7mj1598733193.jpg', 'Photo from TheMealDB'),
  ('52978', 'Kumpir', 'Turkish', '1. Heat the oven to 400°F (200°C). Prick the potatoes and bake them for about 1 1/2 hours, until the skins are crisp and the inside is very soft.
2. Meanwhile, grate the cheese and finely chop the onion and red pepper.
3. Split each potato open and mash the butter into the flesh with a fork, then mix in most of the cheese.
4. Top with the onion, pepper, the rest of the cheese, salt, pepper and some pepper flakes if you like. Add any other toppings you enjoy, such as corn or olives.', 15, 90, 2, '$', array['vegetarian']::text[], 'http://www.turkeysforlife.com/2013/10/firinda-kumpir-turkish-street-food.html', 'https://www.themealdb.com/images/media/meals/mlchx21564916997.jpg', 'Photo from TheMealDB'),
  ('52945', 'Kung Pao Chicken', 'Chinese', '1. Mix the sake, soy sauce and sesame oil with the cornstarch dissolved in the water, and divide it in half.
2. Toss the chicken, cut into pieces, with half of the mixture, cover and chill for about 30 minutes.
3. In a frying pan, mix the other half with the chili powder, vinegar and sugar, then add the chopped green onions and garlic, the water chestnuts and the peanuts. Heat slowly over medium heat until fragrant.
4. Meanwhile, cook the chicken in a little oil in a large frying pan until cooked through.
5. Add the chicken to the sauce and simmer together until the sauce thickens. Serve with rice.', 40, 15, 4, '$$', array[]::text[], 'http://allrecipes.co.uk/recipe/1773/kung-pao-chicken.aspx', 'https://www.themealdb.com/images/media/meals/1525872624.jpg', 'Photo from TheMealDB'),
  ('52946', 'Kung Po Prawns', 'Chinese', '1. Mix the cornstarch with 1 tbsp of the soy sauce, toss in the shrimp and set aside for 10 minutes. Stir the rest of the soy sauce, the tomato paste, both sugars and 2 tbsp of water together into a sauce.
2. Heat a large frying pan or wok until very hot, add the oil and fry the shrimp until golden in places. Tip them out.
3. Add the peanuts, sliced chilies and sliced water chestnuts and stir-fry for 2 minutes, until the peanuts start to color. Add the grated ginger and garlic for 1 minute more.
4. Return the shrimp, pour in the sauce and simmer for 2 minutes, until slightly thick. Serve with rice.', 20, 10, 4, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/1415664/kung-po-prawns', 'https://www.themealdb.com/images/media/meals/1525873040.jpg', 'Photo from TheMealDB'),
  ('53412', 'Lakra me Mish Cabbage and Meat Stew', 'Albanian', '1. Heat some olive oil in a large pan with a lid. Add the chopped onion, diced beef and sliced peppers and fry for 5 minutes, stirring, until the meat is browned.
2. Add the paprika, tomato paste and pepper flakes, season and fry for 2 minutes.
3. Add the chopped cabbage and fry for 3 to 5 minutes, stirring now and then.
4. Pour in the boiling water so it covers the cabbage by about 1 inch, cover and bring to a boil.
5. Simmer for 2 1/2 hours, until the cabbage is soft and the meat tender. Let it cool for 5 minutes before serving.', 20, 160, 4, '$$', array[]::text[], 'https://www.myalbanianfood.com/recipe/lakra-me-mish/', 'https://www.themealdb.com/images/media/meals/mobh1l1779648766.jpg', 'Photo from TheMealDB'),
  ('53407', 'Lakror me Kungull Summer Squash Pie', 'Albanian', '1. Heat the oven to 350°F (180°C). Grate the squash and mix it with the eggs and baking powder.
2. Add the flour and mix to a thick, sticky batter, adding a little more flour if it''s runny.
3. Rub a deep round baking pan with olive oil and spread the batter in it. Rub a little oil over the top with your hand to smooth it.
4. Bake for about 40 minutes, until golden brown. Let it cool before cutting into squares.', 15, 40, 8, '$', array['vegetarian']::text[], 'https://www.myalbanianfood.com/recipe/summer-squash-pie/', 'https://www.themealdb.com/images/media/meals/ae4rwb1779645576.jpg', 'Photo from TheMealDB'),
  ('52821', 'Laksa King Prawn Noodles', 'Malaysian', '1. Heat the oil in a medium saucepan and cook the sliced chili for 1 minute. Add the curry paste and cook for 1 minute more.
2. Dissolve the stock cube in 3 cups (700 ml) of boiling water, pour it into the pan, add the coconut milk and bring to a boil.
3. Add the fish sauce and a little seasoning, then the noodles, and cook for 3 to 4 minutes, until soft.
4. Squeeze in the juice of 1 lime, add the shrimp and cook for 2 to 3 minutes, until hot through.
5. Serve in bowls with the cilantro and the other lime cut into wedges.', 5, 15, 2, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/prawn-laksa-curry-bowl', 'https://www.themealdb.com/images/media/meals/rvypwy1503069308.jpg', 'Photo from TheMealDB'),
  ('52877', 'Lamb and Potato pie', 'British', '1. Dice the lamb and dust it lightly with the flour.
2. Heat a thin layer of oil in a large saucepan and fry the chopped onion and lamb until lightly browned. Season.
3. Add the sliced carrots and the broth, bring to a boil, then cover and simmer for at least 1 hour, until the meat is tender.
4. Heat the oven to 350°F (180°C). Boil the cubed potatoes until just tender, drain and add them to the lamb.
5. Pour into a pie dish, cover with the pastry and cut three slits in the top. Brush with beaten egg and bake for about 40 minutes, until golden.', 20, 110, 4, '$$', array[]::text[], 'https://www.bbc.co.uk/food/recipes/lambandpotatopie_83913', 'https://www.themealdb.com/images/media/meals/sxrpws1511555907.jpg', 'Photo from TheMealDB'),
  ('52805', 'Lamb Biryani', 'Indian', '1. Grind half of the cashews with the poppy seeds and cumin seeds into a smooth paste, using as little water as possible.
2. Deep-fry the sliced onions until light brown and drain them on paper towels. Fry the rest of the cashews until golden. Rinse the rice and soak it for 20 minutes.
3. Heat the ghee in a large, wide pan over medium heat. Fry the cashew paste, ginger-garlic paste, chopped garlic, cinnamon, cloves, cardamom and bay leaf for 1 minute.
4. Stir in the chili powder, biryani masala and half of the chopped mint and cilantro. Take it off the heat, stir in the yogurt, then return it to the heat.
5. Add the lamb, salt and 1/2 cup of water. Cover and cook over medium-low heat for about 1 hour, until tender. Uncover to dry off any extra liquid.
6. Boil the drained rice in plenty of salted water for 7 minutes, until 80% cooked, and drain. Spread it over the lamb and top with the fried onions and cashews, the rest of the herbs and the saffron soaked in a spoonful of warm water.
7. Cover tightly and cook over medium heat for 12 minutes, then over the lowest heat for 5 minutes. Mix gently and serve hot.', 40, 90, 4, '$$', array[]::text[], 'http://www.relishthebite.com/restaurant-style-lamb-biryani/', 'https://www.themealdb.com/images/media/meals/xrttsx1487339558.jpg', 'Photo from TheMealDB'),
  ('53083', 'Lamb Pilaf (Plov)', 'Russian', '1. Cover the prunes with water, add the lemon juice and soak for at least 1 hour. Drain and chop them.
2. Meanwhile, heat the butter in a large pan and cook the chopped onion for 5 minutes. Add the cubed lamb and crushed garlic and fry for 5 minutes, stirring, until browned.
3. Pour in 2/3 cup (150 ml) of the broth, bring to a boil, then cover and simmer for 1 hour, until the lamb is tender.
4. Add the rest of the broth and bring to a boil. Stir in the rinsed rice and a large pinch of saffron, cover and simmer for about 15 minutes, until the rice is tender.
5. Stir in the prunes, season and heat through for a few minutes. Serve on a warm dish with parsley.', 70, 85, 4, '$$', array[]::text[], 'https://www.thespruceeats.com/russian-lamb-pilaf-plov-recipe-1137309', 'https://www.themealdb.com/images/media/meals/kos9av1699014767.jpg', 'Photo from TheMealDB'),
  ('52843', 'Lamb Tagine', 'Moroccan', '1. Heat the olive oil in a heavy pan and cook the chopped onion and carrots for 3 to 4 minutes, until soft.
2. Add the diced lamb and brown it all over. Stir in the garlic, grated ginger, cumin, saffron and cinnamon and cook for a few minutes, until fragrant.
3. Add the honey and apricots, crumble in the stock cube and pour in about 2 cups (500 ml) of boiling water, enough to cover the meat. Bring to a boil, then cover and simmer for 1 hour.
4. Uncover and cook for 30 minutes more, then stir in the cubed squash. Cook for 20 to 30 minutes, until the squash is soft and the lamb tender.
5. Serve with couscous and chopped parsley.', 15, 125, 5, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/2303638/family-meals-easy-lamb-tagine-', 'https://www.themealdb.com/images/media/meals/yuwtuu1511295751.jpg', 'Photo from TheMealDB'),
  ('52782', 'Lamb tomato and sweet spices', 'Moroccan', '1. Drain the vine leaves, soak them in boiling water for 10 minutes and dry them on a towel.
2. For the filling, mix the lamb with the chopped onion, grated potato, rice, parsley, cilantro, cloves and cinnamon. Halve 2 of the tomatoes, grate them into the bowl and throw away the skins. Add 1/2 tsp of salt and some pepper, then squeeze out any juice.
3. For the sauce, heat the oil in a medium pan and cook the grated ginger and crushed garlic for 1 to 2 minutes. Grate in the rest of the tomatoes, add the lemon juice and sugar, season and simmer for 20 minutes.
4. Line a wide, heavy pan with any torn leaves and cover the bottom with the fennel, cut into 1/4-inch slices.
5. Put 2 teaspoons of filling at the base of each leaf, fold in the sides and roll it up tightly. Pack the rolls seam side down in the pan.
6. Pour the sauce over them, adding water just to cover. Weigh them down with a plate, cover, bring to a boil and simmer very gently for 70 minutes, until most of the liquid has gone. Serve warm with rice.', 50, 90, 4, '$$', array[]::text[], 'http://www.ottolenghi.co.uk/recipes/meat/lamb-tomato-and-sweet-spices-shop', 'https://www.themealdb.com/images/media/meals/qtwtss1468572261.jpg', 'Photo from TheMealDB'),
  ('53427', 'Lao Naem Khao', 'Laotian', '1. Thinly slice the onion and shallot and soak them in ice water while you cook.
2. Mix the cooked rice with the grated coconut using your hands, and roll it into 2-inch balls.
3. Heat oil for deep-frying. Dip each ball in the beaten eggs and fry until deep golden and crunchy. Drain on paper towels and let them cool.
4. Break the rice balls into pieces in a large bowl. Add the drained onion and shallot, the sausage torn into small pieces, the chopped pickled garlic, the lime juice, fish sauce, sugar, sliced green onions, cilantro and mint, and mix.
5. Top with the peanuts and serve with lettuce leaves and fresh vegetables.', 20, 25, 6, '$$', array[]::text[], 'https://cookingwithlane.com/naem-khao-crispy-coconut-rice-salad/', 'https://www.themealdb.com/images/media/meals/0dypw51779817467.jpg', 'Photo from TheMealDB'),
  ('52987', 'Lasagna Sandwiches', 'American', '1. Mix the sour cream, finely chopped onion, oregano and salt, and spread it on 4 slices of bread.
2. Cook the bacon until crisp.
3. Layer the bacon, tomato and cheese on the bread and top with the other slices.
4. Melt 2 tbsp of the butter in a large skillet and toast the sandwiches on both sides until browned and the cheese melts, adding more butter if needed.', 10, 15, 4, '$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/xr0n4r1576788363.jpg', 'Photo from TheMealDB'),
  ('52973', 'Leblebi Soup', 'Tunisian', '1. Soak the dried chickpeas overnight and drain them.
2. Heat the oil in a large pot and cook the chopped onion until translucent. Add the chickpeas and broth, bring to a boil, then cover and simmer for 30 minutes.
3. Toast the cumin in a dry pan, then pound it with the garlic and salt into a fine paste.
4. Stir the paste and harissa into the soup and simmer for about 30 minutes more, until the chickpeas are tender.
5. Season with pepper and lime juice and serve hot.', 10, 65, 4, '$', array['vegan', 'vegetarian']::text[], 'http://allrecipes.co.uk/recipe/43419/leblebi--tunisian-chickpea-soup-.aspx', 'https://www.themealdb.com/images/media/meals/x2fw9e1560460636.jpg', 'Photo from TheMealDB'),
  ('53437', 'Leg of Lamb Armenian-Style', 'Armenian', '1. Put the lamb in a roasting pan with the crushed garlic, chopped parsley, onion and mint, the pepper, vinegar, olive oil and salt. Turn it to coat.
2. Cover and marinate in the fridge for 2 days, turning it now and then.
3. Heat the oven to 350°F (180°C) and roast for 1 to 1 1/2 hours, until cooked the way you like. Let it rest before slicing.', 15, 90, 8, '$$$', array[]::text[], 'https://www.armenianmuseum.org/armenian-recipes/leg-of-lamb-armenian-style', 'https://www.themealdb.com/images/media/meals/vy6k391780090969.jpg', 'Photo from TheMealDB'),
  ('52947', 'Ma Po Tofu', 'Chinese', '1. Mix the beef with a pinch of salt and the sesame oil. Mix the cornstarch with 2 1/2 tbsp of water.
2. Cut the tofu into 3/4-inch cubes. Simmer them in salted boiling water for 1 minute and drain.
3. Heat the oil in a wok and fry the beef until crisp. Lift it out, leaving the oil.
4. Fry the doubanjiang over low heat for 1 minute, then add the chopped garlic, the white parts of the green onions, the ginger and the fermented black beans for 30 seconds. Stir in the pepper flakes.
5. Add the water and bring to a boil. Slide in the tofu, add the soy sauce and beef and simmer gently for 6 to 8 minutes.
6. Stir in the cornstarch mixture in two parts, 30 seconds apart, until the sauce coats the tofu. Sprinkle with ground Sichuan pepper and the green parts of the onions and serve with rice.', 15, 20, 4, '$', array[]::text[], 'https://www.chinasichuanfood.com/mapo-tofu-recipe/', 'https://www.themealdb.com/images/media/meals/1525874812.jpg', 'Photo from TheMealDB'),
  ('53461', 'Macaroni Pie', 'Caribbean', '1. Cook the macaroni in salted boiling water for about 8 minutes, until tender. Heat the oven to 350°F (180°C).
2. Drain the macaroni, return it to the hot pan and mix in the butter, then most of the grated cheese.
3. Whisk the egg until fluffy and add the milk, onion powder, mustard, black pepper, salt and cayenne. Mix it into the macaroni.
4. Pour into a greased baking dish and top with the rest of the cheese and the breadcrumbs.
5. Bake for 30 to 45 minutes, depending on the depth of the dish, until set and golden.', 15, 50, 6, '$', array['vegetarian']::text[], 'https://www.totallybarbados.com/articles/barbados-recipes/macaroni-pie-recipe/', 'https://www.themealdb.com/images/media/meals/kpiu4t1782242131.jpg', 'Photo from TheMealDB'),
  ('52827', 'Massaman Beef curry', 'Thai', '1. Heat the oven to 400°F (200°C) and roast the peanuts on a baking sheet for 5 minutes, until golden. Chop them roughly. Lower the oven to 350°F (180°C).
2. Heat 2 tbsp of the coconut cream in a large casserole with a lid. Fry the curry paste for 1 minute, then stir in the cubed beef until coated.
3. Add the rest of the coconut cream with 3/4 cup of water, the cubed potatoes, the chopped onion, lime leaves, cinnamon, tamarind, sugar, fish sauce and most of the peanuts.
4. Bring to a simmer, cover and cook in the oven for 2 hours, until the beef is tender.
5. Sprinkle with the sliced chili and the rest of the peanuts and serve with jasmine rice.', 15, 130, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/420631/beef-massaman-curry', 'https://www.themealdb.com/images/media/meals/tvttqv1504640475.jpg', 'Photo from TheMealDB'),
  ('53400', 'Mastawa Lamb and Rice', 'Afghan', '1. Put the lamb, cut into pieces, in a large pan with the chopped onions and the turmeric, and add water to cover. Bring to a boil, then simmer gently for about 1 1/2 hours, until the meat comes off the bones easily.
2. Meanwhile, cut the orange peel into thin matchsticks, removing as much white pith as you can, and soak it in a bowl of water.
3. Lift out the meat, pull it off the bones in strips and return it to the pan.
4. Rinse the rice and add it with salt to taste. The liquid should cover the rice by about 3/4 inch, so add water if needed. Bring back to a boil and cook uncovered over medium heat, stirring now and then, until the rice is al dente and the liquid absorbed.
5. Carefully stir in the yogurt. Fry the crushed garlic in the oil and add it with the dill, pepper, drained chickpeas and drained orange peel. Season.
6. Cover the pan with a clean towel and the lid and leave on low heat for about 30 minutes. Serve with warm naan.', 20, 150, 4, '$$', array[]::text[], 'https://www.afghanaid.org.uk/mastawa-recipe', 'https://www.themealdb.com/images/media/meals/4kzx4d1779554755.jpg', 'Photo from TheMealDB'),
  ('52865', 'Matar Paneer', 'Indian', '1. Heat the oil in a frying pan over high heat. Add the cubed paneer, lower the heat a little and brown it on all sides. It browns quickly, so don''t walk away. Drain it on paper towels.
2. Fry the grated ginger, cumin, turmeric, coriander and chopped chili in the pan for 1 minute.
3. Add the chopped tomatoes, mash them with a spoon and simmer for 5 minutes, adding a splash of water if it''s too thick. Season well.
4. Add the peas and simmer for 2 minutes, then stir in the paneer and sprinkle with the garam masala. Top with cilantro and serve with naan, roti or rice.', 15, 15, 2, '$$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/matar-paneer', 'https://www.themealdb.com/images/media/meals/xxpqsy1511452222.jpg', 'Photo from TheMealDB'),
  ('52968', 'Mbuzi Choma (Roasted Goat)', 'Kenyan', '1. Season the goat meat with salt and roast it over a medium charcoal fire for about 50 minutes, turning and salting it as you go. Without a grill, roast it in a 375°F (190°C) oven.
2. For the ugali, bring about 4 cups of water with a pinch of salt to a boil in a heavy saucepan. Slowly pour in the cornmeal, stirring.
3. Lower the heat to medium-low and keep stirring, pressing out any lumps, for about 10 minutes, until very thick and pulling away from the pan. Shape it into a ball with wet hands.
4. For the kachumbari, mix the chopped tomatoes, onion, chili and cilantro. Serve the goat with the ugali and the salad.', 15, 60, 4, '$$$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/cuio7s1555492979.jpg', 'Photo from TheMealDB'),
  ('53423', 'Meang Nem', 'Cambodian', '1. Rinse the rice, soak it for 10 minutes and drain well. Toast it in a dry wok over medium heat, stirring all the time, for about 5 minutes, until dark golden. Let it cool, then grind it finely and sift it.
2. Thinly slice the shallots and finely chop the galangal, pickled scallions, chilies and orange zest. Roast and coarsely grind the peanuts. Toast the coconut in a dry pan over low heat for 2 to 3 minutes.
3. Stir the lime juice, orange juice, palm sugar, pickling brine and fish sauce together until the sugar dissolves.
4. Mix the dried shrimp, toasted coconut, chopped aromatics and dressing, then stir in the rice powder. Top with the peanuts.
5. Serve on a large plate and let everyone wrap a little in lettuce leaves with fresh vegetables.', 30, 10, 4, '$$', array['pescatarian']::text[], 'https://www.chefnak.com/meang-nem', 'https://www.themealdb.com/images/media/meals/5rk8vc1779740302.jpg', 'Photo from TheMealDB'),
  ('52777', 'Mediterranean Pasta Salad', 'Italian', '1. Cook the pasta in a large pan of salted boiling water for about 10 minutes, or as the package says.
2. Meanwhile, quarter the tomatoes and slice the olives. Put the tomatoes in a salad bowl, tear the basil over them and mix with 1 tbsp of the oil.
3. Drain the pasta and cool it under cold running water.
4. Toss it with the tomatoes, then add the olives, the drained mozzarella and the tuna in chunks. Mix and let it rest for at least 30 minutes.
5. Just before serving, add plenty of black pepper and drizzle with the rest of the oil.', 40, 10, 4, '$$', array['pescatarian']::text[], 'https://thelemonsqueezy.com/recipe/mediterranean-pasta-salad/', 'https://www.themealdb.com/images/media/meals/wvqpwt1468339226.jpg', 'Photo from TheMealDB'),
  ('53048', 'Mee goreng mamak', 'Malaysian', '1. Fry the peanuts, dried chilies and dried shrimp in 1 tbsp of the oil over medium heat until fragrant. Blend them with the tamarind paste and the water until fine.
2. Cook this paste in 2 tbsp of the oil over low heat until the oil separates and it turns darker.
3. Boil the potatoes, cut into small chunks, until tender, and drain. Slice the onions and tofu, mince the garlic and cut up the cabbage and Chinese broccoli. If the noodles are dried, boil them to soften. Mix the soy sauce with a splash of water.
4. Cook one portion at a time: heat a little oil in a wok and add a quarter of the garlic, onion and paste. Cook until fragrant, then add a quarter of the tofu, potatoes and greens for 30 seconds.
5. Add a quarter of the noodles and 3 tbsp of the soy mixture and toss for 1 minute. Push the noodles aside, scramble in a quarter of the egg, then mix. Repeat for the other portions.', 30, 20, 4, '$', array['pescatarian']::text[], 'https://www.nyonyacooking.com/recipes/mee-goreng-mamak~BkTLRjTuX', 'https://www.themealdb.com/images/media/meals/xquakq1619787532.jpg', 'Photo from TheMealDB'),
  ('52927', 'Montreal Smoked Meat', 'Canadian', '1. For the cure, mix the salt with 3 tbsp of the pepper, 1 tbsp of the coriander, the sugar, bay leaf and cloves. Rub it all over the brisket, put it in a large zip-top bag and cure it in the coldest part of the fridge for 4 days, turning it twice a day.
2. Rinse off as much of the cure as you can and soak the brisket in cold water for 2 hours, changing the water every 30 minutes. Pat it dry.
3. For the rub, mix the rest of the pepper and coriander with the paprika, garlic powder, onion powder, dill, mustard, celery salt and pepper flakes. Coat the brisket all over.
4. Smoke it at 225°F (110°C), fat side up, for about 6 hours, until it reaches 165°F inside. Without a smoker, cook it on a rack in a 225°F oven.
5. Put the brisket on a rack in a roasting pan with 1 inch of water, cover with foil and steam it over two burners on medium heat for 1 to 2 hours, until it reaches 180°F, adding hot water as needed.
6. Let it cool slightly, then slice it and serve on rye bread with mustard.', 60, 450, 10, '$$', array[]::text[], 'http://www.meatwave.com/blog/montreal-smoked-meat-recipe', 'https://www.themealdb.com/images/media/meals/uttupv1511815050.jpg', 'Photo from TheMealDB'),
  ('53047', 'Moroccan Carrot Soup', 'Moroccan', '1. Heat the oven to 350°F (180°C). Toss the chopped carrots, onion and garlic with the cumin, coriander, a pinch of salt and the oil, and spread them on a baking sheet.
2. Roast for 10 to 12 minutes, until the carrots soften. Let them cool.
3. Blend with a little water into a smooth purée and strain it into a pan.
4. Add 2 cups of water, bring to a boil and stir in the garam masala and salt to taste.
5. Take it off the heat, stir in the lemon juice and serve hot.', 10, 25, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.sanjeevkapoor.com/Recipe/Moroccan-Carrot-Soup.html', 'https://www.themealdb.com/images/media/meals/jcr46d1614763831.jpg', 'Photo from TheMealDB'),
  ('53006', 'Moussaka', 'Greek', '1. Heat the broiler to high. Brown the beef in a deep ovenproof frying pan over high heat for 5 minutes.
2. Meanwhile, prick the eggplant with a fork and microwave it on high for 3 to 5 minutes, until soft. Mix the yogurt, egg and parmesan and season.
3. Stir the chopped tomatoes, tomato paste and diced cooked potatoes into the beef, season and heat through. Smooth the top.
4. Slice the eggplant and lay it on top, pour the yogurt mixture over it and spread it evenly.
5. Broil until the topping has set and turned golden.', 10, 25, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/must-make-moussaka', 'https://www.themealdb.com/images/media/meals/ctg8jd1585563097.jpg', 'Photo from TheMealDB'),
  ('53029', 'Mulukhiyah', 'Egyptian', '1. Cook the chopped onion in 3 to 4 tbsp of the olive oil until soft.
2. Add the cubed beef and sear it for 3 to 4 minutes on each side.
3. Pour in the water, or just enough to cover, and cook over medium heat for about 45 minutes, until the meat is tender.
4. Add the frozen mulukhiyah and stir until it thaws and comes to a boil.
5. In another pan, warm the rest of the oil with the crushed garlic over medium-low heat until fragrant, without browning it. Stir it into the soup and simmer for 5 to 10 minutes. Add the salt and serve with lemon juice and rice or pita.', 10, 60, 4, '$$', array[]::text[], 'https://chefindisguise.com/2017/05/15/mulukhiyah-a-stew-fit-for-royals/', 'https://www.themealdb.com/images/media/meals/x372ug1598733932.jpg', 'Photo from TheMealDB'),
  ('52864', 'Mushroom & Chestnut Rotolo', 'British', '1. Soak the dried mushrooms in 1 1/2 cups (350 ml) of boiling water. Blend three quarters of the chestnuts with 2/3 cup (150 ml) of water until creamy, and chop the rest.
2. Heat 2 tbsp of olive oil in a large non-stick frying pan and fry the chopped shallots with a pinch of salt until soft. Add the garlic, chopped chestnuts and rosemary for 2 minutes, then the wild mushrooms with 2 more tbsp of oil, and cook for 3 minutes.
3. Drain and chop the soaked mushrooms, keeping the liquid, and add them with the soy sauce for 2 minutes more.
4. Whisk the wine, mushroom liquid and chestnut cream into a sauce and season. Add half of it to the pan and cook for 1 minute, until glossy. Remove the rosemary.
5. Heat the oven to 350°F (180°C). Cook the lasagne sheets in salted boiling water for 2 minutes, then plunge them into ice water and lay them on a towel. Spread the mushroom mixture over each, roll them up from the short end and cut each roll in half.
6. Stand the rolls cut side up in a baking dish, pour the rest of the sauce over and bake for 10 minutes. Toss the breadcrumbs with 2 tbsp of oil and the sage, scatter them over and bake for 10 minutes more, until golden. Drizzle with truffle oil if you like.', 60, 40, 4, '$$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/mushroom-chestnut-rotolo', 'https://www.themealdb.com/images/media/meals/ssyqwr1511451678.jpg', 'Photo from TheMealDB'),
  ('53059', 'Mushroom soup with buckwheat', 'Croatian', '1. Chop the onion and garlic, slice the mushrooms and rinse the buckwheat.
2. Heat the oil and lightly fry the onion, then add the mushrooms and garlic and keep frying.
3. Add salt, the stock cube, the buckwheat and the bay leaf, cover with water and simmer gently for about 20 minutes.
4. Just before it''s done, stir in the sour cream mixed with the flour, pepper, chopped parsley and vinegar to taste.', 10, 30, 2, '$', array['vegetarian']::text[], 'https://www.visit-croatia.co.uk/croatian-cuisine/croatian-recipes/', 'https://www.themealdb.com/images/media/meals/1ngcbf1628770793.jpg', 'Photo from TheMealDB'),
  ('53038', 'Mustard champ', 'Irish', '1. Boil the potatoes for about 15 minutes, until tender. Drain and mash them.
2. Heat the milk and half of the butter in a corner of the pan, then beat them into the mash with the mustard.
3. Gently fry the sliced green onions in the rest of the butter for 2 minutes, until just soft but still bright green. Fold them into the mash and serve.', 10, 20, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/mustard-champ', 'https://www.themealdb.com/images/media/meals/o7p9581608589317.jpg', 'Photo from TheMealDB'),
  ('53223', 'Mutabbaq', 'Saudi Arabian', '1. Heat a little oil in a frying pan and fry the crushed garlic and ginger, then add the ground beef and all the spices, the salt and the sugar. Cook until the meat is done, then let it cool.
2. Mix the meat with the egg, chopped tomato and chopped green onions.
3. Brush 2 sheets of filo with melted butter, put some filling in the middle, fold the pastry over it into a parcel and brush the seams with more butter. Repeat with the rest.
4. Fry the parcels in a little oil until golden on both sides and all the edges, or brush them with butter and bake at 350°F (180°C) for 10 to 15 minutes.', 25, 25, 6, '$$', array[]::text[], 'https://cookpad.com/eng/recipes/14701273?ref=search&search_term=saudi+arabia', 'https://www.themealdb.com/images/media/meals/i5o2b61763739053.jpg', 'Photo from TheMealDB'),
  ('53051', 'Nasi lemak', 'Malaysian', '1. Put the coconut milk, water, ginger paste, sliced ginger, a pinch of salt, the bay leaf and the rice in a saucepan, cover and bring to a boil. Lower the heat and simmer for 20 to 30 minutes, until cooked.
2. Put the eggs in cold water, bring to a boil, take off the heat and leave them covered for 10 to 12 minutes. Cool, peel and halve them. Slice the cucumber.
3. Heat about 1 cup of oil in a wok over medium-high heat and fry the peanuts until lightly browned. Drain. Fry half of the anchovies until crisp and drain. Discard the oil.
4. Heat the 2 tbsp of oil and cook the chopped onion, garlic and shallots for 1 to 2 minutes. Add the chili powder mixed with a little water and cook for 10 minutes, stirring now and then.
5. Add the rest of the anchovies for 5 minutes, then the sugar, tamarind and a pinch of salt, and simmer for about 5 minutes, until thick.
6. Serve the sauce over the rice, topped with the peanuts, fried anchovies, cucumber and eggs.', 15, 45, 4, '$$', array['pescatarian']::text[], 'https://www.allrecipes.com/recipe/78938/malaysian-nasi-lemak/', 'https://www.themealdb.com/images/media/meals/wai9bw1619788844.jpg', 'Photo from TheMealDB'),
  ('53497', 'Nom Banh Chok – Cambodian Noodle Soup', 'Cambodian', '1. Heat the oil in a large pot over medium heat and fry the minced garlic for about 1 minute, until golden.
2. Add the chicken pieces and cook for about 5 minutes, until opaque on all sides.
3. Pour in the water and bring to a boil. Lower the heat, stir in the fish sauce, salt and sugar and simmer uncovered for 20 minutes.
4. Meanwhile, cook the noodles as the package says, drain and rinse them under cold water.
5. Divide the noodles between 4 bowls and ladle the broth and chicken over them. Top with bean sprouts, chopped mint and sliced chili, and serve with lime wedges.', 10, 40, 4, '$', array[]::text[], 'https://recipes-for-life.com/cambodian-recipes/', 'https://www.themealdb.com/images/media/meals/6g9gif1782688663.jpg', 'Photo from TheMealDB'),
  ('53117', 'Nordic smørrebrød with asparagus and horseradish cream', 'Norwegian', '1. Mix the crème fraîche, grated horseradish, lemon juice, salt and pepper and chill.
2. Fry the sliced shallots in a little oil over medium heat until golden and crisp. Drain on paper towels and salt lightly.
3. Blanch half of the asparagus (4 white and 4 green) in salted boiling water for 2 to 3 minutes, then cool it in ice water. Slice the rest thinly lengthwise to serve raw.
4. Heat the broiler. Butter the rye bread and toast it until golden and crisp.
5. Top each slice with both kinds of asparagus, drizzle with the horseradish cream, and sprinkle with the grated cheese, the crispy shallots and dill.', 20, 15, 4, '$$', array['vegetarian']::text[], 'https://www.bbc.co.uk/food/recipes/nordic_smorrebrod_69435', 'https://www.themealdb.com/images/media/meals/8a8fu01762772651.jpg', 'Photo from TheMealDB'),
  ('52810', 'Osso Buco alla Milanese', 'Italian', '1. Heat the oven to 300°F (150°C). Season the veal shanks and coat them in the flour, shaking off the extra.
2. Heat the oil and 1 tbsp of the butter in a wide, heavy ovenproof pot over medium-high heat. Brown the shanks for about 5 minutes on each flat side, in batches if needed. Set them aside and pour off the fat.
3. Melt the rest of the butter and cook the chopped onion, carrot, celery and fennel, seasoned, for about 6 minutes, until soft but not brown. Stir in 2 of the garlic cloves, the orange zest, marjoram and bay leaf for 1 to 2 minutes.
4. Add the wine and boil until reduced by half, about 5 minutes. Add the broth and tomatoes and boil until there''s about 1 cup of liquid, about 10 minutes.
5. Stand the shanks in the pot bone side up, pour over their juices, cover with parchment and the lid and braise in the oven for about 2 hours, turning them after 40 minutes, until the meat falls off the bone.
6. For the gremolata, mix the last garlic clove, finely chopped, with the parsley and lemon zest. Sprinkle half over the veal and return it to the oven uncovered for 15 minutes. Skim the sauce, season and serve with the rest of the gremolata.', 25, 165, 4, '$$$', array[]::text[], 'https://www.cookstr.com/Meat/Osso-Buco-alla-Milanese', 'https://www.themealdb.com/images/media/meals/wwuqvt1487345467.jpg', 'Photo from TheMealDB'),
  ('53487', 'Oyster Mushroom Soup', 'Bulgarian', '1. Rinse and dry the mushrooms, remove the stems and cut them into thin strips.
2. Melt the butter in a small pot and cook the mushrooms for about 10 minutes, until they release their liquid.
3. Whisk the flour into the water until there are no lumps and add it to the pot with the salt and milk. Cook for 10 minutes more.
4. Mix the crushed garlic with the vinegar. Serve the soup with 1 to 2 tablespoons of the garlic vinegar and some pepper flakes.', 10, 20, 6, '$', array['vegetarian']::text[], 'https://cookinglsl.com/oyster-mushroom-soup-fake-tripe-soup/#wprm-recipe-container-41251', 'https://www.themealdb.com/images/media/meals/0r7y5n1782681336.jpg', 'Photo from TheMealDB'),
  ('53417', 'Pa Amb Tomaquet (Bread with Tomato)', 'Andorran', '1. Toast the bread slices in a toaster or a 400°F (200°C) oven until crisp and golden.
2. Rub each slice with a cut clove of garlic, then with a cut tomato half.
3. Drizzle with a little olive oil, sprinkle with a pinch of salt and serve warm.', 5, 5, 6, '$', array['vegetarian']::text[], 'https://www.gimmesomeoven.com/tomato-rubbed-bread-pa-amb-tomaquet-pan-con-tomate/#recipe', 'https://www.themealdb.com/images/media/meals/lz9rw91779733434.jpg', 'Photo from TheMealDB'),
  ('52774', 'Pad See Ew', 'Thai', '1. Soak or cook the noodles as the package says. Mix the dark soy sauce, oyster sauce, soy sauce, vinegar, sugar and water in a small bowl.
2. Put the minced garlic and oil in a wok over high heat. When hot, add the sliced chicken and the Chinese broccoli stems and cook until the chicken is lightly golden.
3. Push everything to the side, crack in the egg and scramble it. It''s fine if it sticks and chars a little.
4. Add the noodles, the broccoli leaves and the sauce and toss gently until the noodles are dark and the leaves have wilted. Serve right away.', 15, 10, 2, '$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/uuuspp1468263334.jpg', 'Photo from TheMealDB'),
  ('53191', 'Pad Thai', 'Thai', '1. Put the noodles in a large heatproof bowl, cover with boiling water for 4 minutes, then drain and rinse them under cold water.
2. Mix the juice of 4 of the limes with the cayenne, sugar and fish sauce.
3. Heat the oil and fry the shrimp until cooked. Add the sliced green onions and the noodles and toss.
4. Pour in the lime mixture, then stir in the bean sprouts and half of the chopped peanuts and cilantro. Cook for 1 minute, until hot.
5. Scatter with the rest of the peanuts and cilantro and serve with the last lime in wedges and sweet chili sauce.', 15, 10, 2, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/easy-pad-thai', 'https://www.themealdb.com/images/media/meals/rg9ze01763479093.jpg', 'Photo from TheMealDB'),
  ('53192', 'Panang chicken curry (kaeng panang gai)', 'Thai', '1. For the curry paste, pound the dried and fresh chilies, shrimp paste, garlic, galangal, lemongrass, lime zest, coriander, cumin, nutmeg, peanuts and 1 tsp of salt into a rough paste. You can also pulse it in a food processor with 2 to 3 tbsp of the coconut milk. Keep any extra in the fridge for up to 2 weeks.
2. Heat 2 to 3 tbsp of the thick coconut milk in a saucepan over medium-high heat. When it bubbles, stir in 1 to 2 tbsp of the paste for about 1 minute, until fragrant.
3. Add the sliced chicken and cook for 3 to 4 minutes, until it starts to brown, then the trimmed green beans.
4. Season with the fish sauce and sugar, pour in the rest of the coconut milk, add 1 lime leaf and simmer for 3 to 5 minutes, until the chicken is cooked. Taste and adjust.
5. Stir in the basil, take it off the heat and serve with jasmine rice and the other lime leaf, finely sliced.', 20, 15, 2, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/panang-chicken-curry-kaeng-panang-gai', 'https://www.themealdb.com/images/media/meals/0dhtwr1763371444.jpg', 'Photo from TheMealDB'),
  ('53520', 'Pastel de Choclo', 'Chilean', '1. Put the eggs in a saucepan of water, bring to a boil, take off the heat and leave for 15 minutes. Cool, peel and chop them.
2. Heat a little oil in a skillet over medium heat. Cook the chopped onions and garlic with a pinch of salt, half of the paprika and some pepper for about 2 minutes.
3. Add the beef, the rest of the salt and paprika and more pepper, and cook for about 5 minutes, until mostly browned. Add the cooked, shredded chicken, the raisins, olives and eggs.
4. Blend the drained corn with the basil until smooth. Cook it in a saucepan with the butter over medium heat for 7 to 10 minutes, stirring, until thick. Stir in the milk, 2 tsp of sugar and a pinch of salt and cook for about 15 minutes more, until it''s a thick paste.
5. Heat the oven to 350°F (175°C). Spread the meat in a baking dish, cover it with the corn paste, sprinkle with a little sugar and bake for about 20 minutes, until golden.', 25, 50, 6, '$$', array[]::text[], 'https://www.allrecipes.com/recipe/268354/pastel-de-choclo/', 'https://www.themealdb.com/images/media/meals/47abic1782854326.jpg', 'Photo from TheMealDB'),
  ('53517', 'Pastel de Papas (Chilean Potato Pie)', 'Chilean', '1. Cover the potatoes with salted water, bring to a boil and simmer for about 20 minutes, until tender.
2. Meanwhile, heat the oil in a large skillet over medium heat and cook the chopped onion for about 5 minutes, adding the garlic for the last minute. Stir in the chopped tomatoes and tomato paste and cook for 3 to 5 minutes.
3. Add the beef and cook for about 10 minutes, until browned. Stir in the cheese, parsley and cayenne and season.
4. Heat the oven to 350°F (175°C) and grease a 2-quart baking dish. Drain the potatoes, mash them with the butter and salt, let them cool a little and stir in the beaten eggs.
5. Spread half of the potatoes in the dish, cover with the meat, then the rest of the potatoes.
6. Bake for about 40 minutes, until hot and lightly browned.', 20, 70, 6, '$$', array[]::text[], 'https://www.allrecipes.com/recipe/210774/chilean-potato-pie-pastel-de-papas/', 'https://www.themealdb.com/images/media/meals/h031jy1782853081.jpg', 'Photo from TheMealDB'),
  ('53017', 'Paszteciki (Polish Pasties)', 'Polish', '1. Sift the flour and 1 tsp of the salt into a large bowl. Push 1 hard-boiled egg yolk through a fine sieve into it, add 1 raw egg and mix well. Beat in 5 tbsp of the butter, 1 tbsp at a time.
2. Knead the dough on a floured surface until smooth, wrap it and chill for at least 30 minutes.
3. Melt 2 tbsp of the butter in a heavy skillet over medium heat and cook the chopped onion and rutabaga for about 5 minutes, until soft. Grind or very finely chop them with the cooked beef.
4. Melt the rest of the butter, add the meat mixture and cook over low heat, stirring now and then, until dry and thick. Let it cool, then stir in 1 beaten egg and season with the rest of the salt and the pepper.
5. Heat the oven to 350°F (180°C). Roll the dough into a 13 x 8-inch rectangle. Spoon the filling down the middle, wet the long edges and fold them over the filling, then fold in the ends.
6. Put it seam side down on a baking sheet, brush with the last egg, beaten, and bake for about 30 minutes, until golden. Cut it diagonally into 1 1/2-inch pieces.', 50, 50, 5, '$$', array[]::text[], 'https://www.food.com/recipe/paszteciki-polish-pasties-117909', 'https://www.themealdb.com/images/media/meals/c9a3l31593261890.jpg', 'Photo from TheMealDB'),
  ('53019', 'Pierogi (Polish Dumplings)', 'Polish', '1. Melt half of the butter in a skillet over medium heat and cook half of the chopped onion for about 5 minutes. Add the drained sauerkraut, cook for 5 minutes more, season and let it cool.
2. Melt the rest of the butter, cook the rest of the onion until translucent and stir it into the mashed potatoes. Season.
3. For the dough, beat the eggs with the sour cream. Sift the flour, salt and baking powder together, stir them in and knead on a floured surface until smooth and firm.
4. Roll half of the dough out 1/8 inch thick and cut 3-inch rounds. Put a small spoonful of potato filling in the middle of each, wet the edges, fold over and seal with a fork. Repeat with the rest of the dough and the sauerkraut filling.
5. Cook the pierogi in a large pot of lightly salted boiling water for 3 to 5 minutes, until they float. Lift them out with a slotted spoon.', 50, 25, 6, '$', array['vegetarian']::text[], 'https://www.allrecipes.com/recipe/109914/pierogi-polish-dumplings/', 'https://www.themealdb.com/images/media/meals/45xxr21593348847.jpg', 'Photo from TheMealDB'),
  ('52837', 'Pilchard puttanesca', 'Italian', '1. Cook the pasta as the package says.
2. Meanwhile, heat the oil in a non-stick frying pan and cook the chopped onion, garlic and chili for 3 to 4 minutes, until soft. Stir in the tomato paste for 1 minute.
3. Add the pilchards with their sauce, breaking up the fish with a spoon, then add the olives and cook for a few minutes more.
4. Drain the pasta and add it to the pan with 2 to 3 tbsp of the cooking water. Toss well and serve scattered with parmesan.', 10, 15, 4, '$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/pilchard-puttanesca', 'https://www.themealdb.com/images/media/meals/vvtvtr1511180578.jpg', 'Photo from TheMealDB'),
  ('53039', 'Piri-piri chicken and slaw', 'Portuguese', '1. Blend the chilies, garlic, ginger, oregano, coriander, paprika, 2 tbsp of the vinegar and the oil into a marinade. Rub it over the chicken and leave it for 1 hour at room temperature.
2. Heat the oven to 375°F (190°C). Roast the chicken in a roasting pan for 1 hour 20 minutes, then let it rest under loose foil for 20 minutes.
3. Meanwhile, for the slaw, mix the thinly sliced red onion, the grated carrots and beet and the shredded cabbage with the mayonnaise, yogurt, cumin seeds and the rest of the vinegar. Season.
4. Serve the chicken with the slaw.', 75, 100, 4, '$$', array[]::text[], 'https://www.olivemagazine.com/recipes/family/piri-piri-chicken-and-winter-slaw/', 'https://www.themealdb.com/images/media/meals/hglsbl1614346998.jpg', 'Photo from TheMealDB'),
  ('53160', 'Pisto con huevos', 'Spanish', '1. Heat the oil in a large flameproof casserole or cast-iron skillet over low heat. Add the chopped onions with a pinch of salt, cover and cook gently for 15 minutes, stirring now and then. Add the garlic for 2 minutes.
2. Add the sliced peppers and cook, covered, over medium heat for about 5 minutes, until just tender.
3. Stir in the oregano, thyme, bay leaves and some salt and pepper. Add the diced zucchini and eggplant, cover and cook for 10 minutes.
4. Stir in the chopped tomatoes, cover and cook for 20 minutes, stirring now and then.
5. Make 4 hollows and carefully crack an egg into each. Cook over medium heat for 5 to 6 minutes, until the eggs are set but still a little soft. Scatter with parsley and serve.', 20, 60, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/pisto-con-huevos', 'https://www.themealdb.com/images/media/meals/0nswfe1763279040.jpg', 'Photo from TheMealDB'),
  ('53540', 'Pollo en Salsa', 'Costa Rican', '1. Chop the pepper, onion and tomato.
2. Heat a little olive oil in a large pot and cook the onion, garlic, tomato and pepper with the achiote paste, cumin, oregano, salt and pepper for about 4 minutes.
3. Add the chicken and cook for about 2 minutes on each side.
4. Pour in the broth, cover and simmer over low heat for about 35 minutes, until the chicken is very tender. (In a pressure cooker, cook on high for 20 minutes.) Add salt if needed and serve with rice and beans.', 10, 45, 4, '$', array[]::text[], 'https://www.recipesfromcostarica.com/recipes', 'https://www.themealdb.com/images/media/meals/4o13oe1784396585.jpg', 'Photo from TheMealDB'),
  ('53297', 'Pomegranate salad', 'Polish', '1. Mix the olive oil, lemon juice, honey and thyme leaves in a large bowl and season well.
2. Add the lettuce, halved tomatoes, sliced green onions and chopped chili and toss.
3. Take the seeds out of the pomegranate over a bowl and remove any white pith.
4. Arrange the salad on a platter and scatter with the pomegranate seeds and crumbled feta.', 20, 0, 2, '$$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/pomegranate-salad', 'https://www.themealdb.com/images/media/meals/fqpqml1764359125.jpg', 'Photo from TheMealDB'),
  ('52847', 'Pork Cassoulet', 'French', '1. Heat the oven to 275°F (140°C). Heat the goose fat in a large ovenproof pan with a tight lid over high heat and brown the diced pork for a few minutes.
2. Lower the heat and add the sliced onion, whole garlic cloves, sliced carrot and fennel seeds. Cook gently for a few minutes to soften.
3. Pour in the vinegar, scraping the bottom of the pan. Add the broth, tomato paste and half of the rosemary and parsley. Bring to a boil and simmer for 10 minutes, then season.
4. Cover and cook in the oven for 2 hours, taking the lid off for the last hour. Stir now and then, and add the drained beans for the last 30 minutes.
5. Heat the broiler. Scatter the rest of the herbs and the breadcrumbs over the top, drizzle with a little oil and broil for 5 to 10 minutes, until golden. Serve with crusty bread and broccoli.', 15, 150, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/jacks-pork-cassoulet', 'https://www.themealdb.com/images/media/meals/wxuvuv1511299147.jpg', 'Photo from TheMealDB'),
  ('53044', 'Portuguese barbecued pork (Febras assadas)', 'Portuguese', '1. Cut each pork tenderloin into 5 pieces. Put each piece in a plastic bag and pound it with a rolling pin into a thin cutlet.
2. Mix the wine, paprika, salt, pepper and the juice of half a lemon, add the pork and marinate for 20 to 30 minutes.
3. Cut the potatoes into 1-inch fries, soak them in cold water for 5 minutes, change the water and soak for 5 minutes more. Drain and pat dry.
4. Heat the oil in a deep pan to 265°F (130°C) and fry the potatoes in batches for 8 to 10 minutes. Drain. Heat the oil to 350°F (180°C) and fry them again for about 3 minutes, until crisp and golden. Drain and salt.
5. Rub the pork with olive oil and cook it on a very hot grill pan or barbecue for 1 minute on each side, in 2 batches.
6. Pile the fries on plates, top with the pork and its juices, and serve with mayonnaise and lemon wedges.', 40, 30, 4, '$$', array[]::text[], 'https://www.olivemagazine.com/recipes/meat-and-poultry/febras-assadas-portuguese-barbecued-pork-served-with-lemon-and-mayo-on-chips/', 'https://www.themealdb.com/images/media/meals/cybyue1614349443.jpg', 'Photo from TheMealDB'),
  ('53042', 'Portuguese prego with green piri-piri', 'Portuguese', '1. Rub the steaks with the cut garlic, put them in a bag with the olive oil, 1 tbsp of the vinegar and the parsley stalks, and pound them a few times with a rolling pin. Leave for 1 to 2 hours.
2. For the green sauce, blend the basil, jalapeño, green onions, sugar, the rest of the vinegar and 1 tbsp of water until smooth.
3. Heat a grill pan or frying pan until very hot. Brush off the garlic and parsley, season the steaks and sear them for 2 minutes on each side. Let them rest on a plate.
4. Toast the cut ciabatta halves and press them into the steak juices on the plate.
5. Slice the steaks and put them in the rolls with the green sauce and arugula.', 75, 10, 2, '$$$', array[]::text[], 'https://www.olivemagazine.com/recipes/meat-and-poultry/portuguese-prego-with-green-piri-piri/', 'https://www.themealdb.com/images/media/meals/ewcikl1614348364.jpg', 'Photo from TheMealDB'),
  ('52780', 'Potato Gratin with Chicken', 'Italian', '1. Thinly slice the potatoes and boil them for 5 to 8 minutes, until firm but not soft.
2. Meanwhile, put the sliced onions in a baking dish with the olive oil and broth and cook in a 400°F (200°C) oven or on the stove until soft.
3. Drain the potatoes and spread them over the onions. Season and spoon over the crème fraîche to cover. Grate parmesan over the top and broil until golden.
4. Meanwhile, season the chicken and cook it in a frying pan for 5 to 7 minutes on each side, with the bacon, until cooked through.
5. Serve the gratin with the chicken and bacon, and with peas and spinach if you like.', 15, 35, 4, '$$', array[]::text[], 'https://www.instagram.com/p/BHxR7hYBJ6P', 'https://www.themealdb.com/images/media/meals/qwrtut1468418027.jpg', 'Photo from TheMealDB'),
  ('53280', 'Poulet Roti a l''Algerienne (Algerian Roast Chicken)', 'Algerian', '1. Heat the oven to 350°F (175°C).
2. Mix the water, chopped onion, olive oil, vinegar, mustard, crushed garlic, black pepper, cayenne and salt in a roasting dish.
3. Add the chicken and turn it until well coated.
4. Roast for about 1 1/2 hours, basting now and then, until it reaches 165°F in the thickest part of the thigh.', 10, 90, 4, '$$', array[]::text[], 'https://www.allrecipes.com/recipe/258886/poulet-roti-a-lalgerienne-algerian-roast-chicken/', 'https://www.themealdb.com/images/media/meals/nlxald1764112200.jpg', 'Photo from TheMealDB'),
  ('52804', 'Poutine', 'Canadian', '1. Cut the potatoes into fries and pat them dry. Heat oil for deep-frying to 365°F (185°C).
2. Warm the gravy in a saucepan.
3. Fry the potatoes in batches for about 5 minutes, until golden, and drain on paper towels.
4. Pile the fries on a platter, scatter the cheese curds over them, ladle the hot gravy over the top and serve right away.', 10, 20, 4, '$', array[]::text[], 'http://www.food.com/recipe/real-canadian-poutine-113388', 'https://www.themealdb.com/images/media/meals/uuyrrx1487327597.jpg', 'Photo from TheMealDB'),
  ('52921', 'Provençal Omelette Cake', 'French', '1. Whisk 5 eggs in each of two bowls and season. Fry the sliced zucchini and green onions gently in the oil for about 10 minutes, until soft. Let them cool and stir them into one bowl.
2. Add the roasted, sliced peppers, the crushed garlic and the chopped chili to the other bowl and season.
3. Heat a little oil in an 8 to 9-inch non-stick frying pan. Pour in a third of the zucchini mixture and cook until set and lightly browned underneath, then flip it with a plate and cook the other side. Make 2 more, then 3 with the pepper mixture.
4. Beat the cream cheese with the milk until spreadable and stir in the chives, basil, salt and pepper.
5. Line a deep round cake pan the same size as the frying pan with plastic wrap. Layer the omelettes, alternating colors, with a thin layer of cheese between each. Cover and chill for a few hours or up to 24 hours.
6. Turn it out onto a plate, top with arugula, shaved parmesan, a drizzle of olive oil and black pepper, and cut into wedges.', 40, 40, 8, '$$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/6428/provenal-omelette-cake', 'https://www.themealdb.com/images/media/meals/qwtrtp1511799242.jpg', 'Photo from TheMealDB'),
  ('53383', 'Ramen Noodles with Boiled Egg', 'Chinese', '1. Lower the egg into boiling water and cook for 6 1/2 to 7 minutes. Put it in ice water for 3 to 5 minutes, then peel it.
2. Bring the 2 cups of water to a boil and cook the noodles as the package says.
3. Stir in the soy sauce, chilli sauce, salt and pepper.
4. Pour into a bowl, top with the egg cut in half and the sliced green onions, and serve.', 5, 15, 1, '$', array['vegetarian']::text[], null, 'https://www.themealdb.com/images/media/meals/ip5xtp1769779958.jpg', 'Photo from TheMealDB'),
  ('52933', 'Rappie Pie', 'Canadian', '1. Heat the oven to 400°F (200°C) and grease a 10 x 14-inch baking pan.
2. Melt the butter in a skillet over medium heat and cook the chopped onions for about 5 minutes, then over low heat for about 40 minutes more, stirring, until very soft and dark brown.
3. Bring the broth to a boil in a large pot, add the chicken, lower the heat and simmer for about 20 minutes, until cooked through. Lift out the chicken and keep the broth.
4. Peel and finely grate the potatoes, then squeeze out as much liquid as you can in a clean towel. Mix in the salt and pepper and enough hot broth to make a mixture like oatmeal.
5. Spread half of the potatoes in the pan, lay the sliced chicken over them, scatter with the onions and cover with the rest of the potatoes.
6. Bake for about 1 hour, until golden brown. Serve with a little of the reheated broth poured over each portion.', 40, 120, 10, '$', array[]::text[], 'http://allrecipes.com/recipe/234025/rappie-pie/', 'https://www.themealdb.com/images/media/meals/ruwpww1511817242.jpg', 'Photo from TheMealDB'),
  ('53124', 'Raspeballer (Norwegian Potato Dumplings)', 'Norwegian', '1. Simmer the pork knuckle in water for about 3 hours, until the meat falls off the bone. Lift out the pork and keep the broth.
2. Meanwhile, boil half of the potatoes, peel them when cool and mash them well with no lumps. Peel and finely grate the rest and pat them dry with paper towels.
3. Mix the grated and mashed potatoes, then mix in the flour and salt with your hands.
4. Bring the pork broth to a very gentle simmer with the stock cubes (it mustn''t boil hard). With a tablespoon dipped in cold water, shape smooth balls and drop them into the broth.
5. Simmer them for about 30 minutes, heating the sausage in the same pot. Meanwhile, boil the chopped rutabaga and carrots for about 30 minutes, until tender, then drain and mash them with the cream, butter and nutmeg.
6. Serve the dumplings with the meat, the mash and chopped parsley.', 45, 210, 6, '$$', array[]::text[], 'https://scandinaviancookbook.com/raspeballer-norwegian-potato-dumplings/', 'https://www.themealdb.com/images/media/meals/hhm7xy1763075871.jpg', 'Photo from TheMealDB'),
  ('52809', 'Recheado Masala Fish', 'Indian', '1. Soak the dried chilies, ginger, garlic, pepper, cumin, cinnamon, cloves, cardamom and tamarind in the vinegar with the sugar, turmeric and a pinch of salt for 35 to 40 minutes.
2. Grind it all into a thick, smooth paste, adding a little more vinegar only if needed. It must stay thick to stick to the fish.
3. Rinse the mackerel, slit them open down the middle and cut a few slashes on top. Fill the slit and slashes with the paste and coat the fish all over. Marinate for 30 minutes.
4. Heat oil in a shallow pan and fry the fish until golden brown on both sides. Serve hot with salad, lime wedges and rice.', 90, 15, 4, '$$', array['pescatarian']::text[], 'http://www.flavorsofmumbai.com/fish-recheado-masala-recipe/', 'https://www.themealdb.com/images/media/meals/uwxusv1487344500.jpg', 'Photo from TheMealDB'),
  ('52811', 'Ribollita', 'Italian', '1. Heat 2 tbsp of the oil in a large ovenproof pot over medium heat. Add the chopped onion, carrot, celery and garlic, season and cook for 5 to 10 minutes, stirring now and then, until soft.
2. Heat the oven to 500°F (260°C). Add the drained beans, the tomatoes with their juice, the water, rosemary and thyme. Bring to a boil, then cover and simmer for 15 to 20 minutes, breaking up the tomatoes.
3. Remove the herb stems and stir in the chopped kale. Taste and season.
4. Lay the bread over the top of the soup, scatter with the sliced red onion, drizzle with the rest of the oil and sprinkle with the parmesan.
5. Bake for 10 to 15 minutes, until the bread, onions and cheese are browned and crisp. Serve in bowls.', 15, 40, 4, '$', array['vegetarian']::text[], 'https://cooking.nytimes.com/recipes/1016052-ribollita', 'https://www.themealdb.com/images/media/meals/xrrwpx1487347049.jpg', 'Photo from TheMealDB'),
  ('53506', 'Rice and Beans', 'Caribbean', '1. Soak the dried kidney beans overnight, drain them, cover with fresh water and simmer for about 1 hour, until tender.
2. Add the rice, coconut milk, chopped onion, pepper and salt, with enough water to just cover everything.
3. Lay the whole Scotch bonnets on top, taking care not to burst them, and simmer covered for about 20 minutes, until the rice is tender.
4. Remove the peppers before serving.', 10, 90, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes', 'https://www.themealdb.com/images/media/meals/j8c1d51782772399.jpg', 'Photo from TheMealDB'),
  ('52783', 'Rigatoni with fennel sausage sauce', 'Italian', '1. Heat 1 tbsp of the oil in a large pan with a lid and fry the sausages, cut into pieces, over medium-high heat for about 10 minutes, until browned. Set them aside.
2. Fry the chopped onion and fennel in the pan for 15 minutes, until soft and caramelized. Add the paprika, garlic and half of the fennel seeds for 2 minutes, then pour in the wine and boil for 30 seconds.
3. Add the tomatoes, sugar, 1/2 cup (100 ml) of water, the sausages and 1/2 tsp of salt. Cover and simmer for 30 minutes, taking the lid off after 10 minutes, until thick. Stir in the olives and the rest of the fennel seeds.
4. Cook the rigatoni in salted boiling water for 12 to 14 minutes, until al dente. Drain and stir in 1 tbsp of oil.
5. For the pesto, blend the pecorino, anchovy, the rest of the oil and 1 tbsp of water into a rough paste, then add the basil and pulse briefly.
6. Serve the pasta with the sauce and a spoonful of pesto on top.', 15, 60, 6, '$$', array[]::text[], 'http://www.ottolenghi.co.uk/recipes/meat/rigatoni-with-fennel-sausage-sauce-and-pecorino-and-anchovy-pesto-shop', 'https://www.themealdb.com/images/media/meals/qtqvys1468573168.jpg', 'Photo from TheMealDB'),
  ('53273', 'Roast aubergine with goat''s cheese & toasted flatbread', 'Turkish', '1. Heat the oven to 400°F (200°C). Slice the eggplants, brush them with 1 tbsp of the oil, season and roast on a baking sheet for 20 minutes, until browned, adding the tomatoes for the last 5 minutes.
2. Tear the pita into pieces and toast it on another sheet for about 8 minutes, until crisp.
3. For the dressing, mix the vinegar, chopped mint, 1 chopped shallot, the chopped chili, the rest of the oil and some salt and pepper.
4. Put the eggplant, tomatoes, the other shallot, sliced, and the toasted pita in a bowl. Pour over the dressing, crumble the goat cheese on top and add the arugula.', 15, 20, 2, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/roast-aubergine-goats-cheese-toasted-flatbread', 'https://www.themealdb.com/images/media/meals/iydbwy1763816111.jpg', 'Photo from TheMealDB'),
  ('52942', 'Roast fennel and aubergine paella', 'Spanish', '1. Heat the oven to 400°F (200°C). Toss the chopped fennel, eggplant, pepper and zucchini with a little olive oil, salt and pepper and roast for about 20 minutes, turning a couple of times, until golden and almost cooked.
2. Meanwhile, heat a little olive oil in a paella pan or large frying pan over low-medium heat and cook the chopped onion for 8 to 10 minutes, until soft.
3. Turn up the heat to medium, stir in the rice, paprika and saffron for 1 minute, then add the wine and reduce by half. Stir in two thirds of the broth and simmer uncovered for 10 minutes, stirring a couple of times.
4. Stir in the peas, season and gently mix in the roasted vegetables. Pour in the rest of the broth, lay lemon wedges on top, cover and cook for 10 minutes more.
5. Turn up the heat until you hear a slight crackle, to toast the bottom. Take it off the heat, let it sit for 5 minutes and sprinkle with parsley.', 15, 45, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.homestylemag.co.uk/recipe/517/main-courses/roast-fennel-and-aubergine-paella', 'https://www.themealdb.com/images/media/meals/1520081754.jpg', 'Photo from TheMealDB'),
  ('52816', 'Roasted Eggplant With Tahini, Pine Nuts, and Lentils', 'American', '1. Heat the oven to 450°F (230°C). Heat 2 tbsp of olive oil in a saucepan over medium heat and cook the chopped carrots, celery and onion for about 4 minutes, until soft. Add the garlic for 30 seconds.
2. Add the lentils, bay leaves, water and a pinch of salt. Bring to a simmer, partly cover and cook for about 30 minutes, until tender, adding water if needed. Uncover, stir in the vinegar, let it reduce a little and season.
3. Meanwhile, cut the eggplants in half, score the flesh in a crisscross pattern and put them cut side up on a lined baking sheet. Brush each half with about 1 tbsp of oil, season and put a rosemary sprig on top. Roast for 25 to 35 minutes, until very tender and charred.
4. Toast the pine nuts in a little oil in a skillet for about 4 minutes, until golden. Thin the tahini with a little water, lemon or vinegar and salt to make a sauce.
5. Stir half of the parsley into the lentils, put them on a platter and lay the eggplant on top. Spoon the tahini sauce over, and sprinkle with the pine nuts and the rest of the parsley.', 15, 45, 4, '$$', array['vegan', 'vegetarian']::text[], 'http://www.seriouseats.com/recipes/2016/03/roasted-eggplant-tahini-pine-nut-lentil-vegan-experience-recipe.html', 'https://www.themealdb.com/images/media/meals/ysqrus1487425681.jpg', 'Photo from TheMealDB'),
  ('53315', 'Rosemary braised red cabbage with kabanos', 'Ukrainian', '1. Halve the cabbage, cut out the tough core and slice it thinly.
2. Put it in a large pan with everything else except the sausages: the oil, butter, sliced onion, vinegar, sugar, chopped chili, rosemary and diced apple. Add 1 1/4 cups (300 ml) of water and some salt and pepper.
3. Bring to a simmer, cover and cook gently for 1 1/2 hours, stirring often and adding a little water if it gets dry.
4. Add the sausages, cover and simmer for 20 minutes, then uncover and cook for 10 minutes more. Serve with mashed or boiled potatoes.', 10, 120, 4, '$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/rosemary-braised-red-cabbage-kabanos', 'https://www.themealdb.com/images/media/meals/s1jxzl1764369317.jpg', 'Photo from TheMealDB'),
  ('53020', 'Rosol (Polish Chicken Soup)', 'Polish', '1. Put the chicken in a large pot, cover with water and bring to a boil.
2. Simmer for 2 to 2 1/2 hours, skimming off any foam so the broth stays clear.
3. For the last hour, add the onions, carrots, leek, celery and cabbage, the cloves, allspice, bay leaves, parsley, dill, pepper and salt.
4. Strain the broth. Pull the chicken off the bones in large chunks and slice the carrots.
5. Return the chicken and carrots to the broth and serve hot.', 15, 150, 6, '$', array[]::text[], 'https://polishhousewife.com/rosol-polish-chicken-soup/', 'https://www.themealdb.com/images/media/meals/lx1kkj1593349302.jpg', 'Photo from TheMealDB'),
  ('53052', 'Roti john', 'Malaysian', '1. Mix the beef, chopped onion, eggs, chopped chili, salt and pepper in a bowl.
2. Heat a little oil in a pan or on a griddle and pour in the mixture.
3. Press the baguette, split open, cut side down on top and cook for about 2 minutes, until the egg sets.
4. Turn it over to crisp the bread a little. Add mayonnaise, cut it into pieces and serve.', 5, 15, 1, '$', array[]::text[], 'https://www.196flavors.com/malaysia-roti-john/', 'https://www.themealdb.com/images/media/meals/hx335q1619789561.jpg', 'Photo from TheMealDB'),
  ('52962', 'Salmon Eggs Eggs Benedict', 'American', '1. For the hollandaise, whisk the lemon juice, 1 tsp of the vinegar and 3 of the egg yolks in a bowl until light and frothy. Set the bowl over a pan of simmering water and whisk until it thickens.
2. Gradually whisk in all but 1 tbsp of the butter, melted, until thick. If it looks like it''s splitting, whisk it off the heat for a few minutes. Season and keep warm.
3. Bring a large pan of water to a boil, add the rest of the vinegar and lower the heat to a gentle simmer. Stir to make a slight whirlpool and slide in the other 4 eggs one at a time. Poach each for about 4 minutes and lift out with a slotted spoon.
4. Split, toast and butter the muffins. Put a couple of slices of salmon on each half, top with an egg and spoon over the hollandaise.', 15, 20, 4, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/73606/eggs-benedict-with-smoked-salmon-and-chives', 'https://www.themealdb.com/images/media/meals/1550440197.jpg', 'Photo from TheMealDB'),
  ('53234', 'Salmon noodle soup', 'Vietnamese', '1. Bring the broth to a boil in a large pan and stir in the curry paste.
2. Add the noodles and cook for 8 minutes, then the sliced mushrooms and the corn for 2 minutes more.
3. Add the salmon, cut into chunks, and cook for about 3 minutes, until cooked through.
4. Take it off the heat and stir in the lime juice, soy sauce and a pinch of sugar. Ladle into 4 bowls and sprinkle with cilantro.', 10, 20, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/salmon-noodle-soup', 'https://www.themealdb.com/images/media/meals/ikizdm1763760862.jpg', 'Photo from TheMealDB'),
  ('52823', 'Salmon Prawn Risotto', 'Italian', '1. Melt the butter in a heavy pan and cook the chopped onion gently until soft, without browning.
2. Add the rice and stir to coat every grain. Pour in the wine and stir gently until absorbed.
3. Add the hot broth a ladle at a time, stirring until each addition is absorbed, for about 20 minutes, until the rice is tender.
4. Meanwhile, broil the salmon and cook the shrimp and the asparagus until just done.
5. Stir the lemon juice and zest and some pepper into the risotto (the salmon is usually salty enough). Serve topped with the salmon, shrimp and asparagus and scattered with parmesan.', 10, 35, 4, '$$$', array['pescatarian']::text[], 'http://www.rangemaster.co.uk/rangemaster-owners/recipes-ideas-inspiration/recipes/mains/prawn-and-hot-smoked-salmon-risotto-with-asparagus', 'https://www.themealdb.com/images/media/meals/xxrxux1503070723.jpg', 'Photo from TheMealDB'),
  ('52936', 'Saltfish and Ackee', 'Jamaican', '1. A day ahead, soak the salt cod overnight, changing the water a couple of times.
2. Drain it, cover with fresh water and bring to a boil. Drain again, add fresh water, bring to a boil and simmer for about 5 minutes. Drain and flake the fish, removing any skin or bones.
3. For the dumplings, mix the flour and suet with a pinch of salt and about 1 cup (250 ml) of water into a dough. Wrap and chill it.
4. Drain and rinse the ackee. Heat 1 tbsp of oil and fry the chopped onion until soft but not brown. Add the paprika, curry powder, allspice, hot sauce, salt, pepper and the sliced peppers and cook until the peppers are tender.
5. Add the chopped tomatoes and the cod, then gently stir in the ackee and simmer until you''re ready to serve.
6. Heat about 1/2 inch of oil in a frying pan. Shape the dough into plum-size balls and fry them until golden brown. Drain and serve with the saltfish and ackee.', 30, 40, 4, '$$', array[]::text[], 'https://www.bbc.co.uk/food/recipes/saltfish__ackee_with_64803', 'https://www.themealdb.com/images/media/meals/vytypy1511883765.jpg', 'Photo from TheMealDB'),
  ('53443', 'Satee', 'Caribbean', '1. Blend the chopped onion, garlic, lemon juice, sugar, 3/4 cup of the soy sauce, the salt, coriander and 1 cup of the oil into a marinade.
2. Pour it over the cubed beef and marinate for a few hours (not overnight).
3. Thread the beef onto about 36 skewers.
4. Mix the rest of the oil and soy sauce in a shallow dish and roll each skewer in it.
5. Fry the skewers in a large pan, or cook them on a barbecue, turning them, until browned and cooked the way you like.', 30, 20, 8, '$$', array[]::text[], 'https://www.visitaruba.com/aruba-recipes/satee/', 'https://www.themealdb.com/images/media/meals/dqxtlh1780153831.jpg', 'Photo from TheMealDB'),
  ('53577', 'Sauerkraut and Fish Salad', 'Estonian', '1. Hard-boil the egg, then peel and slice it. Toast the bread and cut it into pieces.
2. Whisk the oil with the honey and a pinch of salt into a dressing.
3. Mix the sauerkraut, egg, flaked fish and bread with the dressing and serve.', 15, 10, 2, '$', array['pescatarian']::text[], 'https://estoniancuisine.com/2021/01/09/sauerkraut-and-fish-salad-hapukapsa-kalasalat/', 'https://www.themealdb.com/images/media/meals/2i0plx1784837241.jpg', 'Photo from TheMealDB'),
  ('53296', 'Sauerkraut pierogi', 'Polish', '1. For the crispy shallots, slice 2 of the shallots, toss them in a little flour and deep-fry them in hot oil (350°F/180°C) for about 1 minute, until golden. Drain on paper towels.
2. For the filling, heat 1/2 tbsp of the oil in a frying pan and gently fry the other 2 shallots, chopped, for 10 minutes. Add the sauerkraut and shredded cabbage and cook for 5 to 10 minutes, until soft. Season and let it cool completely.
3. For the dough, mix the egg and the rest of the oil with 1/2 cup (125 ml) of water, then gradually work in the flour. Knead on a floured surface until it stops sticking, wrap and chill for at least 30 minutes.
4. Roll the dough out thinly on a well-floured surface and cut about 25 circles, 3 1/2 inches (9 cm) wide. Put 1 tsp of filling in the middle of each, fold into half-moons and pinch to seal.
5. Boil them in a large pan of salted water for about 2 minutes, until they float. Drain and serve with butter, sour cream and the crispy shallots.', 75, 30, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/pierogi', 'https://www.themealdb.com/images/media/meals/ckbx1h1764123606.jpg', 'Photo from TheMealDB'),
  ('52836', 'Seafood fideuà', 'Spanish', '1. Scrub the mussels, throwing away any with broken shells or that stay open when tapped, and pull off the beards. Peel the body of each shrimp, leaving the head and tail, and remove the vein.
2. Soak the saffron in 3 1/2 tbsp of hot water for 10 minutes. Crush the vermicelli into short pieces.
3. Heat the oil in a large, deep frying pan or paella pan and cook the chopped onion for 5 minutes. Add the garlic for 1 minute, then the pasta, and cook for about 5 minutes, stirring, until toasted brown. Stir in the paprika.
4. Stir in the monkfish and squid, cut into pieces, and the saffron with its water, and season. Spread it out evenly, pour in the hot stock, scatter with the chopped tomatoes, bring to a simmer, cover tightly and cook over medium heat for 6 minutes.
5. Stir, then push the mussels into the pasta, hinge side down, and lay the shrimp on top. Cover and cook for 6 minutes more, until the mussels open, the shrimp are pink and the pasta is cooked. Simmer uncovered for 2 to 3 minutes to cook off most of the liquid.
6. Let it sit for 2 to 3 minutes, squeeze over the lemon and scatter with parsley.', 35, 25, 6, '$$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/seafood-fideua-paella', 'https://www.themealdb.com/images/media/meals/wqqvyq1511179730.jpg', 'Photo from TheMealDB'),
  ('53378', 'Sesame Cucumber Salad', 'Chinese', '1. Peel the cucumbers and cut them lengthwise into quarters. Scrape out the seeds if they''re bitter, then cut them into 1/2-inch pieces.
2. Put them in a serving bowl, sprinkle with the salt and toss with the sesame oil, rice vinegar, torn basil and pepper flakes.
3. Sprinkle with toasted sesame seeds and serve.', 10, 0, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.simplyrecipes.com/recipes/sesame_cucumber_salad/', 'https://www.themealdb.com/images/media/meals/93iok31766436070.jpg', 'Photo from TheMealDB'),
  ('52963', 'Shakshuka', 'Egyptian', '1. Heat the oil in a frying pan with a lid and soften the sliced onions, chili, garlic and chopped cilantro stalks for 5 minutes.
2. Stir in the tomatoes and sugar and let them bubble for 8 to 10 minutes, until thick.
3. Make 4 hollows in the sauce with a spoon and crack an egg into each one.
4. Cover and cook over low heat for 6 to 8 minutes, until the eggs are done the way you like. Scatter with the cilantro leaves and crumbled feta and serve with crusty bread.', 5, 20, 2, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/7573/spicy-tomato-baked-eggs', 'https://www.themealdb.com/images/media/meals/g373701551450225.jpg', 'Photo from TheMealDB'),
  ('53217', 'Shawarma chuck roast wrap', 'Saudi Arabian', '1. Heat the oven to 300°F (150°C). Stir all the spices, the salt, broth and lemon juice together in a heavy ovenproof pot.
2. Add the beef, turn it to coat and spoon some sauce over the top.
3. Cover and cook in the oven for about 3 1/2 hours, until very tender. (In a slow cooker, cook on low for 8 to 10 hours.)
4. Shred the beef with two forks, discarding any fat. Skim the fat off the sauce and mix the beef back in.
5. Fill the pitas with the beef and any toppings you like, fold them like a burrito and toast them in a hot grill pan.', 15, 210, 6, '$$', array[]::text[], 'https://cookpad.com/eng/recipes/24415920?ref=search&search_term=saudi+arabia', 'https://www.themealdb.com/images/media/meals/swo87v1763595282.jpg', 'Photo from TheMealDB'),
  ('52953', 'Shrimp Chow Fun', 'Chinese', '1. Soak the rice noodles until soft (or overnight for dried ones), then boil them as the package says and rinse them under cold water.
2. Mix the shrimp with the egg, a pinch of pepper, 1 tsp of the sesame oil, 1 tbsp of the cornstarch and 1 tbsp of the vegetable oil.
3. Heat 2 tbsp of the oil in a wok and stir-fry the shrimp until golden. Set them aside.
4. Add the last 1 tbsp of oil, the minced garlic and ginger, the sliced onion, bean sprouts and green onions, then the noodles.
5. Add the wine, oyster sauce, sugar, vinegar, the rest of the sesame oil, a pinch of pepper and the soy sauce, then return the shrimp.
6. Mix the rest of the cornstarch with 2 tbsp of water and stir in a little at a time until the sauce is as thick as you like.', 20, 15, 2, '$$', array['pescatarian']::text[], 'https://sueandgambo.com/pages/shrimp-chow-fun', 'https://www.themealdb.com/images/media/meals/1529445434.jpg', 'Photo from TheMealDB'),
  ('53371', 'Sichuan Style Stir-Fried Chinese Long Beans', 'Chinese', '1. Trim the long beans and cut them into 3-inch pieces. Pat them dry.
2. Heat the peanut oil in a wok or large, deep pan over high heat. Stir-fry the beans for 5 to 7 minutes, until blistered and tender.
3. Push them to the side, add the dried chilies and Sichuan pepper and stir-fry for 30 seconds, until fragrant.
4. Toss everything with the salt, sugar, sesame oil and a splash of soy sauce and serve right away.', 10, 10, 2, '$', array['vegan', 'vegetarian']::text[], 'https://www.simplyrecipes.com/recipes/sichuan_style_stir_fried_chinese_long_beans/', 'https://www.themealdb.com/images/media/meals/i0610h1765659464.jpg', 'Photo from TheMealDB'),
  ('53369', 'Silken Tofu with Sesame Soy Sauce', 'Chinese', '1. Drain the tofu and gently slide it out of the package onto a large plate.
2. Slice it into 1/2-inch slabs and gently push them so they fan out across the plate.
3. Drizzle with the soy sauce and the sesame paste, and garnish with the sliced green onion and sesame seeds.', 10, 0, 2, '$', array['vegan', 'vegetarian']::text[], 'https://www.simplyrecipes.com/silken-tofu-with-sesame-soy-sauce-recipe-6979877', 'https://www.themealdb.com/images/media/meals/j9nray1765657692.jpg', 'Photo from TheMealDB'),
  ('53484', 'Simple heart of palm & tomato salad', 'Brazilian', '1. Mix the sliced hearts of palm, halved tomatoes and sliced green onions.
2. Whisk the vinegar and olive oil together and drizzle it over the salad.
3. Sprinkle with chopped parsley, toss and serve.', 10, 0, 6, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/simple-heart-palm-tomato-salad', 'https://www.themealdb.com/images/media/meals/7whfgi1782678933.jpg', 'Photo from TheMealDB'),
  ('52994', 'Skillet Apple Pork Chops with Roasted Sweet Potatoes & Zucchini', 'American', '1. Heat the oven to 450°F (230°C). Dice the sweet potatoes into 1/2-inch pieces, toss them on a baking sheet with a little oil, salt and pepper and roast on the top rack for 12 minutes.
2. Meanwhile, core and thinly slice the apple, chop the garlic and quarter the lemon. Cut the zucchini into 1/2-inch half-moons and toss them on a second sheet with oil, salt and pepper.
3. Season the pork chops and cook them in a little oil in a large pan over medium-high heat for 4 to 5 minutes on each side, until cooked through. Set them aside.
4. Put the zucchini on the middle rack and roast both sheets for 12 to 15 minutes more, until browned.
5. Melt 1 tbsp of the butter in the pork pan, add the apple, season and cook for 2 to 3 minutes, scraping up the browned bits. Add the garlic for 30 seconds, then the broth and sugar, and cook for 3 to 5 minutes, until thick and the apple is tender.
6. Take it off the heat and stir in the rest of the butter and a squeeze of lemon. Serve the pork with the apple sauce on top and the vegetables, with lemon squeezed over the zucchini.', 15, 30, 2, '$$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/h3ijwo1581013377.jpg', 'Photo from TheMealDB'),
  ('53023', 'Sledz w Oleju (Polish Herrings)', 'Polish', '1. Soak the salted herring in cold water for at least 1 hour, changing the water if they''re very salty.
2. Drain them well and cut them into bite-size pieces.
3. Put them in a jar and cover with the oil, allspice, peppercorns and bay leaf. Close the jar.
4. Chill for 2 to 3 days before eating (it keeps for up to 2 weeks). Serve with finely chopped onion.', 75, 0, 4, '$', array['pescatarian']::text[], 'https://www.thespruceeats.com/polish-herrings-in-oil-recipe-1135618', 'https://www.themealdb.com/images/media/meals/7ttta31593350374.jpg', 'Photo from TheMealDB'),
  ('53432', 'Slow-cooked, Wadadli-spiced Cubano pork belly', 'Caribbean', '1. Blend the olive oil, cilantro, parsley, oregano, mint, chilies, the juice of the oranges, limes and grapefruit, the garlic, cumin, allspice, salt and pepper into a marinade.
2. Lay the pork belly in a large dish, pour the marinade over it and rub it in everywhere. Cover and chill overnight.
3. Heat the oven to 275°F (140°C). Lift the pork into a large roasting dish, leaving most of the marinade behind, cover with foil and roast for 4 1/2 hours, basting it 3 or 4 times.
4. Uncover, turn the oven up to 350°F (180°C) and roast for 15 to 20 minutes more, until colored and soft enough to cut with a spoon.
5. Pull the pork apart and serve topped with more chopped cilantro and parsley.', 20, 285, 8, '$$', array[]::text[], 'https://www.theguardian.com/food/2020/jul/04/andi-oliver-antiguan-feast-recipes-slow-cooked-pork-belly-corn-chilli-lime-mango-chow-spiced-bread-butter-pudding', 'https://www.themealdb.com/images/media/meals/t1hg8s1780087329.jpg', 'Photo from TheMealDB'),
  ('52784', 'Smoky Lentil Chili with Squash', 'British', '1. Heat the oven to 400°F (200°C). Slice the squash into thin crescents, drizzle with a little oil and salt and roast for 20 to 30 minutes, turning halfway, until soft. Cool and cube it.
2. Meanwhile, rinse the lentils, cover them with water, bring to a boil and simmer uncovered for 20 to 30 minutes, until tender. Drain.
3. Heat the oil in a medium pot over low heat and cook the chopped onion and leek for about 5 minutes. Add the garlic, cumin and coriander for a few minutes, then the paprika, cinnamon, chili powder, cocoa, salt and oregano.
4. Add the tomatoes, water and diced carrots and simmer, covered, for about 20 minutes, until the vegetables are tender, stirring and adding water if needed.
5. Add the lentils and squash and cook for 10 minutes more.
6. For the cashew cream, soak the cashews in boiling water for at least 4 hours, drain and blend with about 1/2 cup of fresh water, a pinch of salt and the vinegar until creamy. Serve it on the chili.', 20, 60, 6, '$', array['vegan', 'vegetarian']::text[], 'http://www.wholeheartedeats.com/2016/11/smoky-lentil-chili-squash/', 'https://www.themealdb.com/images/media/meals/uwxqwy1483389553.jpg', 'Photo from TheMealDB'),
  ('52770', 'Spaghetti Bolognese', 'Italian', '1. Fry the chopped onions in the oil over fairly high heat for 3 to 4 minutes. Add the garlic and beef and fry until browned.
2. Add the sliced mushrooms and oregano and cook for a couple of minutes more.
3. Stir in the tomatoes, broth, tomato paste, Worcestershire sauce and seasoning. Bring to a boil, then cover and simmer for 30 minutes, stirring now and then.
4. Meanwhile, cook the spaghetti in salted boiling water as the package says and drain it.
5. Stir the sauce into the spaghetti and serve with parmesan for sprinkling on top.', 10, 45, 4, '$$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/sutysw1468247559.jpg', 'Photo from TheMealDB'),
  ('52872', 'Spanish Tortilla', 'Spanish', '1. Cook the sliced onion slowly in the oil and butter in a large non-stick frying pan over low heat for about 15 minutes, until soft but not brown.
2. Add the thinly sliced potatoes, cover and cook for 15 to 20 minutes more, stirring now and then, until soft.
3. Stir in 2 crushed garlic cloves, then the beaten eggs. Cover and cook gently for about 20 minutes, until the edges and bottom are golden and the top is set but still a little wobbly.
4. Slide it onto a plate, cover with another plate, flip it and slide it back into the pan for a few minutes to finish. Serve warm or cold, scattered with parsley.
5. On the side, toast slices of baguette, rub them with the rest of the garlic and top with grated tomato, a pinch of salt and a drizzle of olive oil.', 15, 60, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/spanish-tortilla', 'https://www.themealdb.com/images/media/meals/quuxsx1511476154.jpg', 'Photo from TheMealDB'),
  ('53175', 'Spanish-style slow-cooked lamb shoulder & beans', 'Spanish', '1. Mix the smoked paprika, rosemary and a large pinch of salt. Cut slashes all over the lamb and rub the mix in. If you have time, marinate it for up to 24 hours.
2. Heat the oven to 300°F (150°C). Heat the oil in a large flameproof casserole over medium-high heat and cook the chopped onions and carrots and the garlic cloves for 5 minutes.
3. Pour in the broth and bring to a boil. Nestle the lamb in the pan, cover and roast for 2 hours.
4. Lift out the lamb, stir the drained beans, sliced peppers and olives into the pan, put the lamb back on top and roast uncovered for 1 1/2 hours more.
5. Shred the lamb with two forks and stir the parsley into the beans before serving.', 20, 225, 8, '$$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/spanish-style-slow-cooked-lamb-shoulder-beans', 'https://www.themealdb.com/images/media/meals/9kwatm1763327074.jpg', 'Photo from TheMealDB'),
  ('53105', 'Spiced smoky barbecued chicken', 'Australian', '1. Mash the garlic with a little salt, then mix in the lemon zest and juice, the curry powder, pepper flakes, oil and plenty of black pepper.
2. Toss the chicken in the marinade while the barbecue heats.
3. Lay the herb bunches on the hot grill and put the chicken on top, skin side up. Close the lid and cook for about 10 minutes, then turn and cook for 20 to 30 minutes more, until charred and cooked through.
4. Without a barbecue, roast the chicken on the herbs in a 400°F (200°C) oven for 35 to 40 minutes.', 15, 40, 6, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/spiced-smoky-barbecued-chicken', 'https://www.themealdb.com/images/media/meals/a08uqk1761848682.jpg', 'Photo from TheMealDB'),
  ('52771', 'Spicy Arrabiata Penne', 'Italian', '1. Cook the pasta in a large pot of salted boiling water as the package says, about 9 minutes.
2. Meanwhile, heat the oil in a large skillet over medium-high heat and cook the garlic for 1 to 2 minutes, until fragrant.
3. Add the tomatoes, pepper flakes, Italian seasoning, salt and pepper. Bring to a boil and cook for 5 minutes, then stir in the chopped basil.
4. Drain the pasta and toss it in the sauce. Serve warm with parmesan and more basil.', 5, 15, 4, '$', array['vegetarian']::text[], null, 'https://www.themealdb.com/images/media/meals/ustsqw1468250014.jpg', 'Photo from TheMealDB'),
  ('52797', 'Spicy North African Potato Salad', 'Moroccan', '1. Put the potatoes in a pot of cold water, bring to a boil and cook for about 20 minutes, until a knife goes straight through.
2. Whisk the harissa, oil, lemon juice, salt and pepper.
3. Drain the potatoes, cut them in half and stir in the harissa dressing and the sliced green onions.
4. Spread the arugula in a large salad bowl, add the potatoes and toss. Top with the crumbled feta, mint and pine nuts and season.', 10, 20, 4, '$', array['vegetarian']::text[], null, 'https://www.themealdb.com/images/media/meals/urtwux1486983078.jpg', 'Photo from TheMealDB'),
  ('52849', 'Spinach & Ricotta Cannelloni', 'Italian', '1. For the tomato sauce, heat the oil in a large pan and fry the garlic for 1 minute. Add the sugar, vinegar, tomatoes and seasoning and simmer for 20 minutes, until thick. Stir in the basil and spread it in 2 shallow baking dishes.
2. Beat the mascarpone with the milk until smooth and season.
3. Wilt the spinach by pouring boiling water over it in a colander, in batches. When cool, squeeze it dry and chop it. Mix it with 100 g of the parmesan, the ricotta, salt, pepper and nutmeg.
4. Heat the oven to 400°F (200°C). Pipe the filling into the cannelloni tubes with a bag and lay them side by side on the tomato sauce.
5. Spoon the mascarpone sauce over them and top with the rest of the parmesan and the torn mozzarella.
6. Bake for 30 to 35 minutes, until golden and bubbling, and let it stand for 5 minutes before serving.', 50, 40, 10, '$$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/531632/spinach-and-ricotta-cannelloni', 'https://www.themealdb.com/images/media/meals/wspuvp1511303478.jpg', 'Photo from TheMealDB'),
  ('53040', 'Spring onion and prawn empanadas', 'Portuguese', '1. For the dough, rub the butter into the flour, then add the egg white and half of the yolk (keep the rest), the vinegar, a pinch of salt and enough cold water to make a soft dough. Knead until smooth, wrap and rest for 30 minutes.
2. Heat the oven to 350°F (180°C). Slice the green onions and fry them gently in a little oil until soft. Add the chopped chili and garlic, then the shrimp, and cook until they''re opaque. Season.
3. Lift out the shrimp, boil the juices until they thicken and put the shrimp back.
4. Divide the dough into 8 balls and roll each into a thin circle. Put some filling on one half, sprinkle with feta, fold over and crimp the edges to seal.
5. Put them on an oiled baking sheet, brush with the rest of the yolk mixed with a splash of water and bake for about 30 minutes, until golden.', 50, 40, 4, '$$', array['pescatarian']::text[], 'https://www.olivemagazine.com/recipes/fish-and-seafood/spring-onion-and-prawn-empanadas/', 'https://www.themealdb.com/images/media/meals/1c5oso1614347493.jpg', 'Photo from TheMealDB'),
  ('52866', 'Squash linguine', 'Italian', '1. Heat the oven to 400°F (200°C). Put the cubed squash and the garlic on a baking sheet, drizzle with the oil and roast for 35 to 40 minutes, until soft. Season.
2. Cook the pasta as the package says. Drain it, keeping the water.
3. Blend the squash and garlic with about 1 2/3 cups (400 ml) of the pasta water into a sauce.
4. Fry the sage leaves in a little oil until crisp and drain them.
5. Tip the pasta and sauce into the pan and warm through. Scatter with the sage.', 5, 50, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/creamy-squash-linguine', 'https://www.themealdb.com/images/media/meals/wxswxy1511452625.jpg', 'Photo from TheMealDB'),
  ('53102', 'Squid, chickpea & chorizo salad', 'Australian', '1. Broil or grill the whole peppers until charred all over. Cover them in a bowl until cool, then peel, seed and slice them.
2. Mix the peppers and their juices with the drained chickpeas, chopped parsley, chili and garlic.
3. Heat a large frying pan until smoking. Add a splash of the oil and the sliced squid and stir-fry for 30 seconds. Scatter in the diced chorizo and cook for 30 seconds more.
4. Tip it into the bowl, season, dress with the rest of the oil and the lemon juice and zest, and mix. Serve on a platter.', 20, 20, 6, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/squid-chickpea-chorizo-salad', 'https://www.themealdb.com/images/media/meals/wsu0rc1761848482.jpg', 'Photo from TheMealDB'),
  ('52980', 'Stamppot', 'Dutch', '1. Peel the potatoes, cut them into even pieces and boil them with the bay leaves in salted water for 20 minutes. Remove the bay leaves.
2. Wash the kale, remove the tough stems and cut it into thin strips. Chop the shallots.
3. Melt 1 tbsp of the butter in a frying pan and cook the shallots for a few minutes. Add the kale and 2 tbsp of water, season and cook for about 10 minutes, until tender. Meanwhile, heat the sausages.
4. Warm the milk. Drain the potatoes, dry them and mash them with the warm milk and the rest of the butter. Season with nutmeg, salt and pepper.
5. Mix the kale into the mash and serve topped with slices of the sausage, with mustard or gravy.', 15, 30, 4, '$', array[]::text[], 'https://www.thespruceeats.com/stamppot-with-curly-kale-and-rookworst-1128837', 'https://www.themealdb.com/images/media/meals/hyarod1565090529.jpg', 'Photo from TheMealDB'),
  ('53110', 'Sticky Chicken', 'Australian', '1. Cut 3 slashes in each drumstick.
2. Mix the soy sauce, honey, oil, tomato paste and mustard, pour it over the chicken and coat well. Marinate for 30 minutes at room temperature, or overnight in the fridge.
3. Heat the oven to 400°F (200°C).
4. Tip the chicken into a shallow roasting pan and roast for about 35 minutes, turning now and then, until cooked through and glossy.', 35, 35, 4, '$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/sticky-chicken', 'https://www.themealdb.com/images/media/meals/cj56fs1762340001.jpg', 'Photo from TheMealDB'),
  ('52817', 'Stovetop Eggplant With Harissa, Chickpeas, and Cumin Yogurt', 'American', '1. Heat the oil in a 12-inch skillet over high heat until shimmering. Add the small whole eggplants and lower the heat to medium.
2. Season them and turn them often until browned on all sides and a fork goes in easily, about 20 minutes. Sprinkle in a little water if they start to burn.
3. Mix the harissa with the drained chickpeas and the tomatoes, add them to the pan and cook for about 5 minutes, until the tomatoes blister and break down. Season and add a little water to make it saucy.
4. Meanwhile, mix the yogurt with the cumin and season.
5. Top the eggplant with parsley and a drizzle of olive oil, and serve with the yogurt.', 5, 30, 4, '$', array['vegetarian']::text[], 'http://www.seriouseats.com/2014/09/one-pot-wonders-stovetop-eggplant-harissa-chickpeas-cumin.html', 'https://www.themealdb.com/images/media/meals/yqwtvu1487426027.jpg', 'Photo from TheMealDB'),
  ('53067', 'Stuffed Bell Peppers with Quinoa and Black Beans', 'Mexican', '1. Cook the quinoa as the package says. Heat the oven to 375°F (190°C) and grease a 9 x 13-inch baking dish.
2. Halve the peppers, seed them and bake them cut side up in the dish for 15 to 20 minutes, until slightly soft.
3. Meanwhile, heat the oil in a large skillet over medium heat and cook the chopped onion for 3 to 4 minutes, then the garlic for 1 minute.
4. Stir in the quinoa, drained beans, corn, tomatoes, cumin, chili powder, smoked paprika, salt and pepper and cook for 5 to 7 minutes. Take it off the heat and stir in 1 cup of the cheese.
5. Fill the peppers, top with the rest of the cheese and bake for 15 to 20 minutes more, until the cheese melts. Let them cool for 5 minutes and scatter with cilantro.', 20, 45, 4, '$', array['vegetarian']::text[], null, 'https://www.themealdb.com/images/media/meals/b66myb1683207208.jpg', 'Photo from TheMealDB'),
  ('53008', 'Stuffed Lamb Tomatoes', 'Greek', '1. Heat the oven to 350°F (180°C). Slice the tops off the tomatoes and keep them. Scoop out most of the pulp, chop it and keep the juice. Sprinkle the insides with a little sugar and put the tomatoes on a baking sheet.
2. Heat 2 tbsp of the oil in a large frying pan and cook the chopped onion and garlic gently for about 10 minutes, until soft.
3. Add the lamb, cinnamon and tomato paste, turn up the heat and fry until browned. Add the tomato pulp and juice, the rice and the broth, and season well.
4. Bring to a boil and simmer for about 15 minutes, until the rice is tender and the liquid absorbed. Let it cool a little and stir in the herbs.
5. Fill the tomatoes to the top, put the lids on, drizzle with the rest of the oil, sprinkle 3 tbsp of water into the pan and bake for 35 minutes. Serve hot or cold.', 20, 60, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/stuffed-tomatoes-lamb-mince-dill-rice', 'https://www.themealdb.com/images/media/meals/u55lbp1585564013.jpg', 'Photo from TheMealDB'),
  ('53113', 'Sukuma Wiki', 'Kenyan', '1. Heat the oil in a large skillet over medium heat and cook the sliced onions for 5 to 7 minutes, stirring now and then, until soft.
2. Add the shredded kale, mix well, lower the heat to medium-low, cover and cook for 5 minutes.
3. Uncover, add salt to taste and stir in the cream. Cook for 5 minutes more, stirring now and then, until slightly thick. Serve with a stew and ugali.', 10, 20, 4, '$', array['vegetarian']::text[], 'https://tasteoftheplace.com/sukuma-wiki/', 'https://www.themealdb.com/images/media/meals/60o82j1762341177.jpg', 'Photo from TheMealDB'),
  ('52911', 'Summer Pistou', 'French', '1. Heat the oil in a large pan and fry the sliced leeks and diced zucchini for 5 minutes to soften.
2. Pour in the broth and add three quarters of the drained beans, the chopped green beans and half of the chopped tomatoes. Simmer for 5 to 8 minutes, until tender.
3. Meanwhile, blend the rest of the beans and tomatoes with the garlic and basil until smooth, then stir in the parmesan.
4. Stir this sauce into the soup, cook for 1 minute and serve.', 10, 20, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/summer-pistou', 'https://www.themealdb.com/images/media/meals/rqtxvr1511792990.jpg', 'Photo from TheMealDB'),
  ('53275', 'Sweet potato salad', 'Turkish', '1. Heat the oven to 400°F (200°C). Toss the sweet potato chunks with the oil and some seasoning and spread them on a lined baking sheet.
2. Roast for 30 to 35 minutes, until tender and golden. Let them cool.
3. Whisk the finely chopped shallots, sliced green onions, chopped chives, vinegar and honey with a little salt and pepper.
4. Gently toss the dressing through the sweet potatoes with your hands, so they don''t break up.', 15, 35, 6, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/sweet-potato-salad', 'https://www.themealdb.com/images/media/meals/z458v91763817681.jpg', 'Photo from TheMealDB'),
  ('53093', 'Syrian Spaghetti', 'Syrian', '1. Heat the oven to 350°F (175°C) and grease a 9 x 13-inch baking dish.
2. Cook the spaghetti in a large pot of lightly salted boiling water for 8 to 10 minutes, until al dente, and drain.
3. Stir in the tomato sauce, tomato paste, cinnamon, oil, salt and pepper and spread it in the dish.
4. Bake for about 1 hour, until the top is crunchy.', 10, 70, 6, '$', array['vegan', 'vegetarian']::text[], 'https://www.allrecipes.com/recipe/26303/syrian-spaghetti/', 'https://www.themealdb.com/images/media/meals/5fu4ew1760524857.jpg', 'Photo from TheMealDB'),
  ('53447', 'Tafelspitz', 'Austrian', '1. Cut the unpeeled onion in half and brown the cut sides well in a dry pan.
2. Put about 12 cups (3 liters) of water in a large pot with the chopped carrots, celeriac and parsnips, the leek, the onion halves, parsley, bay leaves and peppercorns, and bring to a boil.
3. Add the beef and simmer very gently for 2 1/2 to 3 hours, until tender, skimming off any foam and adding water as needed. Season with salt only after 2 hours.
4. Lift out the beef and keep it warm in a little of the broth. Season and strain the rest of the broth and serve it as a starter.
5. Slice the beef across the grain and serve it with roast potatoes and horseradish.', 15, 180, 6, '$$', array[]::text[], 'https://www.austria.info/en-gb/recipes/tafelspitz/', 'https://www.themealdb.com/images/media/meals/svf3d01780298321.jpg', 'Photo from TheMealDB'),
  ('52869', 'Tahini Lentils', 'Moroccan', '1. Mix the tahini with the zest and juice of the lemon and 3 1/2 tbsp (50 ml) of cold water into a runny dressing. Season.
2. Heat the oil in a wok or large frying pan over medium-high heat and fry the sliced onion with a pinch of salt for 2 minutes.
3. Add the garlic, sliced pepper, green beans and zucchini and fry for 5 minutes, stirring often.
4. Add the kale, cooked lentils and the dressing and stir for a couple of minutes, until the kale wilts and everything is coated.', 10, 10, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/veggie-tahini-lentils', 'https://www.themealdb.com/images/media/meals/vpxyqt1511464175.jpg', 'Photo from TheMealDB'),
  ('53026', 'Tamiya', 'Egyptian', '1. Soak the dried skinless broad beans in water overnight. Drain them and pat them dry.
2. Grind them in a food processor into a paste, without making it too smooth, or the patties fall apart.
3. Mix in the green onions, garlic, parsley, cumin, baking powder, cayenne and some salt and pepper. Chill for at least 30 minutes.
4. Shape the mixture into 1-inch balls, flatten them slightly and coat them in flour.
5. Heat at least 1 1/2 inches of oil to 365°F (185°C) and fry the patties in batches for about 5 minutes, turning once, until golden. Serve hot with a salad.', 45, 20, 4, '$', array['vegan', 'vegetarian']::text[], 'https://oukosher.org/recipes/tamiya-egyptian-dried-fava-bean-fritters/', 'https://www.themealdb.com/images/media/meals/n3xxd91598732796.jpg', 'Photo from TheMealDB'),
  ('52806', 'Tandoori chicken', 'Indian', '1. Mix the lemon juice with the paprika and the sliced red onions in a large shallow dish. Slash each chicken thigh three times, turn them in the juice and set aside for 10 minutes.
2. Mix the yogurt with the grated ginger, crushed garlic, garam masala, cumin, chili powder and turmeric, pour it over the chicken and mix well. Cover and chill for at least 1 hour, or up to a day.
3. Heat the broiler. Lift the chicken onto a rack over a baking sheet, brush with a little oil and broil for about 8 minutes on each side, until charred in places and cooked through.', 80, 20, 8, '$$', array[]::text[], 'http://www.bbcgoodfood.com/recipes/1660651/tandoori-chicken', 'https://www.themealdb.com/images/media/meals/qptpvt1487339892.jpg', 'Photo from TheMealDB'),
  ('53312', 'Tangy cabbage slaw', 'Ukrainian', '1. Whisk the mayonnaise, lemon zest and juice, vinegar, mustard and celery salt together and season well.
2. Add the shredded cabbages, grated carrots, thinly sliced onion and sliced celery and mix well.
3. Chill until serving. It keeps for up to 1 day.', 15, 0, 8, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/tangy-cabbage-slaw', 'https://www.themealdb.com/images/media/meals/e2g2r21764367568.jpg', 'Photo from TheMealDB'),
  ('53246', 'Tangy carrot, cabbage & onion salad', 'Vietnamese', '1. Put the grated carrots, shredded cabbage and thinly sliced onions in a bowl.
2. Stir the lime juice, peanut oil, chopped chili and sugar together until the sugar dissolves.
3. Pour it over the vegetables and toss. Add the herbs, toss again and scatter with the chopped peanuts.', 15, 0, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/tangy-carrot-red-cabbage-onion-salad', 'https://www.themealdb.com/images/media/meals/dbazbg1763779999.jpg', 'Photo from TheMealDB'),
  ('53404', 'Tavë Kosi Baked Lamb and Yogurt', 'Albanian', '1. Melt half of the butter with the olive oil in a large pan with a lid and brown the diced lamb over medium heat for about 5 minutes.
2. Add the garlic, 1 tsp of the oregano and 1 1/4 cups (300 ml) of the water, season, cover and simmer for 50 minutes, stirring a couple of times.
3. Add the rest of the water and the rice, bring to a boil, cover and cook for about 10 minutes, until the liquid has almost gone. Spread it in a baking dish with at least 2 inches of room on top.
4. Heat the oven to 350°F (180°C). Melt the rest of the butter in a small pan and stir in the flour for 2 minutes.
5. Mix the yogurt with the eggs and some salt and pepper, then quickly whisk in the flour mixture. Pour it over the lamb and sprinkle with the rest of the oregano.
6. Bake on the bottom shelf for 35 minutes, then on the middle shelf for 10 minutes more, until risen with a golden crust. Let it cool for 5 to 10 minutes.', 20, 110, 4, '$$', array[]::text[], 'https://www.myalbanianfood.com/recipe/albanian-tave-kosi/', 'https://www.themealdb.com/images/media/meals/a1mi7t1779643816.jpg', 'Photo from TheMealDB'),
  ('53405', 'Tavë me Presh ska Mish Meatless Leek Bake', 'Albanian', '1. Heat the oven to 350°F (180°C). Fry the sliced leeks in a little olive oil for a few minutes, until they start to brown.
2. Add the roasted, sliced peppers, garlic, broth, herbs, salt, pepper and paprika, stir, then add the rice.
3. Bring to a boil and simmer for 2 minutes.
4. Pour into a baking dish at least 2 inches deep and spread it out evenly.
5. Bake on the bottom shelf for 1 hour. Let it cool for 10 minutes in the oven with the door open before serving.', 15, 65, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.myalbanianfood.com/recipe/albanian-tave-presh-meatless-leek-bake/', 'https://www.themealdb.com/images/media/meals/p5m3w21779644533.jpg', 'Photo from TheMealDB'),
  ('52772', 'Teriyaki Chicken Casserole', 'Japanese', '1. Heat the oven to 350°F (175°C) and grease a 9 x 13-inch baking pan. Cook the brown rice if it isn''t cooked.
2. Bring the soy sauce, 1/2 cup of water, brown sugar, ginger and garlic to a boil in a small covered saucepan, then uncover and cook for 1 minute.
3. Mix the cornstarch with 2 tbsp of water, stir it into the sauce and cook until it starts to thicken.
4. Put the chicken in the pan, pour 1 cup of the sauce over it and bake for about 35 minutes, until cooked through. Shred it in the pan with two forks.
5. Meanwhile, steam the vegetables. Add them and the rice to the chicken with most of the rest of the sauce, toss and bake for 15 minutes more. Let it stand for 5 minutes and drizzle with the last of the sauce.', 15, 55, 4, '$', array[]::text[], null, 'https://www.themealdb.com/images/media/meals/wvpsxx1468256321.jpg', 'Photo from TheMealDB'),
  ('53208', 'Thai coconut & veg broth', 'Thai', '1. Fry the curry paste in the oil in a large saucepan or wok for 1 minute, until fragrant.
2. Add the broth, coconut milk and sugar and simmer for 3 minutes.
3. Add the noodles, sliced carrots and shredded cabbage and simmer for 4 to 6 minutes, until tender.
4. Stir in the bean sprouts and halved tomatoes, add lime juice and seasoning to taste, and serve sprinkled with green onions and cilantro.', 15, 15, 4, '$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/thai-coconut-veg-broth', 'https://www.themealdb.com/images/media/meals/4k8nzy1763583384.jpg', 'Photo from TheMealDB'),
  ('53195', 'Thai curry noodle soup', 'Thai', '1. Heat the oil in a saucepan over medium heat and cook the curry paste for 1 minute.
2. Add the vegetables and shrimp and cook for 3 minutes, until the shrimp are mostly pink.
3. Add the coconut milk, broth and noodles, bring to a boil, then simmer for 5 minutes, until the noodles are cooked and the vegetables still have a bite.
4. Divide between 2 bowls and sprinkle with the herbs, sliced chili and green onion.', 5, 15, 2, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/thai-curry-noodle-soup', 'https://www.themealdb.com/images/media/meals/118oj61763423896.jpg', 'Photo from TheMealDB'),
  ('53197', 'Thai pork & peanut curry', 'Thai', '1. Heat the oil in a large saucepan and cook the sliced green onions and chopped cilantro stalks for 1 minute. Add the sliced pork and cook for 5 minutes, until it starts to brown.
2. Stir in the curry paste and peanut butter for 30 seconds, then add the sugar, soy sauce, coconut milk and 3/4 cup of water.
3. Cover and simmer for 15 minutes, stirring now and then.
4. Uncover, add the corn and turn up the heat. Bubble for 3 minutes, until the sauce thickens a little. Stir in the lime juice, season and serve with the cilantro leaves and rice.', 10, 30, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/thai-pork-peanut-curry', 'https://www.themealdb.com/images/media/meals/snmtd61763426568.jpg', 'Photo from TheMealDB'),
  ('53205', 'Thai prawn curry', 'Thai', '1. Heat the oil in a medium saucepan and cook the chopped onion and ginger for a few minutes, until soft.
2. Stir in the curry paste for 1 minute, then add the tomatoes and coconut cream.
3. Bring to a boil and simmer for 5 minutes, adding a little boiling water if it gets too thick.
4. Add the shrimp and cook for 5 to 10 minutes, depending on their size. Serve with rice and chopped cilantro.', 5, 20, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/easy-thai-prawn-curry', 'https://www.themealdb.com/images/media/meals/qqlwv91763501559.jpg', 'Photo from TheMealDB'),
  ('53210', 'Thai pumpkin soup', 'Thai', '1. Heat the oven to 400°F (200°C). Toss the pumpkin chunks in a roasting pan with half of the oil and some seasoning and roast for 30 minutes, until golden and tender.
2. Meanwhile, gently cook the chopped onion, ginger and bruised lemongrass in the rest of the oil for 8 to 10 minutes.
3. Stir in the curry paste for 1 minute, then the roasted pumpkin, all but 3 tbsp of the coconut milk and the broth. Simmer for 5 minutes and remove the lemongrass.
4. Blend until smooth and reheat, seasoning with salt, pepper, lime juice and a pinch of sugar if needed.
5. Serve drizzled with the rest of the coconut milk and sprinkled with sliced chili.', 25, 45, 6, '$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/thai-pumpkin-soup', 'https://www.themealdb.com/images/media/meals/1brbso1763585098.jpg', 'Photo from TheMealDB'),
  ('52912', 'Three-cheese souffles', 'French', '1. Heat the oven to 400°F (200°C) and butter 4 small ramekins. Coat the insides with the parmesan. Bring the milk and bay leaves to a boil, turn off the heat and leave for 15 minutes.
2. Remove the bay leaves, add the butter and flour and whisk over low heat for about 6 minutes, until you have a smooth, thick sauce.
3. Move it to a large bowl and stir in the mustard, a pinch of cayenne, the grated Gruyère and the egg yolks.
4. Whisk the egg whites in a very clean bowl until soft peaks form, and gently fold them into the sauce in three parts. Fill the ramekins.
5. Top each with a slice of goat cheese and bake on a baking sheet for 20 to 25 minutes, until risen.
6. For a second bake, turn them out upside down into a baking dish, top with the rest of the goat cheese, pour the cream over them and bake for 8 to 10 minutes, until golden. Serve with a salad.', 35, 35, 4, '$$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/3028701/threecheese-souffls', 'https://www.themealdb.com/images/media/meals/sxwquu1511793428.jpg', 'Photo from TheMealDB'),
  ('53444', 'Tirolean Dumplings', 'Austrian', '1. Finely chop the shallots and dice the ham. Cook the shallots in a little butter until translucent, add the ham and parsley, fry briefly and take it off the heat.
2. Cut the bread into cubes and put it in a bowl. Beat the milk with the eggs, salt, pepper and nutmeg and pour it over the bread.
3. Stir in the ham mixture and the flour into a fairly firm dough, adding more bread or flour if needed. Smooth the top and leave it for about 30 minutes.
4. Bring a large pan of salted water to a boil. With wet hands, shape the dough into dumplings, small or medium-sized.
5. Drop them into the boiling water, bring back to a boil and simmer gently for 8 to 20 minutes, depending on size. Drain and serve with chopped parsley and browned butter.', 45, 20, 4, '$', array[]::text[], 'https://www.austria.info/en-gb/recipes/tirolean-dumplings/', 'https://www.themealdb.com/images/media/meals/jbw8m11780155348.jpg', 'Photo from TheMealDB'),
  ('52822', 'Toad In The Hole', 'British', '1. Heat the oven to 400°F (200°C). Brown the sausages in a non-stick pan.
2. Pour the oil into a 12 x 10-inch roasting pan, about 2 inches deep, and heat it in the oven for 5 minutes.
3. Put the flour in a bowl, crack in the eggs and stir in the horseradish. Gradually beat in the milk and season.
4. Put the sausages in the hot pan, pour the batter over them and top with the tomatoes. Bake for 30 minutes, until puffed and golden.', 10, 40, 4, '$', array[]::text[], 'http://www.deliciousmagazine.co.uk/recipes/georgina-fuggles-horseradish-and-vine-tomato-toad-in-the-hole/', 'https://www.themealdb.com/images/media/meals/ytuvwr1503070420.jpg', 'Photo from TheMealDB'),
  ('53240', 'Tofu, greens & cashew stir-fry', 'Vietnamese', '1. Heat the oil in a non-stick wok and fry the broccoli florets over high heat for about 5 minutes, until just tender, adding a little water if it catches.
2. Add the sliced garlic and chili for 1 minute.
3. Toss in the sliced green onions, the soybeans, the bok choy and the cubed tofu and stir-fry for 2 to 3 minutes.
4. Add the hoisin sauce, soy sauce and cashews and toss until hot.', 10, 10, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/tofu-greens-cashew-stir-fry', 'https://www.themealdb.com/images/media/meals/minfsc1763766806.jpg', 'Photo from TheMealDB'),
  ('53196', 'Tom yum (hot & sour) soup with prawns', 'Thai', '1. Bring the broth to a boil in a medium saucepan.
2. Add the bruised lemongrass, the galangal, the cilantro stalks and roots and the lime leaves and simmer for 2 minutes.
3. Add the shrimp, fish sauce, chilies and lime juice and bring back to a boil.
4. Taste and add more lime juice or fish sauce if needed. Serve garnished with cilantro leaves.', 15, 10, 2, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/tom-yum-hot-sour-soup-prawns', 'https://www.themealdb.com/images/media/meals/9c5nlx1763424766.jpg', 'Photo from TheMealDB'),
  ('53032', 'Tonkatsu pork', 'Japanese', '1. Trim the large strip of fat from each chop, then pound them between two sheets of parchment to about 1/2 inch (1 cm) thick and push them back into shape.
2. Put the flour, beaten eggs and breadcrumbs in three wide bowls. Season the pork and coat it in flour, then egg, then breadcrumbs.
3. Heat about 3/4 inch of oil in a large frying pan to 350°F (180°C), or until a breadcrumb sinks slightly and then sizzles.
4. Fry 2 chops at a time for 1 1/2 minutes on each side, then rest them on a rack for 5 minutes.
5. Meanwhile, whisk the ketchup, Worcestershire sauce, oyster sauce and sugar into a sauce, adding a splash of water if it''s thick. Slice the pork and drizzle with the sauce.', 20, 15, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/tonkatsu-pork', 'https://www.themealdb.com/images/media/meals/lwsnkl1604181187.jpg', 'Photo from TheMealDB'),
  ('53318', 'Torta de fiambre', 'Uruguayan', '1. Heat the oven to 425°F (220°C). Line the bottom of an 8 to 9-inch springform pan with parchment, leaving some overhang. Grate the cheese.
2. Whisk the eggs, oil, milk, flour, baking powder, salt and a pinch of oregano for 1 to 2 minutes into a very runny batter.
3. Pour in half of the batter, lay the ham and cheese on top and pour over the rest.
4. Bake for 20 to 25 minutes, until golden on top. Let it rest for a few minutes before unmolding. Serve hot or cold.', 10, 25, 6, '$', array[]::text[], 'https://jennyisbaking.com/2020/12/30/klassische-torta-de-fiambre-aus-uruguay/#recipe', 'https://www.themealdb.com/images/media/meals/okl9cm1764371087.jpg', 'Photo from TheMealDB'),
  ('53075', 'Tortang Talong', 'Filipino', '1. Grill the eggplants over a gas flame or on a hot grill pan until the skins are almost black.
2. Let them cool a little and peel off the skin, keeping the stems on.
3. Beat the eggs with the salt in a wide bowl.
4. Flatten each eggplant on a board with a fork and dip it in the egg.
5. Heat the oil in a pan over medium heat and fry the eggplants for 3 to 4 minutes on each side, until the egg is cooked.', 20, 25, 4, '$', array['vegetarian']::text[], 'https://www.sainsburysmagazine.co.uk/recipes/mains/tortang-talong', 'https://www.themealdb.com/images/media/meals/va668f1683209318.jpg', 'Photo from TheMealDB'),
  ('53416', 'Trinxat (Potato, Cabbage and Bacon Hash)', 'Andorran', '1. Boil the chopped cabbage and potatoes in salted water for 30 to 40 minutes, until tender. Drain very well, return them to the pot over low heat and let them steam dry.
2. Meanwhile, fry the bacon until crisp, keeping the fat, and chop it into small pieces.
3. Mash the potatoes and cabbage with the minced garlic and season.
4. Press the mash into a skillet with the bacon and the bacon fat and fry until golden brown underneath. Flip it and brown the other side.
5. Cut into servings and garnish with chopped parsley.', 10, 50, 4, '$', array[]::text[], 'https://www.internationalcuisine.com/trinxat/#wprm-recipe-container-12938', 'https://www.themealdb.com/images/media/meals/khpso71779732715.jpg', 'Photo from TheMealDB'),
  ('52975', 'Tuna and Egg Briks', 'Tunisian', '1. Heat 2 tsp of the oil in a large saucepan and cook the sliced green onions over low heat for 3 minutes. Add the spinach, cover and cook for 2 to 3 minutes, until wilted. Drain and let it cool.
2. Cut 24 rounds about 5 inches (12.5 cm) wide from the filo, 6 from each sheet, and keep them covered.
3. Squeeze the spinach dry and mix it with the drained tuna, the beaten eggs, hot sauce, salt and pepper.
4. Heat the oven to 400°F (200°C). Stack 3 filo rounds, brushing each lightly with oil. Put a heaped tablespoon of filling in the middle, fold into a half-moon and twist the edges to seal. Make 8 in all.
5. Brush them with the rest of the oil and bake on a non-stick sheet for 12 to 15 minutes, until crisp and golden.
6. Mix the diced tomatoes and cucumber with the lemon juice and seasoning, and serve with the briks and the apricot jam.', 30, 25, 4, '$$', array['pescatarian']::text[], 'http://allrecipes.co.uk/recipe/3096/tunisian-tuna-and-egg-briks.aspx', 'https://www.themealdb.com/images/media/meals/2dsltq1560461468.jpg', 'Photo from TheMealDB'),
  ('52852', 'Tuna Nicoise', 'French', '1. Heat the oven to 400°F (200°C). Toss the potatoes with 2 tsp of the olive oil and some seasoning and roast them on a large baking sheet for 20 minutes, stirring halfway, until crisp and cooked.
2. Meanwhile, put the eggs in a small pan of water, bring to a boil and simmer for 8 to 10 minutes. Cool them in cold water, peel and halve them.
3. In a large salad bowl, whisk the rest of the oils with the vinegar and capers and season.
4. Add the thinly sliced onion, the spinach, the drained tuna and the potatoes and toss gently. Top with the eggs and serve right away.', 10, 20, 4, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/9529/winter-tuna-nioise', 'https://www.themealdb.com/images/media/meals/yypwwq1511304979.jpg', 'Photo from TheMealDB'),
  ('52972', 'Tunisian Lamb Soup', 'Tunisian', '1. Brown the lamb in a casserole over high heat. Set it aside and pour off all but 1 tbsp of the fat.
2. Lower the heat to medium and cook the garlic, chopped onion and spinach for about 5 minutes, until the onion is translucent and the spinach wilted.
3. Return the lamb and add the tomato paste, cumin, harissa, broth, drained chickpeas, lemon juice, salt and pepper. Simmer over low heat for about 20 minutes.
4. Add the pasta and cook for about 15 minutes, until tender.', 10, 45, 4, '$$', array[]::text[], 'http://allrecipes.co.uk/recipe/16694/tunisian-lamb-soup.aspx', 'https://www.themealdb.com/images/media/meals/t8mn9g1560460231.jpg', 'Photo from TheMealDB'),
  ('52845', 'Turkey Meatloaf', 'British', '1. Heat the oven to 350°F (180°C). Heat the oil in a large frying pan and cook the chopped onion for 8 to 10 minutes, until soft. Stir in the garlic, Worcestershire sauce and 2 tsp of the tomato paste and let it cool.
2. Mix the turkey, egg, breadcrumbs and onion mixture well and season. Shape it into a rectangular loaf in a large roasting pan.
3. Spread 1 tbsp of the barbecue sauce over the top and bake for 30 minutes.
4. Meanwhile, drain one can of beans only and mix both cans with the rest of the barbecue sauce and tomato paste. Season.
5. Spoon the beans around the meatloaf and bake for 15 minutes more, until it''s cooked through and the beans are hot. Scatter with parsley and serve in slices.', 20, 50, 4, '$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/turkey-meatloaf', 'https://www.themealdb.com/images/media/meals/ypuxtw1511297463.jpg', 'Photo from TheMealDB'),
  ('53251', 'Turkish lahmacun', 'Turkish', '1. Put the flour in a large bowl, make a well in the middle and sprinkle in the yeast. Pour 1/2 cup (125 ml) of water over the yeast, cover it with a little of the flour and leave it in a warm place for 15 minutes, until the surface cracks.
2. Mix in 1 cup (250 ml) more water and 1 tsp of salt and knead for about 10 minutes, until elastic. Cover and let it rise for 30 minutes, until doubled.
3. Heat the oven as high as it goes (about 475°F/240°C) and sprinkle baking sheets with cornmeal.
4. Peel, seed and chop the tomatoes and finely dice the seeded chilies. Mix them with the green onions, half of the parsley (finely chopped), the beef, the spices, 1 tsp of salt and 1/2 tsp of pepper.
5. Divide the dough into 4 balls, roll each into a thin circle and spread with a thin layer of the meat.
6. Bake each for 10 to 15 minutes, until the edges darken. Top with the rest of the parsley, the sliced red onion and a squeeze of lemon, and serve right away.', 60, 15, 4, '$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/lahmacun', 'https://www.themealdb.com/images/media/meals/tqd3ac1763786065.jpg', 'Photo from TheMealDB'),
  ('53250', 'Vegan banh mi', 'Vietnamese', '1. Toss the shredded vegetables with the vinegar, sugar and 1 tsp of salt and let them pickle while you make the rest.
2. Heat the oven to 350°F (180°C). Cut the baguette into 4 pieces and slice each in half lengthwise. Warm them in the oven for 5 minutes.
3. Spread each piece with hummus. Top 4 of them with slices of tempeh and the pickled vegetables.
4. Sprinkle with the herbs and some hot sauce and close the sandwiches.', 15, 5, 4, '$', array['vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/boxing-day-banh-mi', 'https://www.themealdb.com/images/media/meals/sonirb1763782831.jpg', 'Photo from TheMealDB'),
  ('52775', 'Vegan Lasagna', 'Italian', '1. Heat the oven to 350°F (180°C). Boil the diced carrot, onion and zucchini for 5 to 7 minutes, until soft. Add the lentils and simmer for about 20 minutes, stirring, until soft. Stir in some chopped cilantro.
2. Blanch the spinach for a minute or two and set it aside. Cook the lasagne sheets in the same pan, then drain them.
3. For the sauce, melt the vegan butter, stir in the flour, then gradually whisk in the soy milk with the mustard and vinegar. Cook, stirring, until smooth and thick.
4. Layer the lentils, spinach, lasagne sheets and sauce in a baking dish, finishing with sauce.
5. Bake for about 25 minutes.', 20, 55, 4, '$', array['vegetarian']::text[], null, 'https://www.themealdb.com/images/media/meals/rvxxuy1468312893.jpg', 'Photo from TheMealDB'),
  ('53000', 'Vegetable Shepherds Pie', 'Irish', '1. Heat the oven to 450°F (230°C). Bake the potatoes on a lined sheet for about 45 minutes, until tender. Peel them, press them through a ricer and stir in the butter, then the milk. Season.
2. Soak the dried mushrooms in 3 cups of hot water. Simmer the lentils with 1 garlic clove, 1 tsp of salt and 4 cups of water for 15 to 20 minutes, until tender but not mushy. Drain and discard the garlic.
3. Heat 3 tbsp of oil in a large heavy pot and cook the onions for about 12 minutes, until soft. Add the chopped garlic for 1 minute, then the tomato paste for 2 to 3 minutes, until caramelized.
4. Add the bay leaves and wine and scrape the pan. Add the mushrooms and pour in their liquid, leaving the grit behind. Simmer until reduced by half, about 10 minutes, then add the broth and reduce by half again, about 45 minutes.
5. Strain the sauce into a saucepan and bring to a boil. Stir in the cornstarch mixed with 2 tbsp of water and simmer for 5 minutes, until thick. Stir in the soy sauce and season.
6. Toss the chopped vegetables with 2 tbsp of oil, the rosemary, salt and pepper, and roast on 2 sheets for 20 to 25 minutes. Spread the lentils in a 3-quart baking dish, top with the vegetables and chopped herbs, pour the sauce over and cover with the potatoes. Bake for about 30 minutes and let it stand for 15 minutes.', 45, 150, 8, '$$', array['vegetarian']::text[], null, 'https://www.themealdb.com/images/media/meals/w8umt11583268117.jpg', 'Photo from TheMealDB'),
  ('52863', 'Vegetarian Casserole', 'British', '1. Heat the oil in a large heavy pan and cook the chopped onion gently for 5 to 10 minutes, until soft.
2. Add the garlic, paprika, cumin, dried thyme and the chopped carrots, celery and peppers and cook for 5 minutes.
3. Add the chopped tomatoes, broth, sliced zucchini and thyme sprigs and cook for 20 to 25 minutes.
4. Remove the thyme sprigs, stir in the cooked lentils and bring back to a simmer. Serve with rice, mash or quinoa.', 10, 40, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/1993645/vegetarian-casserole', 'https://www.themealdb.com/images/media/meals/vptwyt1511450962.jpg', 'Photo from TheMealDB'),
  ('52867', 'Vegetarian Chilli', 'British', '1. Heat the oven to 400°F (200°C). Cook the roasted vegetables in a casserole dish for 15 minutes.
2. Add the drained beans and the tomatoes, season and cook for 10 to 15 minutes more, until piping hot.
3. Heat the grain pouch in the microwave for 1 minute and serve with the chili.', 5, 30, 2, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/veggie-chilli', 'https://www.themealdb.com/images/media/meals/wqurxy1511453156.jpg', 'Photo from TheMealDB'),
  ('53325', 'Venezuelan Arepas', 'Venezuelan', '1. Heat the oven to 400°F (210°C). Dissolve the salt in the room-temperature water in a large bowl.
2. Slowly add the precooked cornmeal while you stir, until smooth. Let the dough rest for 5 minutes. It should be firm but easy to shape.
3. Heat a griddle or non-stick pan over medium heat and oil it lightly.
4. With wet hands, shape about 2 tablespoons of dough into a ball, then flatten it into a disc about 3/4 inch thick and 4 inches wide, smoothing any cracks.
5. Cook the arepas in batches for 4 to 5 minutes on each side, until golden.
6. Bake them on a baking sheet for 10 minutes, until slightly puffy and they sound hollow when tapped. Serve hot, plain or filled.', 20, 25, 4, '$', array['vegan', 'vegetarian']::text[], 'https://familiakitchen.com/how-to-make-arepas/', 'https://www.themealdb.com/images/media/meals/3hcy191764376285.jpg', 'Photo from TheMealDB'),
  ('53327', 'Venezuelan Coconut Chicken', 'Venezuelan', '1. Cut the chicken into bite-size pieces, slice the onions and mince the garlic.
2. Heat the oil in a frying pan over medium heat and cook the onions until translucent. Put them in a blender.
3. Add the tomatoes, garlic, turmeric, cumin, sugar, ginger paste, coconut milk and water and blend until smooth.
4. Brown the chicken on all sides in the same pan, about 3 minutes.
5. Add the blended sauce and the bay leaves, bring to a simmer and cook for 15 to 20 minutes, until the chicken is cooked and the sauce creamy. Remove the bay leaves, season and serve with white rice.', 15, 25, 2, '$$', array[]::text[], 'https://www.reluctantgourmet.com/venezuelan-coconut-chicken/#recipe', 'https://www.themealdb.com/images/media/meals/z2sw3o1764378271.jpg', 'Photo from TheMealDB'),
  ('53326', 'Venezuelan Sancocho', 'Venezuelan', '1. Put the beef shank, half an onion, the half bell pepper, 4 whole garlic cloves, the dark green leek leaves and the broth in a large pot. Simmer for 45 to 60 minutes, until the meat is fork-tender.
2. Lift out and discard the large vegetable pieces and the bones.
3. Add the rest of the onion, diced, 2 minced garlic cloves, the chopped red pepper, the sliced light green leek, the green onions, the cassava and the corn, cut into rounds. Cover and simmer over medium heat for 5 to 8 minutes, until the cassava starts to soften.
4. Add the yautia, yam and squash, cut into chunks, and simmer covered for 5 to 6 minutes, until tender. Don''t overcook them, or they fall apart.
5. Season with salt, add chopped cilantro and the last 2 garlic cloves, minced, and simmer for 2 minutes. Serve in large bowls with lime or hot sauce.', 20, 80, 6, '$$', array[]::text[], 'https://mommyshomecooking.com/easy-venezuelan-sancocho/#recipe', 'https://www.themealdb.com/images/media/meals/8859m71764377470.jpg', 'Photo from TheMealDB'),
  ('53228', 'Vietnamese caramel trout', 'Vietnamese', '1. Cook the rice. Put the sugar in a large shallow pan with a small splash of water and heat gently, swirling, until it dissolves.
2. Turn up the heat and bubble the syrup until it''s dark amber. Add the fish sauce, most of the sliced chili and ginger and 1 tbsp of water, and boil again until syrupy.
3. Add the fish skin side down and the halved bok choy cut side down. Cover and simmer for 4 to 5 minutes, until the fish is cooked and the bok choy has wilted.
4. Turn off the heat, squeeze over the lemon and scatter with the rest of the chili and ginger and the cilantro. Serve with rice.', 5, 15, 2, '$$', array['pescatarian']::text[], 'https://www.bbcgoodfood.com/recipes/vietnamese-caramel-trout', 'https://www.themealdb.com/images/media/meals/p02vq41763754350.jpg', 'Photo from TheMealDB'),
  ('53232', 'Vietnamese chicken salad', 'Vietnamese', '1. Whisk the lime juice, fish sauce, soy sauce, sesame oil and chopped chili into a dressing in a large serving bowl.
2. Cook the noodles as the package says, drain them and add them to the dressing.
3. Peel the carrot into long ribbons with a vegetable peeler, and the cucumber too, stopping at the seeds.
4. Add the carrot and cucumber to the noodles with the cooked, shredded chicken, the sliced radishes and red onion and the mint leaves. Toss well and scatter with the peanuts.', 20, 10, 3, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/vietnamese-chicken-salad', 'https://www.themealdb.com/images/media/meals/pk8wtn1763758591.jpg', 'Photo from TheMealDB'),
  ('52828', 'Vietnamese Grilled Pork (bun-thit-nuong)', 'Vietnamese', '1. Slice the pork very thinly, about 1/8 inch. It''s easier if you freeze it for a little while first.
2. Mix the minced garlic and shallots with the sugar, fish sauce, soy sauce, pepper and oil until the sugar dissolves. Marinate the pork in it for 1 hour, or overnight.
3. Heat the oven to 375°F (190°C). Bake the pork for 10 to 15 minutes, until almost cooked, then broil it until golden, turning halfway. Bake the egg rolls as the package says.
4. Meanwhile, cook the noodles as the package says and rinse them in cold water.
5. Fill bowls with the noodles, the pork, the sliced egg rolls, cucumber, mint and crushed peanuts.', 80, 25, 4, '$$', array[]::text[], 'http://www.hungryhuy.com/bun-thit-nuong-recipe-vietnamese-grilled-bbq-pork-with-rice-vermicelli-vegetables/', 'https://www.themealdb.com/images/media/meals/qqwypw1504642429.jpg', 'Photo from TheMealDB'),
  ('53231', 'Vietnamese lamb shanks with sweet potatoes', 'Vietnamese', '1. Heat the oven to 325°F (160°C). Heat 1 tbsp of the oil in a heavy casserole, season the shanks and brown them 2 at a time on all sides, adding the rest of the oil for the second batch. Set them aside.
2. Fry the sliced onions briskly for 30 seconds, add the grated ginger, garlic and 1 chopped chili, lower the heat and cook for 1 minute.
3. Stir in 2 tsp of the sugar, then add the star anise, bruised lemongrass, stock, tomato paste and seasoning. Return the lamb and bring to a boil.
4. Cover and cook in the oven for 1 1/2 hours, then add the sweet potatoes, cut into chunks, and cook for 1 hour more, until the lamb is almost falling off the bone.
5. Stir in the fish sauce, the lime juice and the rest of the sugar. Scatter with the mint, basil and the other chili, sliced.', 20, 180, 4, '$$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/vietnamese-lamb-shanks-sweet-potatoes', 'https://www.themealdb.com/images/media/meals/7xte3u1763757761.jpg', 'Photo from TheMealDB'),
  ('53236', 'Vietnamese-style veggie hotpot', 'Vietnamese', '1. Heat the oil in a medium saucepan with a lid and stir-fry the shredded ginger and sliced garlic for about 5 minutes.
2. Add the squash, cut into chunks, the soy sauce, sugar and broth. Cover and simmer for 10 minutes.
3. Uncover, add the green beans and cook for 3 minutes more, until the squash and beans are tender.
4. Stir in the sliced green onions at the last minute, sprinkle with cilantro and serve with rice.', 5, 20, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.bbcgoodfood.com/recipes/vietnamese-veggie-hotpot', 'https://www.themealdb.com/images/media/meals/4uje7l1763762276.jpg', 'Photo from TheMealDB'),
  ('53106', 'Warm roast asparagus salad', 'Australian', '1. Heat the oven to 400°F (200°C). Snap off the woody ends of the asparagus and lay it in a single layer in a baking pan with sides.
2. Halve the tomatoes and nestle them among the asparagus, season and drizzle with some of the olive oil. Roll up each bacon slice tightly and add it to the pan.
3. Drizzle the bacon with the honey and bake for 20 minutes, until the tomatoes are soft and the bacon crisp.
4. Meanwhile, boil the potatoes until tender. Whisk the vinegar, the rest of the oil, the mustard, salt and pepper in a large bowl.
5. Toss the arugula in half of the dressing and spread it on a platter. Halve the potatoes, toss them in the rest of the dressing and arrange them with the asparagus, tomatoes and bacon.', 20, 25, 4, '$$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/warm-roast-asparagus-salad', 'https://www.themealdb.com/images/media/meals/ktsws11761998344.jpg', 'Photo from TheMealDB'),
  ('52948', 'Wontons', 'Chinese', '1. Mix the ground pork with the minced garlic and ginger, the soy sauce, sesame oil and the finely chopped carrots, celery and green onions.
2. Separate the wonton wrappers. Put a heaped teaspoon of filling in the middle of each.
3. Brush water along 2 edges, fold the wrapper into a triangle and press to seal. Pinch the two long points together.
4. Heat oil for deep-frying to 375°F (190°C) and fry 4 or 5 at a time until golden. Drain and serve with a dipping sauce.', 30, 15, 6, '$', array[]::text[], 'http://www.geniuskitchen.com/recipe/chinese-wontons-20235', 'https://www.themealdb.com/images/media/meals/1525876468.jpg', 'Photo from TheMealDB'),
  ('53225', 'Yemeni Lahsa (Elite Shakshuka)', 'Saudi Arabian', '1. Heat the olive oil over medium heat and cook the diced onion until it softens.
2. Add the chopped tomato and cook for 4 to 5 minutes, then the allspice, a pinch of salt and the pepper.
3. Add the beaten eggs and stir for 2 minutes, then cover and cook for 5 to 6 minutes, until the top sets.
4. Spread the cheese over the top, cover for 1 minute more and serve.', 5, 15, 4, '$', array['vegetarian']::text[], 'https://cookpad.com/eng/recipes/24629321?ref=search&search_term=saudi+arabia', 'https://www.themealdb.com/images/media/meals/30s7vf1763741844.jpg', 'Photo from TheMealDB'),
  ('53294', 'Zapiekanki', 'Polish', '1. Heat the oven to 400°F (200°C). Bake the baguettes on a baking sheet for 8 to 10 minutes and let them cool.
2. Heat 2 tsp of the butter and 1 tsp of the oil in a pan over low heat and cook half of the onion, chopped, for 5 minutes. Add the sliced mushrooms, turn the heat to medium and cook for 5 to 10 minutes, until the liquid has gone. Add the garlic for 1 to 2 minutes, season and stir in the mayonnaise.
3. Halve the baguettes lengthwise, spread them with the mushroom mixture and sprinkle with the cheddar, ham, sliced sausage and mozzarella. Bake for 8 to 10 minutes, until golden.
4. Meanwhile, fry the rest of the onion, sliced, in the rest of the butter and oil for 5 minutes, until golden.
5. Top the baguettes with the onions, sliced pickles, chives and a drizzle of ketchup.', 20, 30, 4, '$', array[]::text[], 'https://www.bbcgoodfood.com/recipes/zapiekanki', 'https://www.themealdb.com/images/media/meals/72lmpt1764122511.jpg', 'Photo from TheMealDB'),
  ('53189', 'Zemiakové Placky', 'Slovak', '1. Peel and finely grate the potatoes, then squeeze out as much liquid as you can in a clean towel.
2. Mix them with the finely chopped onion, the minced garlic, eggs, flour, marjoram, salt and pepper into a thick batter.
3. Heat plenty of oil in a large frying pan over medium heat.
4. Spoon in portions of batter and flatten them into thin pancakes. Fry until golden and crisp on both sides.
5. Drain on paper towels and serve hot.', 20, 25, 4, '$', array['vegetarian']::text[], 'https://www.slovakia-foods.co.uk/blog/post/zemiakove-placky-recipe-how-to-make-authentic-slovak-potato-pancakes.html', 'https://www.themealdb.com/images/media/meals/0umm891763364625.jpg', 'Photo from TheMealDB')
) as v (themealdb_id, title, cuisine, instructions, prep_minutes, cook_minutes, base_servings,
        cost_bracket, diet_tags, source_url, image_url, image_credit)
where not exists (
  select 1 from public.recipes r where r.source_type = 'seed' and lower(r.title) = lower(v.title)
)
on conflict (themealdb_id) do nothing;

